INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('fe-Catch_and_Overhead_Throw', 'Catch and Overhead Throw', 'back', 'lats', '["abdominals","chest","shoulders"]', 'medicine ball', 'plyometrics', 'beginner', '["Begin standing while facing a wall or a partner.","Using both hands, position the ball behind your head, stretching as much as possible, and forcefully throw the ball forward.","Ensure that you follow your throw through, being prepared to receive your rebound from your throw. If you are throwing against the wall, make sure that you stand close enough to the wall to receive the rebound, and aim a little higher than you would with a partner."]', NULL, '["Catch_and_Overhead_Throw/0.jpg","Catch_and_Overhead_Throw/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Chain_Handle_Extension', 'Chain Handle Extension', 'upper arms', 'triceps', '[]', 'other', 'powerlifting', 'intermediate', '["You will need two cable handle attachments and a flat bench, as well as chains, for this exercise. Clip the middle of the chains to the handles, and position yourself on the flat bench. Your elbows should be pointing straight up.","Begin by extending through the elbow, keeping your upper arm still, with your wrists pronated.","Pause at the lockout, and reverse the motion to return to the starting position."]', NULL, '["Chain_Handle_Extension/0.jpg","Chain_Handle_Extension/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Chain_Press', 'Chain Press', 'chest', 'chest', '["shoulders","triceps"]', 'other', 'powerlifting', 'intermediate', '["Begin by connecting the chains to the cable handle attachments. Position yourself on the flat bench in the same position as for a dumbbell press. Your wrists should be pronated and arms perpendicular to the floor. This will be your starting position.","Lower the chains by flexing the elbows, unloading some of the chain onto the floor.","Continue until your elbow forms a 90 degree angle, and then reverse the motion by extending through the elbow to lockout."]', NULL, '["Chain_Press/0.jpg","Chain_Press/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Chair_Leg_Extended_Stretch', 'Chair Leg Extended Stretch', 'upper legs', 'hamstrings', '["adductors"]', 'other', 'stretching', 'beginner', '["Sit upright in a chair and grip the seat on the sides.","Raise one leg, extending the knee, flexing the ankle as you do so.","Slowly move that leg outward as far as you can, and then back to the center and down.","Repeat for your other leg."]', NULL, '["Chair_Leg_Extended_Stretch/0.jpg","Chair_Leg_Extended_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Chair_Lower_Back_Stretch', 'Chair Lower Back Stretch', 'back', 'lats', '["lower back"]', 'body only', 'stretching', 'beginner', '["Sit upright on a chair.","Bend to one side with your arm over your head. You can hold onto the chair with your free hand.","Hold for 10 seconds, and repeat for your other side."]', NULL, '["Chair_Lower_Back_Stretch/0.jpg","Chair_Lower_Back_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Chair_Squat', 'Chair Squat', 'upper legs', 'quadriceps', '["calves","glutes","hamstrings"]', 'machine', 'strength', 'beginner', '["To begin, first set the bar to a position that best matches your height. Once the bar is loaded, step under it and position it across the back of your shoulders.","Take the bar with your hands facing forward, unlock it and lift it off the rack by extending your legs.","Move your feet forward about 18 inches in front of the bar. Position your legs using a shoulder width stance with the toes slightly pointed out. Look forward at all times and maintain a neutral or slightly arched spine. This will be your starting position.","Slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper and lower leg breaks 90 degrees.","Begin to raise the bar as you exhale by pushing the floor with the heels of your feet, extending the knees and returning to the starting position.","Repeat for the recommended amount of repetitions."]', NULL, '["Chair_Squat/0.jpg","Chair_Squat/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Chair_Upper_Body_Stretch', 'Chair Upper Body Stretch', 'shoulders', 'shoulders', '["biceps","chest"]', 'other', 'stretching', 'beginner', '["Sit on the edge of a chair, gripping the back of it.","Straighten your arms, keeping your back straight, and pull your upper body forward so you feel a stretch. Hold for 20-30 seconds."]', NULL, '["Chair_Upper_Body_Stretch/0.jpg","Chair_Upper_Body_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Chest_And_Front_Of_Shoulder_Stretch', 'Chest And Front Of Shoulder Stretch', 'chest', 'chest', '["shoulders"]', 'other', 'stretching', 'beginner', '["Start off by standing with your legs together, holding a bodybar or a broomstick.","Take a slightly wider than shoulder width grip on the pole and hold it in front of you with your palms facing down.","Carefully lift the pole up and behind your head."]', NULL, '["Chest_And_Front_Of_Shoulder_Stretch/0.jpg","Chest_And_Front_Of_Shoulder_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Chest_Push_from_3_point_stance', 'Chest Push from 3 point stance', 'chest', 'chest', '["abdominals","shoulders","triceps"]', 'medicine ball', 'plyometrics', 'beginner', '["Begin in a three point stance, squatted down with your back flat and one hand on the ground. Place the medicine ball directly in front of you.","To begin, take your first step as you pull the ball to your chest, positioning both hands to prepare for the throw.","As you execute the second step, explosively release the ball forward as hard as possible."]', NULL, '["Chest_Push_from_3_point_stance/0.jpg","Chest_Push_from_3_point_stance/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Chest_Push_multiple_response', 'Chest Push (multiple response)', 'chest', 'chest', '["abdominals","shoulders","triceps"]', 'medicine ball', 'plyometrics', 'beginner', '["Begin in a kneeling position facing a wall or utilize a partner. Hold the ball with both hands tight into the chest.","Execute the pass by exploding forward and outward with the hips while pushing the ball as hard as possible.","Follow through by falling forward, catching yourself with your hands.","Immediately return to an upright position. Repeat for the desired number of repetitions."]', NULL, '["Chest_Push_multiple_response/0.jpg","Chest_Push_multiple_response/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Chest_Push_single_response', 'Chest Push (single response)', 'chest', 'chest', '["abdominals","shoulders","triceps"]', 'medicine ball', 'plyometrics', 'beginner', '["Begin in a kneeling position holding the medicine ball with both hands tightly into the chest.","Execute the pass by exploding forward and outward with the hips while pushing the ball as far as possible.","Follow through by falling forward, catching yourself with your hands."]', NULL, '["Chest_Push_single_response/0.jpg","Chest_Push_single_response/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Chest_Push_with_Run_Release', 'Chest Push with Run Release', 'chest', 'chest', '["abdominals","shoulders","triceps"]', 'medicine ball', 'plyometrics', 'beginner', '["Begin in an athletic stance with the knees bent, hips back, and back flat. Hold the medicine ball near your legs. This will be your starting position.","While taking your first step draw the medicine ball into your chest.","As you take the second step, explosively push the ball forward, immediately sprinting for 10 yards after the release. If you are really fast, you can catch your own pass!"]', NULL, '["Chest_Push_with_Run_Release/0.jpg","Chest_Push_with_Run_Release/1.jpg"]', 9.8, 'sets', 0, 'fedb', 1),
('fe-Chest_Stretch_on_Stability_Ball', 'Chest Stretch on Stability Ball', 'chest', 'chest', '[]', 'exercise ball', 'stretching', 'beginner', '["Get on your hands and knees next to an exercise ball.","Place your elbows on top of the ball, keeping your arm out to your side. This will be your starting position.","Lower your torso towards the floor, keeping your elbow on top of the ball. Hold the stretch for 20-30 seconds, and repeat with the other arm."]', NULL, '["Chest_Stretch_on_Stability_Ball/0.jpg","Chest_Stretch_on_Stability_Ball/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Childs_Pose', 'Child''s Pose', 'back', 'lower back', '["glutes","middle back"]', 'body only', 'stretching', 'beginner', '["Get on your hands and knees, walk your hands in front of you.","Lower your buttocks down to sit on your heels. Let your arms drag along the floor as you sit back to stretch your entire spine.","Once you settle onto your heels, bring your hands next to your feet and relax. \"breathe\" into your back. Rest your forehead on the floor. Avoid this position if you have knee problems."]', NULL, '["Childs_Pose/0.jpg","Childs_Pose/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Chin_To_Chest_Stretch', 'Chin To Chest Stretch', 'neck', 'neck', '["traps"]', 'body only', 'stretching', 'beginner', '["Get into a seated position on the floor.","Place both hands at the rear of your head, fingers interlocked, thumbs pointing down and elbows pointing straight ahead. Slowly pull your head down to your chest. Hold for 20-30 seconds."]', NULL, '["Chin_To_Chest_Stretch/0.jpg","Chin_To_Chest_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Circus_Bell', 'Circus Bell', 'shoulders', 'shoulders', '["forearms","glutes","hamstrings","lower back","traps","triceps"]', 'other', 'strongman', 'expert', '["The circus bell is an oversized dumbbell with a thick handle. Begin with the dumbbell between your feet, and grip the handle with both hands.","Clean the dumbbell by extending through your hips and knees to deliver the implement to the desired shoulder, letting go with the extra hand.","Ensure that you get one of the dumbbell heads behind the shoulder to keep from being thrown off balance. To raise it overhead, dip by flexing the knees, and the drive upwards as you extend the dumbbell overhead, leaning slightly away from it as you do so.","Carefully guide the bell back to the floor, keeping it under control as much as possible. It is best to perform this event on a thick rubber mat to prevent damage to the floor."]', NULL, '["Circus_Bell/0.jpg","Circus_Bell/1.jpg"]', 7, 'sets', 0, 'fedb', 1),
('fe-Clean', 'Clean', 'upper legs', 'hamstrings', '["calves","forearms","glutes","lower back","quadriceps","shoulders","traps"]', 'barbell', 'olympic weightlifting', 'intermediate', '["With a barbell on the floor close to the shins, take an overhand (or hook) grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.","","Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees.","Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.","As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.","Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position."]', NULL, '["Clean/0.jpg","Clean/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Clean_Deadlift', 'Clean Deadlift', 'upper legs', 'hamstrings', '["forearms","glutes","lower back","middle back","quadriceps","traps"]', 'barbell', 'olympic weightlifting', 'beginner', '["Begin standing with a barbell close to your shins. Your feet should be directly under your hips with your feet turned out slightly. Grip the bar with a double overhand grip or hook grip, about shoulder width apart. Squat down to the bar. Your spine should be in full extension, with a back angle that places your shoulders in front of the bar and your back as vertical as possible.","Begin by driving through the floor through the front of your heels. As the bar travels upward, maintain a constant back angle. Flare your knees out to the side to help keep them out of the bar''s path.","After the bar crosses the knees, complete the lift by driving the hips into the bar until your hips and knees are extended."]', NULL, '["Clean_Deadlift/0.jpg","Clean_Deadlift/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Clean_Pull', 'Clean Pull', 'upper legs', 'quadriceps', '["forearms","glutes","hamstrings","lower back","traps"]', 'barbell', 'olympic weightlifting', 'intermediate', '["With a barbell on the floor close to the shins, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.","Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight and elbows out. Move the weight with control as you continue to above the knees.","Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended. Full extension should be violent and abrupt, and ensure that you do not prolong the extension for longer than necessary."]', NULL, '["Clean_Pull/0.jpg","Clean_Pull/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Clean_Shrug', 'Clean Shrug', 'back', 'traps', '["forearms","shoulders"]', 'barbell', 'olympic weightlifting', 'beginner', '["Begin with a shoulder width, double overhand or hook grip, with the bar hanging at the mid thigh position. Your back should be straight and inclined slightly forward.","Shrug your shoulders towards your ears. While this exercise can usually by loaded with heavier weight than a clean, avoid overloading to the point that the execution slows down."]', NULL, '["Clean_Shrug/0.jpg","Clean_Shrug/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Clean_and_Jerk', 'Clean and Jerk', 'shoulders', 'shoulders', '["abdominals","glutes","hamstrings","lower back","quadriceps","traps","triceps"]', 'barbell', 'olympic weightlifting', 'expert', '["With a barbell on the floor close to the shins, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.","Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees.","Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.","As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.","Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position.","The second phase is the jerk, which raises the weight overhead. Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible.","Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders.","At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as possible. In the brief moment the feet are not actively driving against the platform, the athletes effort to push the bar up will drive them down. The feet should be split, with one foot forward, and one foot back. Receive the bar with the arms locked out overhead. Return to a standing position."]', NULL, '["Clean_and_Jerk/0.jpg","Clean_and_Jerk/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Clean_and_Press', 'Clean and Press', 'shoulders', 'shoulders', '["abdominals","calves","glutes","hamstrings","lower back","middle back","quadriceps","shoulders","traps","triceps"]', 'barbell', 'strength', 'intermediate', '["Assume a shoulder-width stance, with knees inside the arms. Now while keeping the back flat, bend at the knees and hips so that you can grab the bar with the arms fully extended and a pronated grip that is slightly wider than shoulder width. Point the elbows out to sides. The bar should be close to the shins. Position the shoulders over or slightly ahead of the bar. Establish a flat back posture. This will be your starting position.","Begin to pull the bar by extending the knees. Move your hips forward and raise the shoulders at the same rate while keeping the angle of the back constant; continue to lift the bar straight up while keeping it close to your body.","As the bar passes the knee, extend at the ankles, knees, and hips forcefully, similar to a jumping motion. As you do so, continue to guide the bar with your hands, shrugging your shoulders and using the momentum from your movement to pull the bar as high as possible. The bar should travel close to your body, and you should keep your elbows out.","At maximum elevation, your feet should clear the floor and you should start to pull yourself under the bar. The mechanics of this could change slightly, depending on the weight used. You should descend into a squatting position as you pull yourself under the bar.","As the bar hits terminal height, rotate your elbows around and under the bar. Rack the bar across the front of the shoulders while keeping the torso erect and flexing the hips and knees to absorb the weight of the bar.","Stand to full height, holding the bar in the clean position.","Without moving your feet, press the bar overhead as you exhale. Lower the bar under control ."]', NULL, '["Clean_and_Press/0.jpg","Clean_and_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Clean_from_Blocks', 'Clean from Blocks', 'upper legs', 'quadriceps', '["calves","glutes","hamstrings","shoulders","traps"]', 'barbell', 'olympic weightlifting', 'intermediate', '["With a barbell on boxes or stands of the desired height, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.","Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight with the elbows pointed out.","As full extension is achieved, transition into the receiving position by aggressively shrugging and flexing the arms with the elbows up and out. Aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.","Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position. Return the weight to the boxes for the next rep."]', NULL, '["Clean_from_Blocks/0.jpg","Clean_from_Blocks/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Close-Grip_EZ-Bar_Curl_with_Band', 'Close-Grip EZ-Bar Curl with Band', 'upper arms', 'biceps', '["forearms"]', 'e-z curl bar', 'strength', 'beginner', '["Attach a band to each end of the bar. Take the bar, placing a foot on the middle of the band. Stand upright with a narrow, supinated grip on the EZ bar. The elbows should be close to the torso. This will be your starting position.","While keeping the upper arms in place, flex the elbows to execute the curl. Exhale as the weight is lifted.","Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.","Slowly begin to bring the bar back to starting position as your breathe in.","Repeat for the recommended amount of repetitions."]', NULL, '["Close-Grip_EZ-Bar_Curl_with_Band/0.jpg","Close-Grip_EZ-Bar_Curl_with_Band/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Close-Grip_EZ-Bar_Press', 'Close-Grip EZ-Bar Press', 'upper arms', 'triceps', '["chest","shoulders"]', 'e-z curl bar', 'strength', 'beginner', '["Lie on a flat bench with an EZ bar loaded to an appropriate weight.","Using a narrow grip lift the bar and hold it straight over your torso with your elbows in. The arms should be perpendicular to the floor. This will be your starting position.","Now lower the bar down to your lower chest as you breathe in. Keep the elbows in as you perform this movement.","Using the triceps to push the bar back up, press it back to the starting position by extending the elbows as you exhale.","Repeat."]', NULL, '["Close-Grip_EZ-Bar_Press/0.jpg","Close-Grip_EZ-Bar_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('fe-Close-Grip_EZ_Bar_Curl', 'Close-Grip EZ Bar Curl', 'upper arms', 'biceps', '["forearms"]', 'barbell', 'strength', 'beginner', '["Stand up with your torso upright while holding an E-Z Curl Bar at the closer inner handle. The palm of your hands should be facing forward and they should be slightly tilted inwards due to the shape of the bar. The elbows should be close to the torso. This will be your starting position.","While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move.","Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.","Slowly begin to bring the bar back to starting position as your breathe in.","Repeat for the recommended amount of repetitions."]', NULL, '["Close-Grip_EZ_Bar_Curl/0.jpg","Close-Grip_EZ_Bar_Curl/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Close-Grip_Front_Lat_Pulldown', 'Close-Grip Front Lat Pulldown', 'back', 'lats', '["biceps","middle back","shoulders"]', 'cable', 'strength', 'beginner', '["Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.","Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.","As you have both arms extended in front of you - while holding the bar at the chosen grip width - bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.","As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary (only the arms should move). The forearms should do no other work except for holding the bar; therefore do not try to pull the bar down using the forearms.","After a second in the contracted position, while squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.","6. Repeat this motion for the prescribed amount of repetitions."]', NULL, '["Close-Grip_Front_Lat_Pulldown/0.jpg","Close-Grip_Front_Lat_Pulldown/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Close-Grip_Push-Up_off_of_a_Dumbbell', 'Close-Grip Push-Up off of a Dumbbell', 'upper arms', 'triceps', '["abdominals","chest","shoulders"]', 'body only', 'strength', 'intermediate', '["Lie on the floor and place your hands on an upright dumbbell. Supporting your weight on your toes and hands, keep your torso rigid and your elbows in with your arms straight. This will be your starting position.","Lower your body, allowing the elbows to flex while you inhale. Keep your body straight, not allowing your hips to rise or sag.","Press yourself back up to the starting position by extending the elbows. Breathe out as you perform this step.","After a pause at the contracted position, repeat the movement for the prescribed amount of repetitions."]', NULL, '["Close-Grip_Push-Up_off_of_a_Dumbbell/0.jpg","Close-Grip_Push-Up_off_of_a_Dumbbell/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Conans_Wheel', 'Conan''s Wheel', 'upper legs', 'quadriceps', '["abdominals","biceps","calves","forearms","lower back","shoulders","traps"]', 'other', 'strongman', 'intermediate', '["With the weight loaded, take a zurcher hold on the end of the implement. Place the bar in the crook of the elbow and hold onto your wrist. Try to keep the weight off of the forearms.","Begin by lifting the weight from the ground. Keep a tight, upright posture as you being to walk, taking short, fast steps. Look up and away as you turn in a circle. Do not hold your breath during the event. Continue walking until you complete one or more complete turns."]', NULL, '["Conans_Wheel/0.jpg","Conans_Wheel/1.jpg"]', 7, 'sets', 0, 'fedb', 1),
('fe-Concentration_Curls', 'Concentration Curls', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', 'beginner', '["Sit down on a flat bench with one dumbbell in front of you between your legs. Your legs should be spread with your knees bent and feet on the floor.","Use your right arm to pick the dumbbell up. Place the back of your right upper arm on the top of your inner right thigh. Rotate the palm of your hand until it is facing forward away from your thigh. Tip: Your arm should be extended and the dumbbell should be above the floor. This will be your starting position.","While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Tip: At the top of the movement make sure that the little finger of your arm is higher than your thumb. This guarantees a good contraction. Hold the contracted position for a second as you squeeze the biceps.","Slowly begin to bring the dumbbells back to starting position as your breathe in. Caution: Avoid swinging motions at any time.","Repeat for the recommended amount of repetitions. Then repeat the movement with the left arm."]', NULL, '["Concentration_Curls/0.jpg","Concentration_Curls/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Cross_Body_Hammer_Curl', 'Cross Body Hammer Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', 'beginner', '["Stand up straight with a dumbbell in each hand. Your hands should be down at your side with your palms facing in.","While keeping your palms facing in and without twisting your arm, curl the dumbbell of the right arm up towards your left shoulder as you exhale. Touch the top of the dumbbell to your shoulder and hold the contraction for a second.","Slowly lower the dumbbell along the same path as you inhale and then repeat the same movement for the left arm.","Continue alternating in this fashion until the recommended amount of repetitions is performed for each arm."]', NULL, '["Cross_Body_Hammer_Curl/0.jpg","Cross_Body_Hammer_Curl/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Cross_Over_-_With_Bands', 'Cross Over - With Bands', 'chest', 'chest', '["biceps","shoulders"]', 'bands', 'strength', 'beginner', '["Secure an exercise band around a stationary post.","While facing away from the post, grab the handles on both ends of the band and step forward enough to create tension on the band.","Raise your arms to the sides, parallel to the floor, perpendicular to your torso (your torso and the arms should resemble the letter \"T\") and with the palms facing forward. Have them extended with a slight bend at the elbows. This will be your starting position.","While keeping your arms straight, bring them across your chest in a semicircular motion to the front as you exhale and flex your pecs. Hold the contraction for a second.","Slowly return to the starting position as you inhale.","Perform for the recommended amount of repetitions."]', NULL, '["Cross_Over_-_With_Bands/0.jpg","Cross_Over_-_With_Bands/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Crossover_Reverse_Lunge', 'Crossover Reverse Lunge', 'back', 'lower back', '["abdominals","abductors","glutes","hamstrings","quadriceps"]', 'body only', 'stretching', 'intermediate', '["Stand with your feet shoulder width apart. This will be your starting position.","Perform a rear lunge by stepping back with one foot and flexing the hips and front knee. As you do so, rotate your torso across the front leg.","After a brief pause, return to the starting position and repeat on the other side, continuing in an alternating fashion."]', NULL, '["Crossover_Reverse_Lunge/0.jpg","Crossover_Reverse_Lunge/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Crucifix', 'Crucifix', 'shoulders', 'shoulders', '["forearms"]', 'other', 'strongman', 'beginner', '["In the crucifix, you statically hold weights out to the side for time. While the event can be practiced using dumbbells, it is best to practice with one of the various implements used, such as axes and hammers, as it feels different.","Begin standing, and raise your arms out to the side holding the implements. Your arms should be parallel to the ground. In competition, judges or sensors are used to let you know when you break parallel. Hold for as long as you can. Typically, the weights should be heavy enough that you fail in 30-60 seconds."]', NULL, '["Crucifix/0.jpg","Crucifix/1.jpg"]', 7, 'sets', 0, 'fedb', 1),
('fe-Crunch_-_Legs_On_Exercise_Ball', 'Crunch - Legs On Exercise Ball', 'waist', 'abdominals', '[]', 'body only', 'strength', 'beginner', '["Lie flat on your back with your feet resting on an exercise ball and your knees bent at a 90 degree angle.","Place your feet three to four inches apart and point your toes inward so they touch.","Place your hands lightly on either side of your head keeping your elbows in. Tip: Don''t lock your fingers behind your head.","Push the small of your back down in the floor in order to better isolate your abdominal muscles. This will be your starting position.","Begin to roll your shoulders off the floor and continue to push down as hard as you can with your lower back. Your shoulders should come up off the floor only about four inches, and your lower back should remain on the floor. Breathe out as you execute this portion of the movement. Squeeze your abdominals hard at the top of the contraction and hold for a second. Tip: Focus on a slow, controlled movement. Refrain from using momentum at any time.","Slowly go back down to the starting position as you inhale.","Repeat for the recommended amount of repetitions."]', NULL, '["Crunch_-_Legs_On_Exercise_Ball/0.jpg","Crunch_-_Legs_On_Exercise_Ball/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Crunches', 'Crunches', 'waist', 'abdominals', '[]', 'body only', 'strength', 'beginner', '["Lie flat on your back with your feet flat on the ground, or resting on a bench with your knees bent at a 90 degree angle. If you are resting your feet on a bench, place them three to four inches apart and point your toes inward so they touch.","Now place your hands lightly on either side of your head keeping your elbows in. Tip: Don''t lock your fingers behind your head.","While pushing the small of your back down in the floor to better isolate your abdominal muscles, begin to roll your shoulders off the floor.","Continue to push down as hard as you can with your lower back as you contract your abdominals and exhale. Your shoulders should come up off the floor only about four inches, and your lower back should remain on the floor. At the top of the movement, contract your abdominals hard and keep the contraction for a second. Tip: Focus on slow, controlled movement - don''t cheat yourself by using momentum.","After the one second contraction, begin to come down slowly again to the starting position as you inhale.","Repeat for the recommended amount of repetitions."]', NULL, '["Crunches/0.jpg","Crunches/1.jpg"]', 5, 'sets', 1, 'fedb', 1),
('fe-Cuban_Press', 'Cuban Press', 'shoulders', 'shoulders', '["traps"]', 'dumbbell', 'strength', 'intermediate', '["Take a dumbbell in each hand with a pronated grip in a standing position. Raise your upper arms so that they are parallel to the floor, allowing your lower arms to hang in the \"scarecrow\" position. This will be your starting position.","To initiate the movement, externally rotate the shoulders to move the upper arm 180 degrees. Keep the upper arms in place, rotating the upper arms until the wrists are directly above the elbows, the forearms perpendicular to the floor.","Now press the dumbbells by extending at the elbows, straightening your arms overhead.","Return to the starting position as you breathe in by reversing the steps.","Repeat for the recommended amount of repetitions."]', NULL, '["Cuban_Press/0.jpg","Cuban_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Dancers_Stretch', 'Dancer''s Stretch', 'back', 'lower back', '["abductors","glutes"]', 'body only', 'stretching', 'beginner', '["Sit up on the floor.","Cross your right leg over your left, keeping the knee bent. Your left leg is straight and down on the floor.","Place your left arm on your right leg and your right hand on the floor.","Rotate your upper body to the right, and hold for 10-20 seconds. Switch sides."]', NULL, '["Dancers_Stretch/0.jpg","Dancers_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Deadlift_with_Bands', 'Deadlift with Bands', 'back', 'lower back', '["forearms","glutes","hamstrings","middle back","quadriceps","traps"]', 'barbell', 'powerlifting', 'expert', '["To deadlift with short bands, simply loop them over the bar before you start, and step into them to set up. For long bands, they will need to be anchored to a secure base, such as heavy dumbbells or a rack.","With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.","Lower the bar by bending at the hips and guiding it to the floor."]', NULL, '["Deadlift_with_Bands/0.jpg","Deadlift_with_Bands/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Deadlift_with_Chains', 'Deadlift with Chains', 'back', 'lower back', '["forearms","glutes","hamstrings","middle back","quadriceps","traps"]', 'barbell', 'powerlifting', 'expert', '["You can attach the chains to the sleeves of the bar, or just drape the middle over the bar so there is a greater weight increase as you lift.","Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip on heavier sets. With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar.","Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.","Lower the bar by bending at the hips and guiding it to the floor."]', NULL, '["Deadlift_with_Chains/0.jpg","Deadlift_with_Chains/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Decline_Close-Grip_Bench_To_Skull_Crusher', 'Decline Close-Grip Bench To Skull Crusher', 'upper arms', 'triceps', '["chest","shoulders"]', 'barbell', 'strength', 'intermediate', '["Secure your legs at the end of the decline bench and slowly lay down on the bench.","Using a close grip (a grip that is slightly less than shoulder width), lift the bar from the rack and hold it straight over you with your arms locked and elbows in. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack.","Now lower the bar down to your lower chest as you breathe in. Keep the elbows in as you perform this movement.","Using the triceps to push the bar back up, press it back to the starting position as you exhale.","As you breathe in and you keep the upper arms stationary, bring the bar down slowly by moving your forearms in a semicircular motion towards you until you feel the bar slightly touch your forehead. Breathe in as you perform this portion of the movement.","Lift the bar back to the starting position by contracting the triceps and exhaling.","Repeat steps 3-6 until the recommended amount of repetitions is performed."]', NULL, '["Decline_Close-Grip_Bench_To_Skull_Crusher/0.jpg","Decline_Close-Grip_Bench_To_Skull_Crusher/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Decline_Dumbbell_Flyes', 'Decline Dumbbell Flyes', 'chest', 'chest', '[]', 'dumbbell', 'strength', 'beginner', '["Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.","Once you are laying down, move the dumbbells in front of you at shoulder width. The palms of the hands should be facing each other and the arms should be perpendicular to the floor and fully extended. This will be your starting position.","With a slight bend on your elbows in order to prevent stress at the biceps tendon, lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary; the movement should only occur at the shoulder joint.","Return your arms back to the starting position as you squeeze your chest muscles and breathe out. Tip: Make sure to use the same arc of motion used to lower the weights.","Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions."]', NULL, '["Decline_Dumbbell_Flyes/0.jpg","Decline_Dumbbell_Flyes/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Decline_EZ_Bar_Triceps_Extension', 'Decline EZ Bar Triceps Extension', 'upper arms', 'triceps', '[]', 'barbell', 'strength', 'beginner', '["Secure your legs at the end of the decline bench and slowly lay down on the bench.","Using a close grip (a grip that is slightly less than shoulder width), lift the EZ bar from the rack and hold it straight over you with your arms locked and elbows in. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack.","As you breathe in and you keep the upper arms stationary, bring the bar down slowly by moving your forearms in a semicircular motion towards you until you feel the bar slightly touch your forehead. Breathe in as you perform this portion of the movement.","Lift the bar back to the starting position by contracting the triceps and exhaling.","Repeat until the recommended amount of repetitions is performed."]', NULL, '["Decline_EZ_Bar_Triceps_Extension/0.jpg","Decline_EZ_Bar_Triceps_Extension/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Decline_Oblique_Crunch', 'Decline Oblique Crunch', 'waist', 'abdominals', '[]', 'body only', 'strength', 'beginner', '["Secure your legs at the end of the decline bench and slowly lay down on the bench.","Raise your upper body off the bench until your torso is about 35-45 degrees if measured from the floor.","Put one hand beside your head and the other on your thigh. This will be your starting position.","Raise your upper body slowly from the starting position while turning your torso to the left. Continue crunching up as you exhale until your right elbow touches your left knee. Hold this contracted position for a second. Tip: Focus on keeping your abs tight and keeping the movement slow and controlled.","Lower your body back down slowly to the starting position as you inhale.","After completing one set on the right for the recommended amount of repetitions, switch to your left side. Tip: Focus on really twisting your torso and feeling the contraction when you are in the up position."]', NULL, '["Decline_Oblique_Crunch/0.jpg","Decline_Oblique_Crunch/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Decline_Push-Up', 'Decline Push-Up', 'chest', 'chest', '["shoulders","triceps"]', 'body only', 'strength', 'beginner', '["Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length. Move your feet up to a box or bench. This will be your starting position.","Next, lower yourself downward until your chest almost touches the floor as you inhale.","Now breathe out and press your upper body back up to the starting position while squeezing your chest.","After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed."]', NULL, '["Decline_Push-Up/0.jpg","Decline_Push-Up/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Decline_Reverse_Crunch', 'Decline Reverse Crunch', 'waist', 'abdominals', '[]', 'body only', 'strength', 'beginner', '["Lie on your back on a decline bench and hold on to the top of the bench with both hands. Don''t let your body slip down from this position.","Hold your legs parallel to the floor using your abs to hold them there while keeping your knees and feet together. Tip: Your legs should be fully extended with a slight bend on the knee. This will be your starting position.","While exhaling, move your legs towards the torso as you roll your pelvis backwards and you raise your hips off the bench. At the end of this movement your knees will be touching your chest.","Hold the contraction for a second and move your legs back to the starting position while inhaling.","Repeat for the recommended amount of repetitions."]', NULL, '["Decline_Reverse_Crunch/0.jpg","Decline_Reverse_Crunch/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Decline_Smith_Press', 'Decline Smith Press', 'chest', 'chest', '["shoulders","triceps"]', 'machine', 'strength', 'beginner', '["Place a decline bench underneath the Smith machine. Now place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Using a pronated grip that is wider than shoulder width, unlock the bar from the rack and hold it straight over you with your arms extended. This will be your starting position.","As you inhale, lower the bar under control by allowing the elbows to flex, lightly contacting the torso.","After a brief pause, bring the bar back to the starting position by extending the elbows, exhaling as you do so.","Repeat the movement for the prescribed amount of repetitions.","When the set is complete, lock the bar back in the rack."]', NULL, '["Decline_Smith_Press/0.jpg","Decline_Smith_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Deficit_Deadlift', 'Deficit Deadlift', 'back', 'lower back', '["forearms","glutes","hamstrings","middle back","quadriceps","traps"]', 'barbell', 'powerlifting', 'intermediate', '["Begin by having a platform or weight plates that you can stand on, usually 1-3 inches in height. Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip on heavier sets.","With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.","Lower the bar by bending at the hips and guiding it to the floor."]', NULL, '["Deficit_Deadlift/0.jpg","Deficit_Deadlift/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Depth_Jump_Leap', 'Depth Jump Leap', 'upper legs', 'quadriceps', '["abductors","adductors","calves","glutes","hamstrings"]', 'other', 'plyometrics', 'beginner', '["For this drill you will need two boxes or benches, one 12 to 16 inches high and the other 22 to 26 inches high.","Stand on one of the two boxes with arms at the sides; feet should be together and slightly off the edge as in the depth jump. Place the other box approximately two or three feet in front of and facing the performer.","Begin by dropping off the initial box, landing and simultaneously taking off with both feet.","Rebound by driving upward and outward as intensely as possible, using the arms and full extension of the body to jump onto the higher box. Again, allow the legs to absorb the impact."]', NULL, '["Depth_Jump_Leap/0.jpg","Depth_Jump_Leap/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Dip_Machine', 'Dip Machine', 'upper arms', 'triceps', '["chest","shoulders"]', 'machine', 'strength', 'beginner', '["Sit securely in a dip machine, select the weight and firmly grasp the handles.","Now keep your elbows in at your sides in order to place emphasis on the triceps. The elbows should be bent at a 90 degree angle.","As you contract the triceps, extend your arms downwards as you exhale. Tip: At the bottom of the movement, focus on keeping a little bend in your arms to keep tension on the triceps muscle.","Now slowly let your arms come back up to the starting position as you inhale.","Repeat for the recommended amount of repetitions."]', NULL, '["Dip_Machine/0.jpg","Dip_Machine/1.jpg"]', 5, 'sets', 0, 'fedb', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('fe-Dips_-_Chest_Version', 'Dips - Chest Version', 'chest', 'chest', '["shoulders","triceps"]', 'other', 'strength', 'intermediate', '["For this exercise you will need access to parallel bars. To get yourself into the starting position, hold your body at arms length (arms locked) above the bars.","While breathing in, lower yourself slowly with your torso leaning forward around 30 degrees or so and your elbows flared out slightly until you feel a slight stretch in the chest.","Once you feel the stretch, use your chest to bring your body back to the starting position as you breathe out. Tip: Remember to squeeze the chest at the top of the movement for a second.","Repeat the movement for the prescribed amount of repetitions."]', NULL, '["Dips_-_Chest_Version/0.jpg","Dips_-_Chest_Version/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Donkey_Calf_Raises', 'Donkey Calf Raises', 'lower legs', 'calves', '[]', 'other', 'strength', 'intermediate', '["For this exercise you will need access to a donkey calf raise machine. Start by positioning your lower back and hips under the padded lever provided. The tailbone area should be the one making contact with the pad.","Place both of your arms on the side handles and place the balls of your feet on the calf block with the heels extending off. Align the toes forward, inward or outward, depending on the area you wish to target, and straighten the knees without locking them. This will be your starting position.","Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.","Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.","Repeat for the recommended amount of repetitions."]', NULL, '["Donkey_Calf_Raises/0.jpg","Donkey_Calf_Raises/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Double_Leg_Butt_Kick', 'Double Leg Butt Kick', 'upper legs', 'quadriceps', '["abductors","adductors","calves","glutes","hamstrings"]', 'body only', 'plyometrics', 'beginner', '["Begin standing with your knees slightly bent.","Quickly squat a short distance, flexing the hips and knees, and immediately extend to jump for maximum vertical height.","As you go up, tuck your heels by flexing the knees, attempting to touch the buttocks.","Finish the motion by landing with the knees only partially bent, using your legs to absorb the impact."]', NULL, '["Double_Leg_Butt_Kick/0.jpg","Double_Leg_Butt_Kick/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Downward_Facing_Balance', 'Downward Facing Balance', 'upper legs', 'glutes', '["abdominals","hamstrings"]', 'exercise ball', 'strength', 'intermediate', '["Lie facedown on top of an exercise ball.","While resting on your stomach on the ball, walk your hands forward along the floor and lift your legs, extending your elbows and knees."]', NULL, '["Downward_Facing_Balance/0.jpg","Downward_Facing_Balance/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Drag_Curl', 'Drag Curl', 'upper arms', 'biceps', '["forearms"]', 'barbell', 'strength', 'intermediate', '["Grab a barbell with a supinated grip (palms facing forward) and get your elbows close to your torso and back. This will be your starting position.","As you exhale, curl the bar up while keeping the elbows to the back as you \"Drag\" the bar up by keeping it in contact with your torso. Tip: As you can see, you will not be keeping the elbows pinned to your sides, but instead you will be bringing them back. Also, do not lift your shoulders.","Slowly go back to the starting position as you keep the bar in contact with the torso at all times.","Repeat for the recommended amount of repetitions."]', NULL, '["Drag_Curl/0.jpg","Drag_Curl/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Drop_Push', 'Drop Push', 'chest', 'chest', '["shoulders","triceps"]', 'other', 'plyometrics', 'intermediate', '["Position low boxes or other platforms 2-3 feet apart.","Move to a pushup position between them, supporting yourself by placing your hands on the boxes.","With good posture, drop from the platforms by pressing up and moving your hands to shoulder width, cushioning your landing by absorbing the impact through the arm."]', NULL, '["Drop_Push/0.jpg","Drop_Push/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Dumbbell_Bicep_Curl', 'Dumbbell Bicep Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', 'beginner', '["Stand up straight with a dumbbell in each hand at arm''s length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position.","Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps.","Then, inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the recommended amount of repetitions."]', NULL, '["Dumbbell_Bicep_Curl/0.jpg","Dumbbell_Bicep_Curl/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Dumbbell_Floor_Press', 'Dumbbell Floor Press', 'upper arms', 'triceps', '["chest","shoulders"]', 'dumbbell', 'powerlifting', 'intermediate', '["Lay on the floor holding dumbbells in your hands. Your knees can be bent. Begin with the weights fully extended above you.","Lower the weights until your upper arm comes in contact with the floor. You can tuck your elbows to emphasize triceps size and strength, or to focus on your chest angle your arms to the side.","Pause at the bottom, and then bring the weight together at the top by extending through the elbows."]', NULL, '["Dumbbell_Floor_Press/0.jpg","Dumbbell_Floor_Press/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Dumbbell_Flyes', 'Dumbbell Flyes', 'chest', 'chest', '[]', 'dumbbell', 'strength', 'beginner', '["Lie down on a flat bench with a dumbbell on each hand resting on top of your thighs. The palms of your hand will be facing each other.","Then using your thighs to help raise the dumbbells, lift the dumbbells one at a time so you can hold them in front of you at shoulder width with the palms of your hands facing each other. Raise the dumbbells up like you''re pressing them, but stop and hold just before you lock out. This will be your starting position.","With a slight bend on your elbows in order to prevent stress at the biceps tendon, lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary; the movement should only occur at the shoulder joint.","Return your arms back to the starting position as you squeeze your chest muscles and breathe out. Tip: Make sure to use the same arc of motion used to lower the weights.","Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions."]', NULL, '["Dumbbell_Flyes/0.jpg","Dumbbell_Flyes/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Dumbbell_One-Arm_Triceps_Extension', 'Dumbbell One-Arm Triceps Extension', 'upper arms', 'triceps', '[]', 'dumbbell', 'strength', 'intermediate', '["Grab a dumbbell and either sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs or stand up straight.","Clean the dumbbell up to bring it to shoulder height and then extend the arm over your head so that the whole arm is perpendicular to the floor and next to your head. The dumbbell should be on top of you. The other hand can be kept fully extended to the side, by the waist, supporting the upper arm that has the dumbbell or grabbing a fixed surface.","Rotate the wrist so that the palm of your hand is facing forward and the pinkie is facing the ceiling. This will be your starting position.","Slowly lower the dumbbell behind your head as you hold the upper arm stationary. Inhale as you perform this movement and pause when your triceps are fully stretched.","Return to the starting position by flexing your triceps as you breathe out. Tip: It is imperative that only the forearm moves. The upper arm should remain at all times stationary next to your head.","Repeat for the recommended amount of repetitions and switch arms."]', NULL, '["Dumbbell_One-Arm_Triceps_Extension/0.jpg","Dumbbell_One-Arm_Triceps_Extension/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Dumbbell_Scaption', 'Dumbbell Scaption', 'shoulders', 'shoulders', '["traps"]', 'dumbbell', 'strength', 'beginner', '["This corrective exercise strengthens the muscles that stabilize your shoulder blade. Hold a light weight in each hand, hanging at your sides. Your thumbs should pointing up.","Begin the movement raising your arms out in front of you, about 30 degrees off center. Your arms should be fully extended as you perform the movement.","Continue until your arms are parallel to the ground, and then return to the starting position."]', NULL, '["Dumbbell_Scaption/0.jpg","Dumbbell_Scaption/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Dumbbell_Seated_Box_Jump', 'Dumbbell Seated Box Jump', 'upper legs', 'quadriceps', '["calves","glutes","hamstrings"]', 'dumbbell', 'plyometrics', 'intermediate', '["Position a box a couple feet to the side of a bench. Hold a dumbbell to your chest with both hands and seat yourself on the bench facing the box. This will be your starting position.","Plant your feet firmly on the ground as you lean forward, extending through the hips and knees to jump up and forward.","Land on the box with both feet, absorbing the impact by allowing the hips and knees to bend.","Step down and return to the starting position."]', NULL, '["Dumbbell_Seated_Box_Jump/0.jpg","Dumbbell_Seated_Box_Jump/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Dumbbell_Shoulder_Press', 'Dumbbell Shoulder Press', 'shoulders', 'shoulders', '["triceps"]', 'dumbbell', 'strength', 'intermediate', '["While holding a dumbbell in each hand, sit on a military press bench or utility bench that has back support. Place the dumbbells upright on top of your thighs.","Now raise the dumbbells to shoulder height one at a time using your thighs to help propel them up into position.","Make sure to rotate your wrists so that the palms of your hands are facing forward. This is your starting position.","Now, exhale and push the dumbbells upward until they touch at the top.","Then, after a brief pause at the top contracted position, slowly lower the weights back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions."]', NULL, '["Dumbbell_Shoulder_Press/0.jpg","Dumbbell_Shoulder_Press/1.jpg"]', 5, 'sets', 1, 'fedb', 1),
('fe-Dumbbell_Tricep_Extension_-Pronated_Grip', 'Dumbbell Tricep Extension -Pronated Grip', 'upper arms', 'triceps', '[]', 'dumbbell', 'strength', 'beginner', '["Lie down on a flat bench holding two dumbbells directly above your shoulders. Your arms should be fully extended and form a 90 degree angle from your torso and the floor.","The palms of your hands should be facing forward, and your elbows should be tucked in. This will be your starting position.","Now, inhale and slowly lower the dumbbells until they are near your ears. Be sure to keep your upper arms stationary and your elbows tucked in.","Then, exhale and use your triceps to return the weight to the starting position."]', NULL, '["Dumbbell_Tricep_Extension_-Pronated_Grip/0.jpg","Dumbbell_Tricep_Extension_-Pronated_Grip/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Dynamic_Back_Stretch', 'Dynamic Back Stretch', 'back', 'lats', '[]', 'body only', 'stretching', 'beginner', '["Stand with your feet shoulder width apart. This will be your starting position.","Keeping your arms straight, swing them straight up in front of you 5-10 times, increasing the range of motion each time until your arms are above your head."]', NULL, '["Dynamic_Back_Stretch/0.jpg","Dynamic_Back_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Dynamic_Chest_Stretch', 'Dynamic Chest Stretch', 'chest', 'chest', '["middle back"]', 'body only', 'stretching', 'beginner', '["Stand with your hands together, arms extended directly in front of you. This will be your starting position.","Keeping your arms straight, quickly move your arms back as far as possible and back in again, similar to an exaggerated clapping motion. Repeat 5-10 times, increasing speed as you do so."]', NULL, '["Dynamic_Chest_Stretch/0.jpg","Dynamic_Chest_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-EZ-Bar_Curl', 'EZ-Bar Curl', 'upper arms', 'biceps', '[]', 'e-z curl bar', 'strength', 'beginner', '["Stand up straight while holding an EZ curl bar at the wide outer handle. The palms of your hands should be facing forward and slightly tilted inward due to the shape of the bar. Keep your elbows close to your torso. This will be your starting position.","Now, while keeping your upper arms stationary, exhale and curl the weights forward while contracting the biceps. Focus on only moving your forearms.","Continue to raise the weight until your biceps are fully contracted and the bar is at shoulder level. Hold the top contracted position for a moment and squeeze the biceps.","Then inhale and slowly lower the bar back to the starting position.","Repeat for the recommended amount of repetitions."]', NULL, '["EZ-Bar_Curl/0.jpg","EZ-Bar_Curl/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-EZ-Bar_Skullcrusher', 'EZ-Bar Skullcrusher', 'upper arms', 'triceps', '["forearms"]', 'e-z curl bar', 'strength', 'beginner', '["Using a close grip, lift the EZ bar and hold it with your elbows in as you lie on the bench. Your arms should be perpendicular to the floor. This will be your starting position.","Keeping the upper arms stationary, lower the bar by allowing the elbows to flex. Inhale as you perform this portion of the movement. Pause once the bar is directly above the forehead.","Lift the bar back to the starting position by extending the elbow and exhaling.","Repeat."]', NULL, '["EZ-Bar_Skullcrusher/0.jpg","EZ-Bar_Skullcrusher/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Elbow_Circles', 'Elbow Circles', 'shoulders', 'shoulders', '["traps"]', 'body only', 'stretching', 'beginner', '["Sit or stand with your feet slightly apart.","Place your hands on your shoulders with your elbows at shoulder level and pointing out.","Slowly make a circle with your elbows. Breathe out as you start the circle and breathe in as you complete the circle."]', NULL, '["Elbow_Circles/0.jpg","Elbow_Circles/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Elbows_Back', 'Elbows Back', 'chest', 'chest', '["shoulders"]', 'body only', 'stretching', 'beginner', '["Stand up straight.","Place both hands on your lower back, fingers pointing downward and elbows out.","Then gently pull your elbows back aiming to touch them together."]', NULL, '["Elbows_Back/0.jpg","Elbows_Back/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Elevated_Back_Lunge', 'Elevated Back Lunge', 'upper legs', 'quadriceps', '["glutes","hamstrings"]', 'barbell', 'strength', 'intermediate', '["Position a bar onto a rack at shoulder height loaded to an appropriate weight. Place a short, raised platform behind you.","Rack the bar onto your upper back, keeping your back arched and tight. Step onto your raised platform with both feet. This will be your starting position.","Begin by stepping backwards with one leg. Descend by flexing your hips and knees until your knee touches the floor.","Pause, and extend through the hips and knees to rise up, returning all the way to the starting position before alternating."]', NULL, '["Elevated_Back_Lunge/0.jpg","Elevated_Back_Lunge/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Elevated_Cable_Rows', 'Elevated Cable Rows', 'back', 'lats', '["middle back","traps"]', 'cable', 'strength', 'intermediate', '["Get a platform of some sort (it can be an aerobics or calf raise platform) that is around 4-6 inches in height.","Place it on the seat of the cable row machine.","Sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.","Lean over as you keep the natural alignment of your back and grab the V-bar handles.","With your arms extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lats as you hold the bar in front of you. This is the starting position of the exercise.","Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it until you touch the abdominals. Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard. Hold that contraction for a second and slowly go back to the original position while breathing in.","Repeat for the recommended amount of repetitions."]', NULL, '["Elevated_Cable_Rows/0.jpg","Elevated_Cable_Rows/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Elliptical_Trainer', 'Elliptical Trainer', 'cardio', 'quadriceps', '["calves","glutes","hamstrings"]', 'machine', 'cardio', 'intermediate', '["To begin, step onto the elliptical and select the desired option from the menu. Most ellipticals have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout.","The handles can be used to monitor your heart rate to help you stay at an appropriate intensity."]', NULL, '["Elliptical_Trainer/0.jpg","Elliptical_Trainer/1.jpg"]', 5, 'time', 1, 'fedb', 1),
('fe-Exercise_Ball_Crunch', 'Exercise Ball Crunch', 'waist', 'abdominals', '[]', 'exercise ball', 'strength', 'beginner', '["Lie on an exercise ball with your lower back curvature pressed against the spherical surface of the ball. Your feet should be bent at the knee and pressed firmly against the floor. The upper torso should be hanging off the top of the ball. The arms should either be kept alongside the body or crossed on top of your chest as these positions avoid neck strains (as opposed to the hands behind the back of the head position).","Lower your torso into a stretch position keeping the neck stationary at all times. This will be your starting position.","With the hips stationary, flex the waist by contracting the abdominals and curl the shoulders and trunk upward until you feel a nice contraction on your abdominals. The arms should simply slide up the side of your legs if you have them at the side or just stay on top of your chest if you have them crossed. The lower back should always stay in contact with the ball. Exhale as you perform this movement and hold the contraction for a second.","As you inhale, go back to the starting position.","Repeat for the recommended amount of repetitions."]', NULL, '["Exercise_Ball_Crunch/0.jpg","Exercise_Ball_Crunch/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Exercise_Ball_Pull-In', 'Exercise Ball Pull-In', 'waist', 'abdominals', '[]', 'exercise ball', 'strength', 'beginner', '["Place an exercise ball nearby and lay on the floor in front of it with your hands on the floor shoulder width apart in a push-up position.","Now place your lower shins on top of an exercise ball. Tip: At this point your legs should be fully extended with the shins on top of the ball and the upper body should be in a push-up type of position being supported by your two extended arms in front of you. This will be your starting position.","While keeping your back completely straight and the upper body stationary, pull your knees in towards your chest as you exhale, allowing the ball to roll forward under your ankles. Squeeze your abs and hold that position for a second.","Now slowly straighten your legs, rolling the ball back to the starting position as you inhale.","Repeat for the recommended amount of repetitions."]', NULL, '["Exercise_Ball_Pull-In/0.jpg","Exercise_Ball_Pull-In/1.jpg"]', 5, 'sets', 0, 'fedb', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('fe-External_Rotation', 'External Rotation', 'shoulders', 'shoulders', '[]', 'dumbbell', 'strength', 'beginner', '["Lie sideways on a flat bench with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it.","Bend the elbows of the arm holding the dumbbell so that it creates a 90-degree angle between the upper arm and the forearm. Tip: Keep the arm parallel to your torso.","Now bend the elbow while keeping the upper arm stationary. In this manner, the forearm will be parallel to the floor and perpendicular to your torso (Tip: So the forearm will be directly in front of you). The upper arm will be stationary by your torso and should be parallel to the floor (aligned with your torso at all times). This will be your starting position.","As you breathe out, externally rotate your forearm so that the dumbbell is lifted up in a semicircle motion as you maintain the 90 degree angle bend between the upper arms and the forearm. You will continue this external rotation until the forearm is perpendicular to the floor and the torso pointing towards the ceiling. At this point you will hold the contraction for a second.","As you breathe in, slowly go back to the starting position.","Repeat for the recommended amount of repetitions and then switch to the other arm."]', NULL, '["External_Rotation/0.jpg","External_Rotation/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-External_Rotation_with_Band', 'External Rotation with Band', 'shoulders', 'shoulders', '[]', 'bands', 'strength', 'beginner', '["Choke the band around a post. The band should be at the same height as your elbow. Stand with your left side to the band a couple of feet away.","Grasp the end of the band with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position.","With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching across the front of your torso. This will be your starting position.","Execute the movement by rotating your arm in a backhand motion, keeping your elbow in place.","Continue as far as you are able, pause, and then return to the starting position."]', NULL, '["External_Rotation_with_Band/0.jpg","External_Rotation_with_Band/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-External_Rotation_with_Cable', 'External Rotation with Cable', 'shoulders', 'shoulders', '[]', 'cable', 'strength', 'beginner', '["Adjust the cable to the same height as your elbow. Stand with your left side to the band a couple of feet away.","Grasp the handle with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position.","With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching across the front of your torso. This will be your starting position.","Execute the movement by rotating your arm in a backhand motion, keeping your elbow in place."]', NULL, '["External_Rotation_with_Cable/0.jpg","External_Rotation_with_Cable/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Face_Pull', 'Face Pull', 'shoulders', 'shoulders', '["middle back"]', 'cable', 'strength', 'intermediate', '["Facing a high pulley with a rope or dual handles attached, pull the weight directly towards your face, separating your hands as you do so. Keep your upper arms parallel to the ground."]', NULL, '["Face_Pull/0.jpg","Face_Pull/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Farmers_Walk', 'Farmer''s Walk', 'lower arms', 'forearms', '["abdominals","glutes","hamstrings","lower back","quadriceps","traps"]', 'other', 'strongman', 'intermediate', '["There are various implements that can be used for the farmers walk. These can also be performed with heavy dumbbells or short bars if these implements aren''t available. Begin by standing between the implements.","After gripping the handles, lift them up by driving through your heels, keeping your back straight and your head up.","Walk taking short, quick steps, and don''t forget to breathe. Move for a given distance, typically 50-100 feet, as fast as possible."]', NULL, '["Farmers_Walk/0.jpg","Farmers_Walk/1.jpg"]', 3.5, 'sets', 0, 'fedb', 1),
('fe-Fast_Skipping', 'Fast Skipping', 'upper legs', 'quadriceps', '["abductors","adductors","calves","glutes","hamstrings"]', 'body only', 'plyometrics', 'beginner', '["Start in a relaxed position with one leg slightly forward. This will be your starting position.","Skip by executing a step-hop pattern of right-right-step to left-left-step, and so on, alternating back and forth.","Perform fast skips by maintaining close contact with the ground and reduce air time, moving as quickly as possible."]', NULL, '["Fast_Skipping/0.jpg","Fast_Skipping/1.jpg"]', 11, 'sets', 0, 'fedb', 1),
('fe-Flat_Bench_Cable_Flyes', 'Flat Bench Cable Flyes', 'chest', 'chest', '[]', 'cable', 'strength', 'intermediate', '["Position a flat bench between two low pulleys so that when you are laying on it, your chest will be lined up with the cable pulleys.","Lay flat on the bench and keep your feet on the ground.","Have someone hand you the handles on each hand. You will grab each single handle attachment with a palms up grip.","Extend your arms by your side with a slight bend on your elbows. Tip: You will keep this bend constant through the whole movement. Your arms should be parallel to the floor. This is your starting position.","Now start lifting the arms in a semi-circle motion directly in front of you by pulling the cables together until both hands meet at the top of the movement. Squeeze your chest as you perform this motion and breathe out during this movement. Also, hold the contraction for a second at the top. Tip: When performed correctly, at the top position of this movement, your arms should be perpendicular to your torso and the floor touching above your chest.","Slowly come back to the starting position.","Repeat for the recommended amount of repetitions."]', NULL, '["Flat_Bench_Cable_Flyes/0.jpg","Flat_Bench_Cable_Flyes/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Flexor_Incline_Dumbbell_Curls', 'Flexor Incline Dumbbell Curls', 'upper arms', 'biceps', '[]', 'dumbbell', 'strength', 'beginner', '["Hold the dumbbell towards the side farther from you so that you have more weight on the side closest to you. (This can be done for a good effect on all bicep dumbbell exercises). Now do a normal incline dumbbell curl, but keep your wrists as far back as possible so as to neutralize any stress that is placed on them.","Sit on an incline bench that is angled at 45-degrees while holding a dumbbell on each hand.","Let your arms hang down on your sides, with the elbows in, and turn the palms of your hands forward with the thumbs pointing away from the body. Tip: You will keep this hand position throughout the movement as there should not be any twisting of the hands as they come up. This will be your starting position.","Curl up the two dumbbells at the same time until your biceps are fully contracted and exhale. Tip: Do not swing the arms or use momentum. Keep a controlled motion at all times. Hold the contracted position for a second at the top.","As you inhale, slowly go back to the starting position.","Repeat for the recommended amount of repetitions."]', NULL, '["Flexor_Incline_Dumbbell_Curls/0.jpg","Flexor_Incline_Dumbbell_Curls/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Floor_Glute-Ham_Raise', 'Floor Glute-Ham Raise', 'upper legs', 'hamstrings', '["calves","glutes"]', 'body only', 'strength', 'intermediate', '["You can use a partner for this exercise or brace your feet under something stable.","Begin on your knees with your upper legs and torso upright. If using a partner, they will firmly hold your feet to keep you in position. This will be your starting position.","Lower yourself by extending at the knee, taking care to NOT flex the hips as you go forward.","Place your hands in front of you as you reach the floor. This movement is very difficult and you may be unable to do it unaided. Use your arms to lightly push off the floor to aid your return to the starting position."]', NULL, '["Floor_Glute-Ham_Raise/0.jpg","Floor_Glute-Ham_Raise/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Floor_Press', 'Floor Press', 'upper arms', 'triceps', '["chest","shoulders"]', 'barbell', 'powerlifting', 'intermediate', '["Adjust the j-hooks so they are at the appropriate height to rack the bar. Begin lying on the floor with your head near the end of a power rack. Keeping your shoulder blades pulled together; pull the bar off of the hooks.","Lower the bar towards the bottom of your chest or upper stomach, squeezing the bar and attempting to pull it apart as you do so. Ensure that you tuck your elbows throughout the movement. Lower the bar until your upper arm contacts the ground and pause, preventing any slamming or bouncing of the weight.","Press the bar back up as fast as you can, keeping the bar, your wrists, and elbows in line as you do so."]', NULL, '["Floor_Press/0.jpg","Floor_Press/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Floor_Press_with_Chains', 'Floor Press with Chains', 'upper arms', 'triceps', '["chest","shoulders"]', 'barbell', 'powerlifting', 'intermediate', '["Adjust the j-hooks so they are at the appropriate height to rack the bar. For this exercise, drape the chains directly over the end of the bar, trying to keep the ends away from the plates.","Begin lying on the floor with your head near the end of a power rack. Keeping your shoulder blades pulled together, pull the bar off of the hooks.","Lower the bar towards the bottom of your chest or upper stomach, squeezing the bar and attempting to pull it apart as you do so. Ensure that you tuck your elbows throughout the movement. Lower the bar until your upper arm contacts the ground and pause, preventing any slamming or bouncing of the weight.","Press the bar back up as fast as you can, keeping the bar, your wrists, and elbows in line as you do so."]', NULL, '["Floor_Press_with_Chains/0.jpg","Floor_Press_with_Chains/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Foot-SMR', 'Foot-SMR', 'lower legs', 'calves', '[]', 'other', 'stretching', 'intermediate', '["This exercise stretches the fascia of the muscles in the feet. Start off seated with your shoes removed. Using a foot roller or a similar object, such as a small section of pvc pipe, place your foot against the roller across the arch of your foot. This will be your starting position.","Press down firmly, rolling across the arch of your foot. Hold for 10-30 seconds, and then switch feet."]', NULL, '["Foot-SMR/0.jpg","Foot-SMR/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Forward_Drag_with_Press', 'Forward Drag with Press', 'chest', 'chest', '["calves","glutes","hamstrings","quadriceps","shoulders","triceps"]', 'other', 'strongman', 'intermediate', '["Attach a dual handled chain or rope attachment to the sled. You should be facing away from the sled, holding a handle in each hand.","Begin the movement by moving forward for one step. Leaning forward, extend through the legs and hips to move, pausing with each step to extend through the elbows, pressing your hands forward. Step forward until you return to the start position prepared to press."]', NULL, '["Forward_Drag_with_Press/0.jpg","Forward_Drag_with_Press/1.jpg"]', 7, 'sets', 0, 'fedb', 1),
('fe-Freehand_Jump_Squat', 'Freehand Jump Squat', 'upper legs', 'quadriceps', '["calves","glutes","hamstrings"]', 'body only', 'strength', 'intermediate', '["Cross your arms over your chest.","With your head up and your back straight, position your feet at shoulder width.","Keeping your back straight and chest up, squat down as you inhale until your upper thighs are parallel, or lower, to the floor.","Now pressing mainly with the ball of your feet, jump straight up in the air as high as possible, using the thighs like springs. Exhale during this portion of the movement.","When you touch the floor again, immediately squat down and jump again.","Repeat for the recommended amount of repetitions."]', NULL, '["Freehand_Jump_Squat/0.jpg","Freehand_Jump_Squat/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Frog_Hops', 'Frog Hops', 'upper legs', 'quadriceps', '["calves","glutes","hamstrings"]', 'body only', 'stretching', 'intermediate', '["Stand with your hands behind your head, and squat down keeping your torso upright and your head up. This will be your starting position.","Jump forward several feet, avoiding jumping unnecessarily high. As your feet contact the ground, absorb the impact through your legs, and jump again. Repeat this action 5-10 times."]', NULL, '["Frog_Hops/0.jpg","Frog_Hops/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Frog_Sit-Ups', 'Frog Sit-Ups', 'waist', 'abdominals', '[]', 'body only', 'strength', 'intermediate', '["Lie with your back flat on the floor (or exercise mat) and your legs extended in front of you.","Now bend at the knees and place your outer thighs by the floor (or mat) as you make the soles of your feet touch each other.","Now try pushing both soles and bringing them up as near you as possible while you keep the outer thighs on the floor (or at least almost touching it). Tip: In this position your legs should create a diamond shape.","Now, cross your arms in front of you by touching the opposite shoulders. This will be your starting position.","As you exhale flatten your lower back to the floor while curling the torso upwards. Tip: This will be like performing the first 1/4 movement of a sit up. Hold at the top position for a second.","As you inhale, slowly lower back to the starting position.","Repeat for the recommended amount of repetitions."]', NULL, '["Frog_Sit-Ups/0.jpg","Frog_Sit-Ups/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Front_Box_Jump', 'Front Box Jump', 'upper legs', 'hamstrings', '["abductors","adductors","calves","glutes","quadriceps"]', 'other', 'plyometrics', 'beginner', '["Begin with a box of an appropriate height 1-2 feet in front of you. Stand with your feet should width apart. This will be your starting position.","Perform a short squat in preparation for jumping, swinging your arms behind you.","Rebound out of this position, extending through the hips, knees, and ankles to jump as high as possible. Swing your arms forward and up.","Land on the box with the knees bent, absorbing the impact through the legs. You can jump from the box back to the ground, or preferably step down one leg at a time."]', NULL, '["Front_Box_Jump/0.jpg","Front_Box_Jump/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Front_Cone_Hops_or_hurdle_hops', 'Front Cone Hops (or hurdle hops)', 'upper legs', 'quadriceps', '["abductors","adductors","calves","glutes","hamstrings"]', 'other', 'plyometrics', 'beginner', '["Set up a row of cones or other small barriers, placing them a few feet apart.","Stand in front of the first cone with your feet shoulder width apart. This will be your starting position.","Begin by jumping with both feet over the first cone, swinging both arms as you jump.","Absorb the impact of landing by bending the knees, rebounding out of the first leap by jumping over the next cone.","Continue until you have jumped over all of the cones."]', NULL, '["Front_Cone_Hops_or_hurdle_hops/0.jpg","Front_Cone_Hops_or_hurdle_hops/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Front_Incline_Dumbbell_Raise', 'Front Incline Dumbbell Raise', 'shoulders', 'shoulders', '[]', 'dumbbell', 'strength', 'beginner', '["Sit down on an incline bench with the incline set anywhere between 30 to 60 degrees while holding a dumbbell on each hand. Tip: You can change the angle to hit the muscle a little differently each time.","Extend your arms straight in front of you and have your palms facing down with the dumbbells raised about 1 inch above your thighs. This will be your starting position.","Slowly raise the dumbbells straight up until they are slightly above your shoulders, while keeping your elbows locked. Squeeze at the top for a second and make sure you breathe out during this portion of the movement. Tip: Keep your head resting down against the bench and your legs on the floor at all times.","Lower the arms back to the starting position as you inhale.","Repeat for the recommended amount of repetitions."]', NULL, '["Front_Incline_Dumbbell_Raise/0.jpg","Front_Incline_Dumbbell_Raise/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Front_Leg_Raises', 'Front Leg Raises', 'upper legs', 'hamstrings', '[]', 'body only', 'stretching', 'beginner', '["Stand next to a chair or other support, holding on with one hand.","Swing your leg forward, keeping the leg straight. Continue with a downward swing, bringing the leg as far back as your flexibility allows. Repeat 5-10 times, and then switch legs."]', NULL, '["Front_Leg_Raises/0.jpg","Front_Leg_Raises/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Front_Plate_Raise', 'Front Plate Raise', 'shoulders', 'shoulders', '[]', 'other', 'strength', 'intermediate', '["While standing straight, hold a barbell plate in both hands at the 3 and 9 o''clock positions. Your palms should be facing each other and your arms should be extended and locked with a slight bend at the elbows and the plate should be down near your waist in front of you as far as you can go. Tip: The arms will remain in this position throughout the exercise. This will be your starting position.","Slowly raise the plate as you exhale until it is a little above shoulder level. Hold the contraction for a second. Tip: make sure that you do not swing the weight or bend at the elbows. Your torso should remain stationary throughout the movement as well.","As you inhale, slowly lower the plate back down to the starting position.","Repeat for the recommended amount of repetitions."]', NULL, '["Front_Plate_Raise/0.jpg","Front_Plate_Raise/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Front_Raise_And_Pullover', 'Front Raise And Pullover', 'chest', 'chest', '["lats","shoulders","triceps"]', 'barbell', 'strength', 'beginner', '["Lie on a flat bench while holding a barbell using a palms down grip that is about 15 inches apart.","Place the bar on your upper thighs, extend your arms and lock them while keeping a slight bend on the elbows. This will be your starting position.","Now raise the weight using a semicircular motion and keeping your arms straight as you inhale. Continue the same movement until the bar is on the other side above your head . (Tip: the bar will travel approximately 180-degrees). At this point your arms should be parallel to the floor with the palms of your hands facing the ceiling.","Now return the barbell to the starting position by reversing the motion as you exhale.","Repeat for the recommended amount of repetitions."]', NULL, '["Front_Raise_And_Pullover/0.jpg","Front_Raise_And_Pullover/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Front_Squat_Clean_Grip', 'Front Squat (Clean Grip)', 'upper legs', 'quadriceps', '["abdominals","glutes","hamstrings"]', 'barbell', 'strength', 'intermediate', '["To begin, first set the bar in a rack slightly below shoulder level. Rest the bar on top of the deltoids, pushing into the clavicles, and lightly touching the throat. Your hands should be in a clean grip, touching the bar only with your fingers to help keep it in position.","Lift the bar off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head and elbows up at all times. This will be your starting position.","Bend at the knees, sitting down between your legs. Continue down until your hamstrings are on your calves. Keep your knees aligned with your feet by consciously using your abductors to push your knees out as you squat.","Begin to raise the bar as you exhale by pushing the floor mainly with the heel or middle of your foot as you straighten the legs again and return to the starting position."]', NULL, '["Front_Squat_Clean_Grip/0.jpg","Front_Squat_Clean_Grip/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Front_Squats_With_Two_Kettlebells', 'Front Squats With Two Kettlebells', 'upper legs', 'quadriceps', '["calves","glutes"]', 'kettlebells', 'strength', 'intermediate', '["Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so.","Looking straight ahead at all times, squat as low as you can and pause at the bottom. As you squat down, push your knees out. You should squat between your legs, keeping an upright torso, with your head and chest up.","Rise back up by driving through your heels and repeat."]', NULL, '["Front_Squats_With_Two_Kettlebells/0.jpg","Front_Squats_With_Two_Kettlebells/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Front_Two-Dumbbell_Raise', 'Front Two-Dumbbell Raise', 'shoulders', 'shoulders', '[]', 'dumbbell', 'strength', 'beginner', '["Pick a couple of dumbbells and stand with a straight torso and the dumbbells on front of your thighs at arms length with the palms of the hand facing your thighs. This will be your starting position.","While maintaining the torso stationary (no swinging), lift the dumbbells to the front with a slight bend on the elbow and the palms of the hands always facing down. Continue to go up until you arms are slightly above parallel to the floor. Exhale as you execute this portion of the movement and pause for a second at the top.","As you inhale, lower the dumbbells back down slowly to the starting position.","Repeat for the recommended amount of repetitions."]', NULL, '["Front_Two-Dumbbell_Raise/0.jpg","Front_Two-Dumbbell_Raise/1.jpg"]', 5, 'sets', 0, 'fedb', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('fe-Full_Range-Of-Motion_Lat_Pulldown', 'Full Range-Of-Motion Lat Pulldown', 'back', 'lats', '["biceps","middle back","shoulders"]', 'cable', 'strength', 'intermediate', '["Either standing or seated on a high bench, grasp two stirrup cables that are attached to the high pulleys. Grab with the opposing hand so your arms are crisscrossed about you and your palms are facing forward.","Keeping your chest up and maintaining a slight arch in your lower back, pull the handles down as if you were doing a regular pulldown. The range of motion will be more of an arc. During the movement, rotate your hands so that in the bottom position your palms face each other rather than forward. Return slowly to the starting position and repeat."]', NULL, '["Full_Range-Of-Motion_Lat_Pulldown/0.jpg","Full_Range-Of-Motion_Lat_Pulldown/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Gironda_Sternum_Chins', 'Gironda Sternum Chins', 'back', 'lats', '["biceps","middle back"]', 'other', 'strength', 'intermediate', '["Grasp the pull-up bar with a shoulder width underhand grip.","Now hang with your arms fully extended and stick your chest out and lean back. Tip: You will be leaning back throughout the entire movement. This will be your starting position.","Start pulling yourself towards the bar with your spine arched throughout the movement and your head leaning back as far away from the bar as possible. Exhale as you perform this portion of the movement. Tip: At the upper end of the movement, your hips and legs will be at about a 45-degree angle to the floor.","Keep pulling until your collarbone passes the bar and your lower chest or sternum area touches it. Hold that contraction for a second. Tip: By the time you''ve completed this portion of the movement; your head will be parallel to the floor.","Slowly start going back to the starting position as you inhale.","Repeat for the recommended amount of repetitions."]', NULL, '["Gironda_Sternum_Chins/0.jpg","Gironda_Sternum_Chins/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Glute_Ham_Raise', 'Glute Ham Raise', 'upper legs', 'hamstrings', '["calves","glutes"]', 'machine', 'powerlifting', 'intermediate', '["Begin by adjusting the equipment to fit your body. Place your feet against the footplate in between the rollers as you lie facedown. Your knees should be just behind the pad.","Start from the bottom of the movement. Keep your back arched as you begin the movement by flexing the knees. Drive your toes into the foot plate as you do so. Keep your upper body straight, and continue until your body is upright.","Return to the starting position, keeping your descent under control."]', NULL, '["Glute_Ham_Raise/0.jpg","Glute_Ham_Raise/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Glute_Kickback', 'Glute Kickback', 'upper legs', 'glutes', '["hamstrings"]', 'body only', 'strength', 'beginner', '["Kneel on the floor or an exercise mat and bend at the waist with your arms extended in front of you (perpendicular to the torso) in order to get into a kneeling push-up position but with the arms spaced at shoulder width. Your head should be looking forward and the bend of the knees should create a 90-degree angle between the hamstrings and the calves. This will be your starting position.","As you exhale, lift up your right leg until the hamstrings are in line with the back while maintaining the 90-degree angle bend. Contract the glutes throughout this movement and hold the contraction at the top for a second. Tip: At the end of the movement the upper leg should be parallel to the floor while the calf should be perpendicular to it.","Go back to the initial position as you inhale and now repeat with the left leg.","Continue to alternate legs until all of the recommended repetitions have been performed."]', NULL, '["Glute_Kickback/0.jpg","Glute_Kickback/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Goblet_Squat', 'Goblet Squat', 'upper legs', 'quadriceps', '["calves","glutes","hamstrings","shoulders"]', 'kettlebells', 'strength', 'beginner', '["Stand holding a light kettlebell by the horns close to your chest. This will be your starting position.","Squat down between your legs until your hamstrings are on your calves. Keep your chest and head up and your back straight.","At the bottom position, pause and use your elbows to push your knees out. Return to the starting position, and repeat for 10-20 repetitions."]', NULL, '["Goblet_Squat/0.jpg","Goblet_Squat/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Good_Morning', 'Good Morning', 'upper legs', 'hamstrings', '["abdominals","glutes","lower back"]', 'barbell', 'powerlifting', 'intermediate', '["Begin with a bar on a rack at shoulder height. Rack the bar across the rear of your shoulders as you would a power squat, not on top of your shoulders. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Step back from the rack.","Begin by bending at the hips, moving them back as you bend over to near parallel. Keep your back arched and your cervical spine in proper alignment.","Reverse the motion by extending through the hips with your glutes and hamstrings. Continue until you have returned to the starting position."]', NULL, '["Good_Morning/0.jpg","Good_Morning/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Good_Morning_off_Pins', 'Good Morning off Pins', 'upper legs', 'hamstrings', '["abdominals","glutes","lower back"]', 'barbell', 'powerlifting', 'intermediate', '["Begin with a bar on a rack at about the same height as your stomach. Bend over underneath the bar and rack the bar across the rear of your shoulders as you would a power squat, not on top of your shoulders. At the proper height, you should be near parallel to the floor when bent over. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Keep your back arched and your cervical spine in proper alignment.","Begin the motion by extending through the hips with your glutes and hamstrings, and you are standing with the weight. Slowly lower the weight back to the pins returning to the starting position."]', NULL, '["Good_Morning_off_Pins/0.jpg","Good_Morning_off_Pins/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Gorilla_Chin_Crunch', 'Gorilla Chin/Crunch', 'waist', 'abdominals', '["biceps","lats"]', 'body only', 'strength', 'intermediate', '["Hang from a chin-up bar using an underhand grip (palms facing you) that is slightly wider than shoulder width.","Now bend your knees at a 90 degree angle so that the calves are parallel to the floor while the thighs remain perpendicular to it. This will be your starting position.","As you exhale, pull yourself up while crunching your knees up at the same time until your knees are at chest level. You will stop going up as soon as your nose is at the same level as the bar. Tip: When you get to this point you should also be finishing the crunch at the same time.","Slowly start to inhale as you return to the starting position.","Repeat for the recommended amount of repetitions."]', NULL, '["Gorilla_Chin_Crunch/0.jpg","Gorilla_Chin_Crunch/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Groin_and_Back_Stretch', 'Groin and Back Stretch', 'upper legs', 'adductors', '[]', 'body only', 'stretching', 'intermediate', '["Sit on the floor with your knees bent and feet together.","Interlock your fingers behind your head. This will be your starting position.","Curl downwards, bringing your elbows to the inside of your thighs. After a brief pause, return to the starting position with your head up and your back straight. Repeat for 10-20 repetitions."]', NULL, '["Groin_and_Back_Stretch/0.jpg","Groin_and_Back_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Groiners', 'Groiners', 'upper legs', 'adductors', '[]', 'body only', 'stretching', 'intermediate', '["Begin in a pushup position on the floor. This will be your starting position.","Using both legs, jump forward landing with your feet next to your hands. Keep your head up as you do so.","Return to the starting position and immediately repeat the movement, continuing for 10-20 repetitions."]', NULL, '["Groiners/0.jpg","Groiners/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Hack_Squat', 'Hack Squat', 'upper legs', 'quadriceps', '["calves","glutes","hamstrings"]', 'machine', 'strength', 'beginner', '["Place the back of your torso against the back pad of the machine and hook your shoulders under the shoulder pads provided.","Position your legs in the platform using a shoulder width medium stance with the toes slightly pointed out. Tip: Keep your head up at all times and also maintain the back on the pad at all times.","Place your arms on the side handles of the machine and disengage the safety bars (which on most designs is done by moving the side handles from a facing front position to a diagonal position).","Now straighten your legs without locking the knees. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).","Begin to slowly lower the unit by bending the knees as you maintain a straight posture with the head up (back on the pad at all times). Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the unit as you exhale by pushing the floor with mainly with the heel of your foot as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."]', NULL, '["Hack_Squat/0.jpg","Hack_Squat/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Hammer_Curls', 'Hammer Curls', 'upper arms', 'biceps', '[]', 'dumbbell', 'strength', 'beginner', '["Stand up with your torso upright and a dumbbell on each hand being held at arms length. The elbows should be close to the torso.","The palms of the hands should be facing your torso. This will be your starting position.","Now, while holding your upper arm stationary, exhale and curl the weight forward while contracting the biceps. Continue to raise the weight until the biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a brief moment as you squeeze the biceps. Tip: Focus on keeping the elbow stationary and only moving your forearm.","After the brief pause, inhale and slowly begin the lower the dumbbells back down to the starting position.","Repeat for the recommended amount of repetitions."]', NULL, '["Hammer_Curls/0.jpg","Hammer_Curls/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Hammer_Grip_Incline_DB_Bench_Press', 'Hammer Grip Incline DB Bench Press', 'chest', 'chest', '["shoulders","triceps"]', 'dumbbell', 'strength', 'beginner', '["Lie back on an incline bench with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.","By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them at shoulder width.","Once at shoulder width, keep the palms of your hands with a neutral grip (palms facing each other). Keep your elbows flared out with the upper arms in line with the shoulders (perpendicular to the torso) and the elbows bent creating a 90-degree angle between the upper arm and the forearm. This will be your starting position.","Now bring down the weights slowly to your side as you breathe in. Keep full control of the dumbbells at all times.","As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the dumbbells back in your thighs and then on the floor. This is the safest manner to dispose of the dumbbells."]', NULL, '["Hammer_Grip_Incline_DB_Bench_Press/0.jpg","Hammer_Grip_Incline_DB_Bench_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Hamstring-SMR', 'Hamstring-SMR', 'upper legs', 'hamstrings', '[]', 'foam roll', 'stretching', 'beginner', '["In a seated position, extend your legs over a foam roll so that it is position on the back of the upper legs. Place your hands to the side or behind you to help support your weight. This will be your starting position.","Using your hands, lift your hips off of the floor and shift your weight on the foam roll to one leg. Relax the hamstrings of the leg you are stretching.","Roll over the foam from below the hip to above the back of the knee, pausing at points of tension for 10-30 seconds. Repeat for the other leg."]', NULL, '["Hamstring-SMR/0.jpg","Hamstring-SMR/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Hamstring_Stretch', 'Hamstring Stretch', 'upper legs', 'hamstrings', '[]', 'body only', 'stretching', 'beginner', '["Lie on your back with one leg extended above you, with the hip at ninety degrees. Keep the other leg flat on the floor.","Loop a belt, band, or rope over the ball of your foot. This will be your starting position.","Pull on the belt to create tension in the calves and hamstrings. Hold this stretch for 10-30 seconds, and repeat with the other leg."]', NULL, '["Hamstring_Stretch/0.jpg","Hamstring_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Hang_Clean', 'Hang Clean', 'upper legs', 'quadriceps', '["calves","forearms","glutes","hamstrings","lower back","shoulders","traps"]', 'barbell', 'olympic weightlifting', 'intermediate', '["Begin with a shoulder width, double overhand or hook grip, with the bar hanging at the mid thigh position. Your back should be straight and inclined slightly forward.","Begin by aggressively extending through the hips, knees and ankles, driving the weight upward. As you do so, shrug your shoulders towards your ears.","Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position."]', NULL, '["Hang_Clean/0.jpg","Hang_Clean/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Hang_Clean_-_Below_the_Knees', 'Hang Clean - Below the Knees', 'upper legs', 'quadriceps', '["calves","forearms","glutes","hamstrings","lower back","shoulders","traps"]', 'barbell', 'olympic weightlifting', 'intermediate', '["Begin with a shoulder width, double overhand or hook grip, with the bar hanging just below the knees. Your back should be straight and inclined slightly forward.","Begin by aggressively extending through the hips, knees and ankles, driving the weight upward. As you do so, shrug your shoulders towards your ears. As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out.","At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.","Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position."]', NULL, '["Hang_Clean_-_Below_the_Knees/0.jpg","Hang_Clean_-_Below_the_Knees/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Hang_Snatch', 'Hang Snatch', 'upper legs', 'hamstrings', '["abdominals","calves","forearms","glutes","lower back","quadriceps","shoulders","traps"]', 'barbell', 'olympic weightlifting', 'expert', '["Begin with a wide grip on the bar, with an overhand or hook grip. The feet should be directly below the hips with the feet turned out. Your knees should be slightly bent, and the torso inclined forward. The spine should be fully extended and the head facing forward. The bar should be at the hips. This will be your starting position.","Aggressively extend through the legs and hips. At peak extension, shrug the shoulders and allow the elbows to flex to the side.","As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. Receive the bar with your body as low as possible and the arms fully extended overhead.","Return to a standing position with the weight overhead. Follow by returning the weight to the ground under control."]', NULL, '["Hang_Snatch/0.jpg","Hang_Snatch/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Hang_Snatch_-_Below_Knees', 'Hang Snatch - Below Knees', 'upper legs', 'hamstrings', '["abdominals","calves","forearms","glutes","lower back","quadriceps","shoulders","traps"]', 'barbell', 'olympic weightlifting', 'expert', '["Begin with a wide grip on the bar, with an overhand or hook grip. The feet should be directly below the hips with the feet turned out. Your knees should be slightly bent, and the torso inclined forward. The spine should be fully extended and the head facing forward. The bar should be just below the knees. This will be your starting position.","Aggressively extend through the legs and hips. At peak extension, shrug the shoulders and allow the elbows to flex to the side.","As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. Receive the bar with your body as low as possible and the arms fully extended overhead.","Return to a standing position with the weight overhead, and then return the weight to the floor under control."]', NULL, '["Hang_Snatch_-_Below_Knees/0.jpg","Hang_Snatch_-_Below_Knees/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Hanging_Bar_Good_Morning', 'Hanging Bar Good Morning', 'upper legs', 'hamstrings', '["abdominals","glutes","lower back"]', 'barbell', 'powerlifting', 'intermediate', '["Begin with a bar on a rack at about the same height as your stomach. Suspend the bar using chains or suspension straps.","Bend over underneath the bar and rack the bar across the rear of your shoulders as you would a power squat, not on top of your traps. At the proper height, you should be near parallel to the floor when bent over. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Keep your back arched and your cervical spine in proper alignment.","Begin the motion by extending through the hips with your glutes and hamstrings, and you are standing with the weight.","Slowly lower the weight back to the starting position, where it is supported by the chains."]', NULL, '["Hanging_Bar_Good_Morning/0.jpg","Hanging_Bar_Good_Morning/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Heaving_Snatch_Balance', 'Heaving Snatch Balance', 'upper legs', 'quadriceps', '["abdominals","forearms","glutes","hamstrings","shoulders","triceps"]', 'barbell', 'olympic weightlifting', 'intermediate', '["This drill helps you learn the snatch. Begin by holding a light weight across the back of the shoulders. Your feet should be slightly wider than hip width apart with the feet turned out, the same position that you would perform a squat with.","Begin by dipping with the knees slightly, and popping back up to briefly unload the bar. Drive yourself underneath the bar, elevating it overhead as you descend into a full squat.","Return to a standing position."]', NULL, '["Heaving_Snatch_Balance/0.jpg","Heaving_Snatch_Balance/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Heavy_Bag_Thrust', 'Heavy Bag Thrust', 'chest', 'chest', '["abdominals","shoulders","triceps"]', 'other', 'plyometrics', 'beginner', '["Utilize a heavy bag for this exercise. Assume an upright stance next to the bag, with your feet staggered, fairly wide apart. Place your hand on the bag at about chest height. This will be your starting position.","Begin by twisting at the waist, pushing the bag forward as hard as possible. Perform this move quickly, pushing the bag away from your body.","Receive the bag as it swings back by reversing these steps."]', NULL, '["Heavy_Bag_Thrust/0.jpg","Heavy_Bag_Thrust/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-High_Cable_Curls', 'High Cable Curls', 'upper arms', 'biceps', '[]', 'cable', 'strength', 'intermediate', '["Stand between a couple of high pulleys and grab a handle in each arm. Position your upper arms in a way that they are parallel to the floor with the palms of your hands facing you. This will be your starting position.","Curl the handles towards you until they are next to your ears. Make sure that as you do so you flex your biceps and exhale. The upper arms should remain stationary and only the forearms should move. Hold for a second in the contracted position as you squeeze the biceps.","Slowly bring back the arms to the starting position.","Repeat for the recommended amount of repetitions."]', NULL, '["High_Cable_Curls/0.jpg","High_Cable_Curls/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Hip_Circles_prone', 'Hip Circles (prone)', 'upper legs', 'abductors', '["adductors"]', 'body only', 'stretching', 'beginner', '["Position yourself on your hands and knees on the ground. Maintaining good posture, raise one bent knee off of the ground. This will be your starting position.","Keeping the knee in a bent position, rotate the femur in an arc, attempting to make a big circle with your knee.","Perform this slowly for a number of repetitions, and repeat on the other side."]', NULL, '["Hip_Circles_prone/0.jpg","Hip_Circles_prone/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Hip_Extension_with_Bands', 'Hip Extension with Bands', 'upper legs', 'glutes', '["hamstrings"]', 'bands', 'strength', 'beginner', '["Secure one end of the band to the lower portion of a post and attach the other to one ankle.","Facing the attachment point of the band, hold on to the column to stabilize yourself.","Keeping your head and your chest up, move the resisted leg back as far as you can while keeping the knee straight.","Return the leg to the starting position."]', NULL, '["Hip_Extension_with_Bands/0.jpg","Hip_Extension_with_Bands/1.jpg"]', 5, 'sets', 0, 'fedb', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('fe-Hip_Flexion_with_Band', 'Hip Flexion with Band', 'upper legs', 'quadriceps', '[]', 'bands', 'strength', 'beginner', '["Secure one end of the band to the lower portion of a post and attach the other to one ankle.","Face away from the attachment point of the band.","Keeping your head and your chest up, raise your knee up to 90 degrees and pause.","Return the leg to the starting position."]', NULL, '["Hip_Flexion_with_Band/0.jpg","Hip_Flexion_with_Band/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Hug_Knees_To_Chest', 'Hug Knees To Chest', 'back', 'lower back', '["glutes"]', 'body only', 'stretching', 'beginner', '["Lie down on your back and pull both knees up to your chest.","Hold your arms under the knees, not over (that would put to much pressure on your knee joints).","Slowly pull the knees toward your shoulders. This also stretches your buttocks muscles."]', NULL, '["Hug_Knees_To_Chest/0.jpg","Hug_Knees_To_Chest/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Hurdle_Hops', 'Hurdle Hops', 'upper legs', 'hamstrings', '["abductors","adductors","calves","glutes","hamstrings"]', 'other', 'plyometrics', 'beginner', '["Set up a row of hurdles or other small barriers, placing them a few feet apart.","Stand in front of the first hurdle with your feet shoulder width apart. This will be your starting position.","Begin by jumping with both feet over the first hurdle, swinging both arms as you jump.","Absorb the impact of landing by bending the knees, rebounding out of the first leap by jumping over the next hurdle. Continue until you have jumped over all of the hurdles."]', NULL, '["Hurdle_Hops/0.jpg","Hurdle_Hops/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Hyperextensions_Back_Extensions', 'Hyperextensions (Back Extensions)', 'back', 'lower back', '["glutes","hamstrings"]', 'other', 'strength', 'beginner', '["Lie face down on a hyperextension bench, tucking your ankles securely under the footpads.","Adjust the upper pad if possible so your upper thighs lie flat across the wide pad, leaving enough room for you to bend at the waist without any restriction.","With your body straight, cross your arms in front of you (my preference) or behind your head. This will be your starting position. Tip: You can also hold a weight plate for extra resistance in front of you under your crossed arms.","Start bending forward slowly at the waist as far as you can while keeping your back flat. Inhale as you perform this movement. Keep moving forward until you feel a nice stretch on the hamstrings and you can no longer keep going without a rounding of the back. Tip: Never round the back as you perform this exercise. Also, some people can go farther than others. The key thing is that you go as far as your body allows you to without rounding the back.","Slowly raise your torso back to the initial position as you inhale. Tip: Avoid the temptation to arch your back past a straight line. Also, do not swing the torso at any time in order to protect the back from injury.","Repeat for the recommended amount of repetitions."]', NULL, '["Hyperextensions_Back_Extensions/0.jpg","Hyperextensions_Back_Extensions/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Hyperextensions_With_No_Hyperextension_Bench', 'Hyperextensions With No Hyperextension Bench', 'back', 'lower back', '["glutes","hamstrings"]', 'body only', 'strength', 'intermediate', '["With someone holding down your legs, slide yourself down to the edge a flat bench until your hips hang off the end of the bench. Tip: Your entire upper body should be hanging down towards the floor. Also, you will be in the same position as if you were on a hyperextension bench but the range of motion will be shorter due to the height of the flat bench vs. that of the hyperextension bench.","With your body straight, cross your arms in front of you (my preference) or behind your head. This will be your starting position. Tip: You can also hold a weight plate for extra resistance in front of you under your crossed arms.","Start bending forward slowly at the waist as far as you can while keeping your back flat. Inhale as you perform this movement. Keep moving forward until you almost touch the floor or you feel a nice stretch on the hamstrings (whichever comes first). Tip: Never round the back as you perform this exercise.","Slowly raise your torso back to the initial position as you exhale. Tip: Avoid the temptation to arch your back past a straight line. Also, do not swing the torso at any time in order to protect the back from injury.","Repeat for the recommended amount of repetitions."]', NULL, '["Hyperextensions_With_No_Hyperextension_Bench/0.jpg","Hyperextensions_With_No_Hyperextension_Bench/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-IT_Band_and_Glute_Stretch', 'IT Band and Glute Stretch', 'upper legs', 'abductors', '[]', 'other', 'stretching', 'intermediate', '["Loop a belt, rope, or band around one of your feet, and swing that leg across your body to the opposite side, keeping the leg extended as you lay on the ground. This will be your starting position.","Keeping your foot off of the floor, pull on the belt, using the tension to pull the toes up. Hold for 10-20 seconds, and repeat on the other side."]', NULL, '["IT_Band_and_Glute_Stretch/0.jpg","IT_Band_and_Glute_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Iliotibial_Tract-SMR', 'Iliotibial Tract-SMR', 'upper legs', 'abductors', '[]', 'foam roll', 'stretching', 'intermediate', '["Lay on your side, with the bottom leg placed onto a foam roller between the hip and the knee. The other leg can be crossed in front of you.","Place as much of your weight as is tolerable onto your bottom leg; there is no need to keep your bottom leg in contact with the ground. Be sure to relax the muscles of the leg you are stretching.","Roll your leg over the foam from you hip to your knee, pausing for 10-30 seconds at points of tension. Repeat with the opposite leg."]', NULL, '["Iliotibial_Tract-SMR/0.jpg","Iliotibial_Tract-SMR/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Incline_Barbell_Triceps_Extension', 'Incline Barbell Triceps Extension', 'upper arms', 'triceps', '["forearms"]', 'barbell', 'strength', 'intermediate', '["Hold a barbell with an overhand grip (palms down) that is a little closer together than shoulder width.","Lie back on an incline bench set at any angle between 45-75-degrees.","Bring the bar overhead with your arms extended and elbows in. The arms should be in line with the torso above the head. This will be your starting position.","Now lower the bar in a semicircular motion behind your head until your forearms touch your biceps. Inhale as you perform this movement. Tip: Keep your upper arms stationary and close to your head at all times. Only the forearms should move.","Return to the starting position as you breathe out and you contract the triceps. Hold the contraction for a second.","Repeat for the recommended amount of repetitions."]', NULL, '["Incline_Barbell_Triceps_Extension/0.jpg","Incline_Barbell_Triceps_Extension/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Incline_Bench_Pull', 'Incline Bench Pull', 'back', 'middle back', '["lats","shoulders"]', 'barbell', 'strength', 'beginner', '["Grab a dumbbell in each hand and lie face down on an incline bench that is set to an incline that is approximately 30 degrees.","Let the arms hang to your sides fully extended as they point to the floor.","Turn the wrists until your hands have a pronated (palms down) grip.","Now flare the elbows out. This will be your starting position.","As you breathe out, start to pull the dumbbells up as if you are doing a reverse bench press. You will do this by bending at the elbows and bringing the upper arms up as you let the forearms hang. Continue this motion until the upper arms are at the same level as your back. Tip: The elbows will come out to the side and your upper arms and torso should make the letter \"T\" at the top of the movement. Hold the contraction at the top for a second.","Slowly go back down to the starting position as you breathe in.","Repeat for the recommended amount of repetitions."]', NULL, '["Incline_Bench_Pull/0.jpg","Incline_Bench_Pull/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Incline_Cable_Chest_Press', 'Incline Cable Chest Press', 'chest', 'chest', '["shoulders","triceps"]', 'cable', 'strength', 'beginner', '["Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 45 degrees to the body, with your head and chest up. The elbows should be bent to about 90 degrees. This will be your starting position.","Begin by extending through the elbow, pressing the handles together straight in front of you. Keep your shoulder blades retracted as you execute the movement.","After pausing at full extension, return to the starting position, keeping tension on the cables."]', NULL, '["Incline_Cable_Chest_Press/0.jpg","Incline_Cable_Chest_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Incline_Cable_Flye', 'Incline Cable Flye', 'chest', 'chest', '["shoulders"]', 'cable', 'strength', 'intermediate', '["To get yourself into the starting position, set the pulleys at the floor level (lowest level possible on the machine that is below your torso).","Place an incline bench (set at 45 degrees) in between the pulleys, select a weight on each one and grab a pulley on each hand.","With a handle on each hand, lie on the incline bench and bring your hands together at arms length in front of your face. This will be your starting position.","With a slight bend of your elbows (in order to prevent stress at the biceps tendon), lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary. The movement should only occur at the shoulder joint.","Return your arms back to the starting position as you squeeze your chest muscles and exhale. Hold the contracted position for a second. Tip: Make sure to use the same arc of motion used to lower the weights.","Repeat the movement for the prescribed amount of repetitions."]', NULL, '["Incline_Cable_Flye/0.jpg","Incline_Cable_Flye/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Incline_Dumbbell_Bench_With_Palms_Facing_In', 'Incline Dumbbell Bench With Palms Facing In', 'chest', 'chest', '["shoulders","triceps"]', 'dumbbell', 'strength', 'beginner', '["Lie back on an incline bench with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.","By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them at shoulder width.","Once at shoulder width, keep the palms of your hands with a neutral grip (palms facing each other). Keep your elbows flared out with the upper arms in line with the shoulders (perpendicular to the torso) and the elbows bent creating a 90-degree angle between the upper arm and the forearm. This will be your starting position.","Now bring down the weights slowly to your side as you breathe in. Keep full control of the dumbbells at all times.","As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the dumbbells back in your thighs and then on the floor. This is the safest manner to dispose of the dumbbells."]', NULL, '["Incline_Dumbbell_Bench_With_Palms_Facing_In/0.jpg","Incline_Dumbbell_Bench_With_Palms_Facing_In/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Incline_Dumbbell_Curl', 'Incline Dumbbell Curl', 'upper arms', 'biceps', '[]', 'dumbbell', 'strength', 'beginner', '["Sit back on an incline bench with a dumbbell in each hand held at arms length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position.","While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second.","Slowly begin to bring the dumbbells back to starting position as your breathe in.","Repeat for the recommended amount of repetitions."]', NULL, '["Incline_Dumbbell_Curl/0.jpg","Incline_Dumbbell_Curl/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Incline_Dumbbell_Flyes', 'Incline Dumbbell Flyes', 'chest', 'chest', '["shoulders"]', 'dumbbell', 'strength', 'beginner', '["Hold a dumbbell on each hand and lie on an incline bench that is set to an incline angle of no more than 30 degrees.","Extend your arms above you with a slight bend at the elbows.","Now rotate the wrists so that the palms of your hands are facing you. Tip: The pinky fingers should be next to each other. This will be your starting position.","As you breathe in, start to slowly lower the arms to the side while keeping the arms extended and while rotating the wrists until the palms of the hand are facing each other. Tip: At the end of the movement the arms will be by your side with the palms facing the ceiling.","As you exhale start to bring the dumbbells back up to the starting position by reversing the motion and rotating the hands so that the pinky fingers are next to each other again. Tip: Keep in mind that the movement will only happen at the shoulder joint and at the wrist. There is no motion that happens at the elbow joint.","Repeat for the recommended amount of repetitions."]', NULL, '["Incline_Dumbbell_Flyes/0.jpg","Incline_Dumbbell_Flyes/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Incline_Dumbbell_Flyes_-_With_A_Twist', 'Incline Dumbbell Flyes - With A Twist', 'chest', 'chest', '["shoulders"]', 'dumbbell', 'strength', 'beginner', '["Hold a dumbbell in each hand and lie on an incline bench that is set to an incline angle of no more than 30 degrees.","Extend your arms above you with a slight bend at the elbows.","Now rotate the wrists so that the palms of your hands are facing you. Tip: The pinky fingers should be next to each other. This will be your starting position.","As you breathe in, start to slowly lower the arms to the side while keeping the arms extended and while rotating the wrists until the palms of the hand are facing each other. Tip: At the end of the movement the arms will be by your side with the palms facing the ceiling.","As you exhale start to bring the dumbbells back up to the starting position by reversing the motion and rotating the hands so that the pinky fingers are next to each other again. Tip: Keep in mind that the movement will only happen at the shoulder joint and at the wrist. There is no motion that happens at the elbow joint.","Repeat for the recommended amount of repetitions."]', NULL, '["Incline_Dumbbell_Flyes_-_With_A_Twist/0.jpg","Incline_Dumbbell_Flyes_-_With_A_Twist/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Incline_Hammer_Curls', 'Incline Hammer Curls', 'upper arms', 'biceps', '[]', 'dumbbell', 'strength', 'beginner', '["Seat yourself on an incline bench with a dumbbell in each hand. You should pressed firmly against he back with your feet together. Allow the dumbbells to hang straight down at your side, holding them with a neutral grip. This will be your starting position.","Initiate the movement by flexing at the elbow, attempting to keep the upper arm stationary.","Continue to the top of the movement and pause, then slowly return to the start position."]', NULL, '["Incline_Hammer_Curls/0.jpg","Incline_Hammer_Curls/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Incline_Inner_Biceps_Curl', 'Incline Inner Biceps Curl', 'upper arms', 'biceps', '[]', 'dumbbell', 'strength', 'beginner', '["Hold a dumbbell in each hand and lie back on an incline bench.","The dumbbells should be at arm''s length hanging at your sides and your palms should be facing out. This will be your starting position.","Now as you exhale curl the weight outward and up while keeping your forearms in line with your side deltoids. Continue the curl until the dumbbells are at shoulder height and to the sides of your deltoids. Tip: The end of the movement should look similar to a double biceps pose.","After a second contraction at the top of the movement, start to inhale and slowly lower the weights back to the starting position using the same path used to bring them up.","Repeat for the recommended amount of repetitions."]', NULL, '["Incline_Inner_Biceps_Curl/0.jpg","Incline_Inner_Biceps_Curl/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Incline_Push-Up_Depth_Jump', 'Incline Push-Up Depth Jump', 'chest', 'chest', '["shoulders","triceps"]', 'other', 'plyometrics', 'beginner', '["For this drill you will need a box about 12 inches high, and two thick mats or aerobics steps.","Place the steps just outside of your shoulders, and place your feet on top of the box so that you are in an incline pushup position, your hands just inside the steps. This will be your starting position.","Begin by bending at the elbows to lower your body, quickly reversing position to push your body off of the ground. As you leave the ground, move your hands onto the steps, bending your elbows to absorb the impact.","Repeat the motion to return to the starting position."]', NULL, '["Incline_Push-Up_Depth_Jump/0.jpg","Incline_Push-Up_Depth_Jump/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Incline_Push-Up_Medium', 'Incline Push-Up Medium', 'chest', 'chest', '["abdominals","shoulders","triceps"]', 'body only', 'strength', 'beginner', '["Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.","Place your hands on the bar, with your hands about shoulder width apart.","Position your feet back from the bar with arms and body straight. This will be your starting position.","Keeping your body straight, lower your chest to the bar by bending the arms.","Return to the starting position by extending the elbows, pressing yourself back up."]', NULL, '["Incline_Push-Up_Medium/0.jpg","Incline_Push-Up_Medium/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Incline_Push-Up_Wide', 'Incline Push-Up Wide', 'chest', 'chest', '["abdominals","shoulders","triceps"]', 'body only', 'strength', 'beginner', '["Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.","Place your hands on the bar, with your hands wider than shoulder width.","Position your feet back from the bar with arms and body straight. Your arms should be perpendicular to the body. This will be your starting position.","Keeping your body straight, lower your chest to the bar by bending the arms.","Return to the starting position by extending the elbows, pressing yourself back up."]', NULL, '["Incline_Push-Up_Wide/0.jpg","Incline_Push-Up_Wide/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Intermediate_Groin_Stretch', 'Intermediate Groin Stretch', 'upper legs', 'hamstrings', '[]', 'other', 'stretching', 'intermediate', '["Lie on your back with your legs extended. Loop a belt, rope, or band around one of your feet, and swing that leg as far to the side as you can. This will be your starting position.","Pull gently on the belt to create tension in your groin and hamstring muscles. Hold for 10-20 seconds, and repeat on the other side."]', NULL, '["Intermediate_Groin_Stretch/0.jpg","Intermediate_Groin_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Intermediate_Hip_Flexor_and_Quad_Stretch', 'Intermediate Hip Flexor and Quad Stretch', 'upper legs', 'quadriceps', '[]', 'other', 'stretching', 'intermediate', '["Lie face down on the floor, with a rope, belt, or band looped around one foot.","Flex the knee and extend the hip of the leg to be stretched, using both hands to pull on the belt. Your knee and your hip should come off of the floor, creating tension in the hip flexors and quadriceps. Hold the stretch for 10-20 seconds, and repeat on the other leg."]', NULL, '["Intermediate_Hip_Flexor_and_Quad_Stretch/0.jpg","Intermediate_Hip_Flexor_and_Quad_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Internal_Rotation_with_Band', 'Internal Rotation with Band', 'shoulders', 'shoulders', '[]', 'bands', 'strength', 'beginner', '["Choke the band around a post. The band should be at the same height as your elbow. Stand with your right side to the band a couple of feet away.","Grasp the end of the band with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position.","With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching away from your torso. This will be your starting position.","Execute the movement by rotating your arm in a forehand motion, keeping your elbow in place.","Continue as far as you are able, pause, and then return to the starting position."]', NULL, '["Internal_Rotation_with_Band/0.jpg","Internal_Rotation_with_Band/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Inverted_Row', 'Inverted Row', 'back', 'middle back', '["lats"]', 'body only', 'strength', 'beginner', '["Position a bar in a rack to about waist height. You can also use a smith machine.","Take a wider than shoulder width grip on the bar and position yourself hanging underneath the bar. Your body should be straight with your heels on the ground with your arms fully extended. This will be your starting position.","Begin by flexing the elbow, pulling your chest towards the bar. Retract your shoulder blades as you perform the movement.","Pause at the top of the motion, and return yourself to the start position.","Repeat for the desired number of repetitions."]', NULL, '["Inverted_Row/0.jpg","Inverted_Row/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Inverted_Row_with_Straps', 'Inverted Row with Straps', 'back', 'middle back', '["biceps","lats"]', 'other', 'strength', 'beginner', '["Hang a rope or suspension straps from a rack or other stable object. Grasp the ends and position yourself in a supine position hanging from the ropes. Your body should be straight with your heels on the ground with your arms fully extended. This will be your starting position.","Begin by flexing the elbow, pulling your chest to your hands. Retract your shoulder blades as you perform the movement.","Pause at the top of the motion, and return yourself to the start position.","Repeat for the desired number of repetitions."]', NULL, '["Inverted_Row_with_Straps/0.jpg","Inverted_Row_with_Straps/1.jpg"]', 5, 'sets', 0, 'fedb', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('fe-Iron_Cross', 'Iron Cross', 'shoulders', 'shoulders', '["chest","glutes","hamstrings","lower back","quadriceps","traps"]', 'dumbbell', 'strength', 'intermediate', '[]', NULL, '["Iron_Cross/0.jpg","Iron_Cross/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Iron_Crosses_stretch', 'Iron Crosses (stretch)', 'upper legs', 'quadriceps', '[]', 'body only', 'stretching', 'intermediate', '["Lie face down on the floor, with your arms extended out to your side, palms pressed to the floor. This will be your starting position.","To begin, flex one knee and bring that leg across the back of your body, attempting to touch it to the ground near the opposite hand.","Promptly return the leg to the starting postion, and quickly repeat with the other leg. Continue alternating for 10-20 repetitions."]', NULL, '["Iron_Crosses_stretch/0.jpg","Iron_Crosses_stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Isometric_Neck_Exercise_-_Front_And_Back', 'Isometric Neck Exercise - Front And Back', 'neck', 'neck', '[]', 'body only', 'strength', 'beginner', '["With your head and neck in a neutral position (normal position with head erect facing forward), place both of your hands on the front side of your head.","Now gently push forward as you contract the neck muscles but resisting any movement of your head. Start with slow tension and increase slowly. Keep breathing normally as you execute this contraction.","Hold for the recommended number of seconds.","Now release the tension slowly.","Rest for the recommended amount of time and repeat with your hands placed on the back side of your head."]', NULL, '["Isometric_Neck_Exercise_-_Front_And_Back/0.jpg","Isometric_Neck_Exercise_-_Front_And_Back/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Isometric_Neck_Exercise_-_Sides', 'Isometric Neck Exercise - Sides', 'neck', 'neck', '[]', 'body only', 'strength', 'beginner', '["With your head and neck in a neutral position (normal position with head erect facing forward), place your left hand on the left side of your head.","Now gently push towards the left as you contract the left neck muscles but resisting any movement of your head. Start with slow tension and increase slowly. Keep breathing normally as you execute this contraction.","Hold for the recommended number of seconds.","Now release the tension slowly.","Rest for the recommended amount of time and repeat with your right hand placed on the right side of your head."]', NULL, '["Isometric_Neck_Exercise_-_Sides/0.jpg","Isometric_Neck_Exercise_-_Sides/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-JM_Press', 'JM Press', 'upper arms', 'triceps', '["chest","shoulders"]', 'barbell', 'strength', 'beginner', '["Start the exercise the same way you would a close grip bench press. You will lie on a flat bench while holding a barbell at arms length (fully extended) with the elbows in. However, instead of having the arms perpendicular to the torso, make sure the bar is set in a direct line above the upper chest. This will be your starting position.","Now beginning from a fully extended position lower the bar down as if performing a lying triceps extension. Inhale as you perform this movement. When you reach the half way point, let the bar roll back about one inch by moving the upper arms towards your legs until they are perpendicular to the torso. Tip: Keep the bend at the elbows constant as you bring the upper arms forward.","As you exhale, press the bar back up by using the triceps to perform a close grip bench press.","Now go back to the starting position and start over.","Repeat for the recommended amount of repetitions."]', NULL, '["JM_Press/0.jpg","JM_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Jefferson_Squats', 'Jefferson Squats', 'upper legs', 'quadriceps', '["calves","glutes","hamstrings","lower back","traps"]', 'barbell', 'strength', 'intermediate', '["Place a barbell on the floor.","Stand in the middle of the bar length wise.","Bend down by bending at the knees and keeping your back straight and grasp the front of the bar with your right hand. Your palm should be in (neutral grip) facing the left side.","Grasp the rear of the bar with your left hand. The palm of your hand should be in neutral grip alignment (palms facing the right side). Tip: Ensure that your grip is even on the bar. Your torso should be positioned right in the middle of the bar and the distance between your torso and your right hand (which should be at the front) should be the same as the distance between your torso and your left hand (which should be to your back).","Now stand straight up with the weight. Tip: Your feet should be shoulder width apart and your toes slightly pointed out.","Squat down by bending at the knees and keeping your back straight until your upper thighs are parallel with the floor. Tip: Keep your back as vertical as possible with the floor and your head up. Also remember to not let your knees go past your toes. Inhale during this portion of the movement.","Now drive yourself back up to the starting position by pushing with the feet . Tip: Keep the bar hanging at arm''s length and your elbows locked with a slight bend. The arms only serve as hooks. Avoid doing any lifting with them. Do the lifting with your thighs; not your arms."]', NULL, '["Jefferson_Squats/0.jpg","Jefferson_Squats/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Jerk_Balance', 'Jerk Balance', 'shoulders', 'shoulders', '["glutes","hamstrings","quadriceps","triceps"]', 'barbell', 'olympic weightlifting', 'intermediate', '["This drill helps you learn to drive yourself low enough during the jerk and corrects those who move backward during the movement. Begin with the bar racked in the jerk position, with the shoulders forward, torso upright, and the feet split slightly apart.","Initiate the movement as you would a normal jerk, dipping at the knees while keeping your torso vertical, and driving back up forcefully, using momentum and not your arms to elevate the weight.","Keep the rear foot in place, using it to drive your body forward into a full split as you jerk the weight. Recover by standing up with the weight overhead."]', NULL, '["Jerk_Balance/0.jpg","Jerk_Balance/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Jerk_Dip_Squat', 'Jerk Dip Squat', 'upper legs', 'quadriceps', '["abdominals","calves"]', 'barbell', 'olympic weightlifting', 'intermediate', '["This movement strengthens the dip portion of the jerk. Begin with the bar racked in the jerk position, with the shoulders forward to create a shelf and the bar lightly contacting the throat. The feet should be directly under the hips, with the feet turned out as is comfortable.","Keeping the torso vertical, dip by flexing the knees, allowing them to travel forward and without moving the hips to the rear. The dip should not be excessive. Return the weight to the starting position by driving forcefully though the feet."]', NULL, '["Jerk_Dip_Squat/0.jpg","Jerk_Dip_Squat/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Jogging_Treadmill', 'Jogging, Treadmill', 'cardio', 'quadriceps', '["glutes","hamstrings"]', 'machine', 'cardio', 'beginner', '["To begin, step onto the treadmill and select the desired option from the menu. Most treadmills have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout.","Treadmills offer convenience, cardiovascular benefits, and usually have less impact than jogging outside. A 150 lb person will burn almost 250 calories jogging for 30 minutes, compared to more than 450 calories running. Maintain proper posture as you jog, and only hold onto the handles when necessary, such as when dismounting or checking your heart rate."]', NULL, '["Jogging_Treadmill/0.jpg","Jogging_Treadmill/1.jpg"]', 7, 'time', 0, 'fedb', 1),
('fe-Keg_Load', 'Keg Load', 'back', 'lower back', '["abdominals","biceps","calves","forearms","glutes","hamstrings","middle back","quadriceps","shoulders","traps"]', 'other', 'strongman', 'intermediate', '["To load kegs, place the desired number a distance from the loading platform, typically 30-50 feet.","Begin by grabbing the close handle of the first keg, tilting it onto its side to grab the opposite edge of the bottom of the keg. Lift the keg up to your chest.","The higher you can place the keg, the faster you should be able to move to the platform. Shouldering is usually not allowed. Be sure to keep a firm hold on the keg. Move as quickly as possible to the platform, and load it, extending through your hips, knees, and ankles to get it as high as possible.","Return to the starting position to retrieve the next keg, and repeat until the event is completed."]', NULL, '["Keg_Load/0.jpg","Keg_Load/1.jpg"]', 7, 'sets', 0, 'fedb', 1),
('fe-Kettlebell_Dead_Clean', 'Kettlebell Dead Clean', 'upper legs', 'hamstrings', '["calves","glutes","lower back","quadriceps","traps"]', 'kettlebells', 'strength', 'intermediate', '["Place kettlebell between your feet. To get in the starting position, push your butt back and look straight ahead.","Clean the kettlebell to your shoulder. Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so.","Lower the kettlebell, keeping the hamstrings loaded by keeping your back straight and your butt out."]', NULL, '["Kettlebell_Dead_Clean/0.jpg","Kettlebell_Dead_Clean/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Kettlebell_Halo', 'Kettlebell Halo', 'shoulders', 'shoulders', '["traps","middle back","abdominals","triceps"]', 'kettlebells', 'strength', 'beginner', '["Stand tall with your feet hip-width apart. Hold a kettlebell upside down by the horns, with the bell above your hands and close to your chest. Brace your abdominals and squeeze your glutes so your ribcage stays down. This is your starting position.","Keeping your elbows close to your head, move the kettlebell up past one ear and around behind your head.","Continue the circle past the opposite ear and back down to the starting position in front of your chest, letting the bell pass close to your body throughout.","Complete the prescribed number of circles in one direction, then repeat the same number in the opposite direction.","Move slowly and keep your head, hips and lower back still. If your lower back arches or the bell drifts far from your head, use a lighter weight."]', NULL, NULL, 5, 'sets', 0, 'fedb', 1),
('fe-Kettlebell_Halo_With_Overhead_Extension', 'Kettlebell Halo with Overhead Extension', 'shoulders', 'shoulders', '["traps","middle back","abdominals"]', 'kettlebells', 'strength', 'intermediate', '["Stand tall with your feet hip-width apart. Hold a kettlebell upside down by the horns, with the bell above your hands and close to your chest. Brace your abdominals and squeeze your glutes so your ribcage stays down. This is your starting position.","Keeping your elbows close to your head, move the kettlebell up past one ear and around until it sits behind your head. Pause here.","From this position, extend your elbows to press the kettlebell up and overhead until your arms are straight, keeping your upper arms alongside your head.","Bend your elbows to lower the kettlebell back to the pause position behind your head, under control.","Continue the circle past the opposite ear and back down to the starting position in front of your chest to complete one repetition.","Alternate the direction of the circle on each repetition. Keep your head, hips and lower back still throughout; if your lower back arches or you cannot reach the overhead position without leaning back, use a lighter weight or perform the halo and the extension as separate exercises."]', NULL, NULL, 5, 'sets', 0, 'fedb', 1),
('fe-Kettlebell_One-Legged_Deadlift', 'Kettlebell One-Legged Deadlift', 'upper legs', 'hamstrings', '["glutes","lower back"]', 'kettlebells', 'strength', 'intermediate', '["Hold a kettlebell by the handle in one hand. Stand on one leg, on the same side that you hold the kettlebell.","Keeping that knee slightly bent, perform a stiff legged deadlift by bending at the hip, extending your free leg behind you for balance.","Continue lowering the kettlebell until you are parallel to the ground, and then return to the upright position."]', NULL, '["Kettlebell_One-Legged_Deadlift/0.jpg","Kettlebell_One-Legged_Deadlift/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Kettlebell_Overhead_Triceps_Extension', 'Kettlebell Overhead Triceps Extension', 'upper arms', 'triceps', '["shoulders","abdominals"]', 'kettlebells', 'strength', 'beginner', '["Stand with your feet hip-width apart, holding a kettlebell by the horns with both hands. Press it overhead until your arms are extended, with the bell hanging behind your hands.","Brace your abdominals and keep your upper arms vertical and close to your head. This is your starting position.","Bend at the elbows to lower the kettlebell behind your head, going as far as your shoulder mobility allows without your elbows flaring outward.","Extend your elbows to press the kettlebell back to the starting position, keeping your upper arms still throughout.","Keep your ribcage down and avoid arching your lower back as you extend."]', NULL, NULL, 5, 'sets', 0, 'fedb', 1),
('fe-Kettlebell_Pass_Between_The_Legs', 'Kettlebell Pass Between The Legs', 'waist', 'abdominals', '["glutes","hamstrings","shoulders"]', 'kettlebells', 'strength', 'intermediate', '["Place one kettlebell between your legs and take a comfortable stance. Bend over by pushing your butt out and keeping your back flat.","Pick up a kettlebell and pass it to your other hand between your legs, in the fashion of a \"W\". Go back and forth for several repetitions."]', NULL, '["Kettlebell_Pass_Between_The_Legs/0.jpg","Kettlebell_Pass_Between_The_Legs/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Kettlebell_Pirate_Ships', 'Kettlebell Pirate Ships', 'shoulders', 'shoulders', '["abdominals"]', 'kettlebells', 'strength', 'beginner', '["With a wide stance, hold a kettlebell with both hands. Allow it to hang at waist level with your arms extended. This will be your starting position.","Initiate the movement by turning to one side, swinging the kettlebell to head height. Briefly pause at the top of the motion.","Allow the bell to drop as you rotate to the opposite side, again raising the kettlebell to head height.","Repeat for the desired amount of repetitions."]', NULL, '["Kettlebell_Pirate_Ships/0.jpg","Kettlebell_Pirate_Ships/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Kettlebell_Turkish_Get-Up_Lunge_style', 'Kettlebell Turkish Get-Up (Lunge style)', 'shoulders', 'shoulders', '["abdominals","hamstrings","quadriceps","triceps"]', 'kettlebells', 'strength', 'intermediate', '["Lie on your back on the floor and press a kettlebell to the top position by extending the elbow. Bend the knee on the same side as the kettlebell.","Keeping the kettlebell locked out at all times, pivot to the opposite side and use your non- working arm to assist you in driving forward to the lunge position. Using your free hand, push yourself to a seated position, then progressing to one knee.","While looking up at the kettlebell, slowly stand up. Reverse the motion back to the starting position and repeat."]', NULL, '["Kettlebell_Turkish_Get-Up_Lunge_style/0.jpg","Kettlebell_Turkish_Get-Up_Lunge_style/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Kipping_Muscle_Up', 'Kipping Muscle Up', 'back', 'lats', '["abdominals","biceps","forearms","middle back","shoulders","traps","triceps"]', 'other', 'strength', 'intermediate', '["Grip the rings using a false grip, with the base of your palms on top of the rings.","Begin with a movement swinging your legs backward slightly.","Counter that movement by swinging your legs forward and up, jerking your chin and chest back, pulling yourself up with both arms as you do so. As you reach the top position of the pull-up, pull the rings to your armpits as you roll your shoulders forward, allowing your elbows to move straight back behind you. This puts you into the proper position to continue into the dip portion of the movement.","Maintaining control and stability, extend through the elbow to complete the motion.","Use care when lowering yourself to the ground."]', NULL, '["Kipping_Muscle_Up/0.jpg","Kipping_Muscle_Up/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Knee_Across_The_Body', 'Knee Across The Body', 'upper legs', 'glutes', '["abductors","lower back"]', 'body only', 'stretching', 'beginner', '["Lie down on the floor with your right leg straight. Bend your left leg and lower it across your body, holding the knee down toward the floor with your right hand. (The knee doesn''t need to touch the floor if you''re tight.)","Place your left arm comfortably beside you and turn your head to the left. Imagine you have a weight tied to your tailbone. let your tailbone fall back toward the floor as your chest reaches in the opposite direction to stretch your lower back. Switch sides."]', NULL, '["Knee_Across_The_Body/0.jpg","Knee_Across_The_Body/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Knee_Circles', 'Knee Circles', 'lower legs', 'calves', '["hamstrings","quadriceps"]', 'body only', 'stretching', 'beginner', '["Stand with your legs together and hands by your waist.","Now move your knees in a circular motion as you breathe normally.","Repeat for the recommended amount of repetitions."]', NULL, '["Knee_Circles/0.jpg","Knee_Circles/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Knee_Hip_Raise_On_Parallel_Bars', 'Knee/Hip Raise On Parallel Bars', 'waist', 'abdominals', '[]', 'other', 'strength', 'beginner', '["Position your body on the vertical leg raise bench so that your forearms are resting on the pads next to the torso and holding on to the handles. Your arms will be bent at a 90 degree angle.","The torso should be straight with the lower back pressed against the pad of the machine and the legs extended pointing towards the floor. This will be your starting position.","Now as you breathe out, lift your legs up as you keep them extended. Continue this movement until your legs are roughly parallel to the floor and then hold the contraction for a second. Tip: Do not use any momentum or swinging as you perform this exercise.","Slowly go back to the starting position as you breathe in.","Repeat for the recommended amount of repetitions."]', NULL, '["Knee_Hip_Raise_On_Parallel_Bars/0.jpg","Knee_Hip_Raise_On_Parallel_Bars/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Knee_Tuck_Jump', 'Knee Tuck Jump', 'upper legs', 'hamstrings', '["abductors","adductors","calves","glutes","quadriceps"]', 'body only', 'plyometrics', 'beginner', '["Begin in a comfortable standing position with your knees slightly bent. Hold your hands in front of you, palms down with your fingertips together at chest height. This will be your starting position.","Rapidly dip down into a quarter squat and immediately explode upward. Drive the knees towards the chest, attempting to touch them to the palms of the hands.","Jump as high as you can, raising your knees up, and then ensure a good land be re-extending your legs, absorbing impact through be allowing the knees to rebend."]', NULL, '["Knee_Tuck_Jump/0.jpg","Knee_Tuck_Jump/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Kneeling_Arm_Drill', 'Kneeling Arm Drill', 'shoulders', 'shoulders', '["abdominals"]', 'body only', 'plyometrics', 'beginner', '["This drill helps increase arm efficiency during the run. Begin kneeling, left foot in front, right knee down. Apply pressure through the front heel to keep your glutes and hamstrings activated.","Begin by blocking the arms in long, pendulum like swings. Close the arm angle, blocking with the arms as you would when jogging, progressing to a run and finally a sprint.","As soon as your hands pass the hip, accelerate them forward during the sprinting motion to move them as quickly as possible.","Switch knees and repeat."]', NULL, '["Kneeling_Arm_Drill/0.jpg","Kneeling_Arm_Drill/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Kneeling_Cable_Crunch_With_Alternating_Oblique_Twists', 'Kneeling Cable Crunch With Alternating Oblique Twists', 'waist', 'abdominals', '[]', 'cable', 'strength', 'beginner', '["Connect a rope attachment to a high pulley cable and position a mat on the floor in front of it.","Grab the rope with both hands and kneel approximately two feet back from the tower.","Position the rope behind your head with your hands by your ears.","Keep your hands in the same place, contract your abs and pull downward on the rope in a crunching movement until your elbows reach your knees.","Pause briefly at the bottom and rise up in a slow and controlled manner until you reach the starting position.","Repeat the same downward movement until you''re halfway down, at which time you''ll begin rotating one of your elbows to the opposite knee.","Again, pause briefly at the bottom and rise up in a slow and controlled manner until you reach the starting position.","Repeat the same movement as before, but alternate the other elbow to the opposite knee.","Continue this series of movements to failure."]', NULL, '["Kneeling_Cable_Crunch_With_Alternating_Oblique_Twists/0.jpg","Kneeling_Cable_Crunch_With_Alternating_Oblique_Twists/1.jpg"]', 5, 'sets', 0, 'fedb', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('fe-Kneeling_Forearm_Stretch', 'Kneeling Forearm Stretch', 'lower arms', 'forearms', '[]', 'body only', 'stretching', 'beginner', '["Start by kneeling on a mat with your palms flat and your fingers pointing back toward your knees.","Slowly lean back keeping your palms flat on the floor until you feel a stretch in your wrists and forearms. Hold for 20-30 seconds."]', NULL, '["Kneeling_Forearm_Stretch/0.jpg","Kneeling_Forearm_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Kneeling_High_Pulley_Row', 'Kneeling High Pulley Row', 'back', 'lats', '["biceps","middle back"]', 'cable', 'strength', 'beginner', '["Select the appropriate weight using a pulley that is above your head. Attach a rope to the cable and kneel a couple of feet away, holding the rope out in front of you with both arms extended. This will be your starting position.","Initiate the movement by flexing the elbows and fully retracting your shoulders, pulling the rope toward your upper chest with your elbows out.","After pausing briefly, slowly return to the starting position."]', NULL, '["Kneeling_High_Pulley_Row/0.jpg","Kneeling_High_Pulley_Row/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Kneeling_Hip_Flexor', 'Kneeling Hip Flexor', 'upper legs', 'quadriceps', '["quadriceps"]', 'body only', 'stretching', 'beginner', '["Kneel on a mat and bring your right knee up so the bottom of your foot is on the floor and extend your left leg out behind you so the top of your foot is on the floor.","Shift your weight forward until you feel a stretch in your hip. Hold for 15 seconds, then repeat for your other side."]', NULL, '["Kneeling_Hip_Flexor/0.jpg","Kneeling_Hip_Flexor/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Kneeling_Single-Arm_High_Pulley_Row', 'Kneeling Single-Arm High Pulley Row', 'back', 'lats', '["biceps","middle back"]', 'cable', 'strength', 'beginner', '["Attach a single handle to a high pulley and make your weight selection.","Kneel in front of the cable tower, taking the cable with one hand with your arm extended. This will be your starting position.","Starting with your palm facing forward, pull the weight down to your torso by flexing the elbow and retract the shoulder blade. As you do so, rotate the wrist so that at the completion of the movement, your palm is now facing you.","After a brief pause, return to the starting position."]', NULL, '["Kneeling_Single-Arm_High_Pulley_Row/0.jpg","Kneeling_Single-Arm_High_Pulley_Row/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Kneeling_Squat', 'Kneeling Squat', 'upper legs', 'glutes', '["abdominals","hamstrings","lower back"]', 'barbell', 'powerlifting', 'intermediate', '["Set the bar to the proper height in a power rack. Kneel behind the bar; it may be beneficial to put a mat down to pad your knees. Slide under the bar, racking it across the back of your shoulders. Your shoulder blades should be retracted and the bar tight across your back. Unrack the weight.","With your head looking forward, sit back with your butt until you touch your calves.","Reverse the motion, returning the torso to an upright position."]', NULL, '["Kneeling_Squat/0.jpg","Kneeling_Squat/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Landmine_180s', 'Landmine 180''s', 'waist', 'abdominals', '["glutes","lower back","shoulders"]', 'barbell', 'strength', 'beginner', '["Position a bar into a landmine or securely anchor it in a corner. Load the bar to an appropriate weight.","Raise the bar from the floor, taking it to shoulder height with both hands with your arms extended in front of you. Adopt a wide stance. This will be your starting position.","Perform the movement by rotating the trunk and hips as you swing the weight all the way down to one side. Keep your arms extended throughout the exercise.","Reverse the motion to swing the weight all the way to the opposite side.","Continue alternating the movement until the set is complete."]', NULL, '["Landmine_180s/0.jpg","Landmine_180s/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Landmine_Linear_Jammer', 'Landmine Linear Jammer', 'shoulders', 'shoulders', '["abdominals","calves","chest","hamstrings","quadriceps","triceps"]', 'barbell', 'strength', 'intermediate', '["Position a bar into landmine or, lacking one, securely anchor it in a corner. Load the bar to an appropriate weight and position the handle attachment on the bar.","Raise the bar from the floor, taking the handles to your shoulders. This will be your starting position.","In an athletic stance, squat by flexing your hips and setting your hips back, keeping your arms flexed.","Reverse the motion by powerfully extending through the hips, knees, and ankles, while also extending the elbows to straighten the arms. This movement should be done explosively, coming out of the squat to full extension as powerfully as possible.","Return to the starting position."]', NULL, '["Landmine_Linear_Jammer/0.jpg","Landmine_Linear_Jammer/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Lateral_Bound', 'Lateral Bound', 'upper legs', 'adductors', '["abductors","calves","glutes","hamstrings","quadriceps"]', 'body only', 'plyometrics', 'beginner', '["Assume a half squat position facing 90 degrees from your direction of travel. This will be your starting position.","Allow your lead leg to do a countermovement inward as you shift your weight to the outside leg.","Immediately push off and extend, attempting to bound to the side as far as possible.","Upon landing, immediately push off in the opposite direction, returning to your original start position.","Continue back and forth for several repetitions."]', NULL, '["Lateral_Bound/0.jpg","Lateral_Bound/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Lateral_Box_Jump', 'Lateral Box Jump', 'upper legs', 'adductors', '["abductors","calves","glutes","hamstrings","quadriceps"]', 'other', 'plyometrics', 'beginner', '["Assume a comfortable standing position, with a short box positioned next to you. This will be your starting position.","Quickly dip into a quarter squat to initiate the stretch reflex, and immediately reverse direction to jump up and to the side.","Bring your knees high enough to ensure your feet have good clearance over the box.","Land on the center of the box, using your legs to absorb the impact.","Carefully jump down to the other side of the box, and continue going back and forth for several repetitions."]', NULL, '["Lateral_Box_Jump/0.jpg","Lateral_Box_Jump/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Lateral_Cone_Hops', 'Lateral Cone Hops', 'upper legs', 'adductors', '["abductors","calves","glutes","hamstrings","quadriceps"]', 'other', 'plyometrics', 'beginner', '["Position a number of cones in a row several feet apart.","Stand next to the end of the cones, facing 90 degrees to the direction of travel. This will be your starting position.","Begin the jump by dipping with the knees to initiate a stretch reflex, and immediately reverse direction to push off the ground, jumping up and sideways over the cone.","Use your legs to absorb impact upon landing, and rebound into the next jump, continuing down the row of cones."]', NULL, '["Lateral_Cone_Hops/0.jpg","Lateral_Cone_Hops/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Lateral_Raise_-_With_Bands', 'Lateral Raise - With Bands', 'shoulders', 'shoulders', '[]', 'bands', 'strength', 'beginner', '["To begin, stand on an exercise band so that tension begins at arm''s length. Grasp the handles using a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The handles should be resting on the sides of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.","Use your side shoulders to lift the handles to the sides as you exhale. Continue to lift the handles until they are slightly above parallel. Tip: As you lift the handles, slightly tilt the hand as if you were pouring water and keep your arms extended. Also, keep your torso stationary and pause for a second at the top of the movement.","Lower the handles back down slowly to the starting position. Inhale as you perform this portion of the movement.","Repeat for the recommended amount of repetitions."]', NULL, '["Lateral_Raise_-_With_Bands/0.jpg","Lateral_Raise_-_With_Bands/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Latissimus_Dorsi-SMR', 'Latissimus Dorsi-SMR', 'back', 'lats', '[]', 'foam roll', 'stretching', 'beginner', '["While lying on the floor, place a foam roll under your back and to one side, just behind your arm pit. This will be your starting position.","Keep the arm of the side being stretched behind and to the side of you as you shift your weight onto your lats, keeping your upper body off of the ground. Hold for 10-30 seconds, and switch sides."]', NULL, '["Latissimus_Dorsi-SMR/0.jpg","Latissimus_Dorsi-SMR/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Leg-Over_Floor_Press', 'Leg-Over Floor Press', 'chest', 'chest', '["shoulders","triceps"]', 'kettlebells', 'strength', 'intermediate', '["Lie on the floor with one kettlebell in place on your chest, holding it by the handle. Extend leg on working side over leg on non-working side.Your free arm can be extended out to your side for support.","Press the kettlebll into a locked out position.","Lower the weight until the elbow touches the ground, keeping the kettlebell above the elbow. Repeat for the desired number of repetitions."]', NULL, '["Leg-Over_Floor_Press/0.jpg","Leg-Over_Floor_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Leg-Up_Hamstring_Stretch', 'Leg-Up Hamstring Stretch', 'upper legs', 'hamstrings', '[]', 'body only', 'stretching', 'beginner', '["Lie flat on your back, bend one knee, and put that foot flat on the floor to stabilize your spine.","Extend the other leg in the air. If you''re tight, you wont be able to straighten it. That''s okay. Extend the knee so that the sole of the lifted foot faces the ceiling (or as close as you can get it).","Slowly straighten the legs as much as possible and then pull the leg toward your nose. Switch sides."]', NULL, '["Leg-Up_Hamstring_Stretch/0.jpg","Leg-Up_Hamstring_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Leg_Extensions', 'Leg Extensions', 'upper legs', 'quadriceps', '[]', 'machine', 'strength', 'beginner', '["For this exercise you will need to use a leg extension machine. First choose your weight and sit on the machine with your legs under the pad (feet pointed forward) and the hands holding the side bars. This will be your starting position. Tip: You will need to adjust the pad so that it falls on top of your lower leg (just above your feet). Also, make sure that your legs form a 90-degree angle between the lower and upper leg. If the angle is less than 90-degrees then that means the knee is over the toes which in turn creates undue stress at the knee joint. If the machine is designed that way, either look for another machine or just make sure that when you start executing the exercise you stop going down once you hit the 90-degree angle.","Using your quadriceps, extend your legs to the maximum as you exhale. Ensure that the rest of the body remains stationary on the seat. Pause a second on the contracted position.","Slowly lower the weight back to the original position as you inhale, ensuring that you do not go past the 90-degree angle limit.","Repeat for the recommended amount of times."]', NULL, '["Leg_Extensions/0.jpg","Leg_Extensions/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Leg_Lift', 'Leg Lift', 'upper legs', 'glutes', '["hamstrings"]', 'body only', 'strength', 'beginner', '["While standing up straight with both feet next to each other at around shoulder width, grab a sturdy surface such as the sides of a squat rack or the top of a chair to brace yourself and keep balance.","With or without an ankle weight, lift one leg behind you as if performing a leg curl but standing up while keeping the other leg straight. Breathe out as you perform this movement.","Slowly bring the raised leg back to the floor as you breathe in.","Repeat for the recommended amount of repetitions.","Repeat the movement with the opposite leg."]', NULL, '["Leg_Lift/0.jpg","Leg_Lift/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Leg_Press', 'Leg Press', 'upper legs', 'quadriceps', '["calves","glutes","hamstrings"]', 'machine', 'strength', 'beginner', '["Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).","Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you. Tip: Make sure that you do not lock your knees. Your torso and the legs should make a perfect 90-degree angle. This will be your starting position.","As you inhale, slowly lower the platform until your upper and lower legs make a 90-degree angle.","Pushing mainly with the heels of your feet and using the quadriceps go back to the starting position as you exhale.","Repeat for the recommended amount of repetitions and ensure to lock the safety pins properly once you are done. You do not want that platform falling on you fully loaded."]', NULL, '["Leg_Press/0.jpg","Leg_Press/1.jpg"]', 5, 'sets', 1, 'fedb', 1),
('fe-Leg_Pull-In', 'Leg Pull-In', 'waist', 'abdominals', '[]', 'body only', 'strength', 'beginner', '["Lie on an exercise mat with your legs extended and your hands either palms facing down next to you or under your glutes. Tip: My preference is with the hands next to me. This will be your starting position.","Bend your knees and pull your upper thighs into your midsection as you breathe out. Continue the motion until your knees are around chest level. Contract your abs as you execute this movement and hold for a second at the top. Tip: As you perform the motion, the lower legs (calves) should always remain parallel to the floor.","Return to the starting position as you inhale.","Repeat for the recommended amount of repetitions."]', NULL, '["Leg_Pull-In/0.jpg","Leg_Pull-In/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Leverage_Chest_Press', 'Leverage Chest Press', 'chest', 'chest', '["shoulders","triceps"]', 'machine', 'strength', 'beginner', '["Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the bottom or middle of the pectorals at the beginning of the motion.","Your chest and head should be up and your shoulder blades retracted. This will be your starting position.","Press the handles forward by extending through the elbow.","After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete."]', NULL, '["Leverage_Chest_Press/0.jpg","Leverage_Chest_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Leverage_Deadlift', 'Leverage Deadlift', 'upper legs', 'quadriceps', '["glutes","hamstrings"]', 'machine', 'strength', 'beginner', '["Load the pins to an appropriate weight. Position yourself directly between the handles. Grasp the bottom handles with a comfortable grip, and then lower your hips as you take a breath. Look forward with your head and keep your chest up. This will be your starting position.","Return the weight to the starting position."]', NULL, '["Leverage_Deadlift/0.jpg","Leverage_Deadlift/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Leverage_Decline_Chest_Press', 'Leverage Decline Chest Press', 'chest', 'chest', '["shoulders","triceps"]', 'machine', 'strength', 'beginner', '["Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the bottom of the pectorals at the beginning of the motion. Your chest and head should be up and your shoulder blades retracted. This will be your starting position.","Press the handles forward by extending through the elbow.","After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete."]', NULL, '["Leverage_Decline_Chest_Press/0.jpg","Leverage_Decline_Chest_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Leverage_High_Row', 'Leverage High Row', 'back', 'middle back', '["lats"]', 'machine', 'strength', 'beginner', '["Load an appropriate weight onto the pins and adjust the seat height so that you can just reach the handles above you. Adjust the knee pad to help keep you down. Grasp the handles with a pronated grip. This will be your starting position.","Pull the handles towards your torso, retracting your shoulder blades as you flex the elbow.","Pause at the bottom of the motion, and then slowly return the handles to the starting position.","For multiple repetitions, avoid completely returning the weight to the stops to keep tension on the muscles being worked."]', NULL, '["Leverage_High_Row/0.jpg","Leverage_High_Row/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Leverage_Incline_Chest_Press', 'Leverage Incline Chest Press', 'chest', 'chest', '["shoulders","triceps"]', 'machine', 'strength', 'beginner', '["Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the top of the pectorals at the beginning of the motion. Your chest and head should be up and your shoulder blades retracted. This will be your starting position.","Press the handles forward by extending through the elbow.","After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete."]', NULL, '["Leverage_Incline_Chest_Press/0.jpg","Leverage_Incline_Chest_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Leverage_Iso_Row', 'Leverage Iso Row', 'back', 'lats', '["biceps","middle back"]', 'machine', 'strength', 'beginner', '["Load an appropriate weight onto the pins and adjust the seat height so that the handles are at chest level. Grasp the handles with either a neutral or pronated grip. This will be your starting position.","Pull the handles towards your torso, retracting your shoulder blades as you flex the elbow.","Pause at the bottom of the motion, and then slowly return the handles to the starting position. For multiple repetitions, avoid completely returning the weight to the stops to keep tension on the muscles being worked."]', NULL, '["Leverage_Iso_Row/0.jpg","Leverage_Iso_Row/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Leverage_Shoulder_Press', 'Leverage Shoulder Press', 'shoulders', 'shoulders', '["triceps"]', 'machine', 'strength', 'beginner', '["Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the top of the shoulders at the beginning of the motion. Your chest and head should be up and handles held with a pronated grip. This will be your starting position.","Press the handles upward by extending through the elbow.","After a brief pause at the top, return the weight to just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete."]', NULL, '["Leverage_Shoulder_Press/0.jpg","Leverage_Shoulder_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('fe-Leverage_Shrug', 'Leverage Shrug', 'back', 'traps', '["forearms"]', 'machine', 'strength', 'beginner', '["Load the pins to an appropriate weight. Position yourself directly between the handles.","Grasp the top handles with a comfortable grip, and then lower your hips as you take a breath. Look forward with your head and keep your chest up.","Drive through the floor with your heels, extending your hips and knees as you rise to a standing position. Keep your arms straight throughout the movement, finishing with your shoulders back. This will be your starting position.","Raise the weight by shrugging the shoulders towards your ears, moving straight up and down.","Pause at the top of the motion, and then return the weight to the starting position."]', NULL, '["Leverage_Shrug/0.jpg","Leverage_Shrug/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Linear_3-Part_Start_Technique', 'Linear 3-Part Start Technique', 'upper legs', 'hamstrings', '["calves","quadriceps"]', 'body only', 'plyometrics', 'beginner', '["This drill helps you accelerate as quickly as possible into a sprint from a dead stop. It helps to use a line to start from. Begin with two feet on the line. Place your left foot with the toe next to your right ankle. Place your right foot 4-6 inches behind the left.","Place your right hand onto the line, and thing bring your nose close to your left knee.","Squat down as you lean foward, your head being lower than your hips and your weight loaded onto the left leg. This will be your starting position.","Take your left hand up so that it is parallel to the ground, pointing behind you, and explode out when ready."]', NULL, '["Linear_3-Part_Start_Technique/0.jpg","Linear_3-Part_Start_Technique/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Linear_Acceleration_Wall_Drill', 'Linear Acceleration Wall Drill', 'upper legs', 'hamstrings', '["calves","glutes","quadriceps"]', 'body only', 'plyometrics', 'beginner', '["Lean at around 45 degrees against a wall. Your feet should be together, glutes contracted.","Begin by lifting your right knee quickly, pausing, and then driving it straight down into the ground.","Switch legs, raising the opposite knee, and then attacking the ground straight down.","Repeat once more with your right leg, and as soon as the right foot strikes the ground hammer them out rapidly, alternating left and right as fast as you can."]', NULL, '["Linear_Acceleration_Wall_Drill/0.jpg","Linear_Acceleration_Wall_Drill/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Linear_Depth_Jump', 'Linear Depth Jump', 'upper legs', 'quadriceps', '["calves","glutes","hamstrings"]', 'other', 'plyometrics', 'intermediate', '["You will need two boxes or benches spaced a few feet away from each other. Begin by standing on one box facing towards the other platform.","To initiate the movement, gently drop down to the ground between your platforms, allowing the knees and hips to flex.","Reverse the motion by exploding, extending through the hips, knees, and ankles to jump onto the other platform.","Land softly, asborbing the impact through the legs."]', NULL, '["Linear_Depth_Jump/0.jpg","Linear_Depth_Jump/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Log_Lift', 'Log Lift', 'shoulders', 'shoulders', '["abdominals","chest","glutes","hamstrings","lower back","middle back","quadriceps","traps","triceps"]', 'other', 'strongman', 'intermediate', '["Begin standing with the log in front of you. Grasp the handles, and begin to clean the log. As you are bent over to start the clean, attempt to get the log as high as possible, pulling it into your chest. Extend through the hips and knees to bring it up to complete the clean.","Push your head back and look up, creating a shelf on your chest to rest the log. Begin the press by dipping, flexing slightly through the knees and reversing the motion. This push press will generate momentum to start the log moving vertically. Continue by extending through the elbows to press the log above your head. There are no strict rules on form, so use whatever techniques you are most efficient with. As the log is pressed, ensure that you push your head through on each repetition, looking forward.","Repeat as many times as possible. Attempt to control the descent of the log as it is returned to the ground."]', NULL, '["Log_Lift/0.jpg","Log_Lift/1.jpg"]', 7, 'sets', 0, 'fedb', 1),
('fe-London_Bridges', 'London Bridges', 'back', 'lats', '["biceps","forearms","middle back"]', 'other', 'strength', 'intermediate', '["Attach a climbing rope to a high beam or cross member. Below it, ensure that the smith machine bar is locked in place with the safeties and cannot move. Alternatively, a secure box could also be utilized.","Stand on the bar, using the rope to balance yourself. This will be your starting position.","Keeping your body straight, lean back and lower your body by slowly going hand over hand with the rope. Continue until you are perpendicular to the ground.","Keeping your body straight, reverse the motion, going hand over hand back to the starting position."]', NULL, '["London_Bridges/0.jpg","London_Bridges/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Looking_At_Ceiling', 'Looking At Ceiling', 'upper legs', 'quadriceps', '[]', 'body only', 'stretching', 'beginner', '["Kneel on the floor, holding your heels with both hands.","Lift your buttocks up and forward while bringing your head back to look up at the ceiling, to give an arch in your back."]', NULL, '["Looking_At_Ceiling/0.jpg","Looking_At_Ceiling/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Low_Cable_Crossover', 'Low Cable Crossover', 'chest', 'chest', '["shoulders"]', 'cable', 'strength', 'beginner', '["To move into the starting position, place the pulleys at the low position, select the resistance to be used and grasp a handle in each hand.","Step forward, gaining tension in the pulleys. Your palms should be facing forward, hands below the waist, and your arms straight. This will be your starting position.","With a slight bend in your arms, draw your hands upward and toward the midline of your body. Your hands should come together in front of your chest, palms facing up.","Return your arms back to the starting position after a brief pause."]', NULL, '["Low_Cable_Crossover/0.jpg","Low_Cable_Crossover/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Low_Cable_Triceps_Extension', 'Low Cable Triceps Extension', 'upper arms', 'triceps', '[]', 'cable', 'strength', 'beginner', '["Select the desired weight and lay down face up on the bench of a seated row machine that has a rope attached to it. Your head should be pointing towards the attachment.","Grab the outside of the rope ends with your palms facing each other (neutral grip).","Position your elbows so that they are bent at a 90 degree angle and your upper arms are perpendicular (90 degree angle) to your torso. Tip: Keep the elbows in and make sure that the upper arms point to the ceiling while your forearms point towards the pulley above your head. This will be your starting position.","As you breathe out, extend your lower arms until they are straight and vertical. The upper arms and elbows remain stationary throughout the movement. Only the forearms should move. Contract the triceps hard for a second.","As you breathe in slowly return to the starting position.","Repeat for the recommended amount of repetitions."]', NULL, '["Low_Cable_Triceps_Extension/0.jpg","Low_Cable_Triceps_Extension/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Low_Pulley_Row_To_Neck', 'Low Pulley Row To Neck', 'shoulders', 'shoulders', '["biceps","middle back","traps"]', 'cable', 'strength', 'beginner', '["Sit on a low pulley row machine with a rope attachment.","Grab the ends of the rope using a palms-down grip and sit with your back straight and your knees slightly bent. Tip: Keep your back almost completely vertical and your arms fully extended in front of you. This will be your starting position.","While keeping your torso stationary, lift your elbows and start bending them as you pull the rope towards your neck while exhaling. Throughout the movement your upper arms should remain parallel to the floor. Tip: Continue this motion until your hands are almost next to your ears (the forearms will not be parallel to the floor at the end of the movement as they will be angled a bit upwards) and your elbows are out away from your sides.","After holding for a second or so at the contracted position, come back slowly to the starting position as you inhale. Tip: Again, during no part of the movement should the torso move.","Repeat for the recommended amount of repetitions."]', NULL, '["Low_Pulley_Row_To_Neck/0.jpg","Low_Pulley_Row_To_Neck/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Lower_Back-SMR', 'Lower Back-SMR', 'back', 'lower back', '[]', 'foam roll', 'stretching', 'beginner', '["In a seated position, place a foam roll under your lower back. Cross your arms in front of you and protract your shoulders. This will be your starting position.","Raise your hips off of the floor and lean back, keeping your weight on your lower back. Now shift your weight slightly to one side, keeping your weight off of the spine and on the muscles to the side of it. Roll over your lower back, holding points of tension for 10-30 seconds. Repeat on the other side."]', NULL, '["Lower_Back-SMR/0.jpg","Lower_Back-SMR/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Lunge_Pass_Through', 'Lunge Pass Through', 'upper legs', 'hamstrings', '["calves","glutes","quadriceps"]', 'kettlebells', 'strength', 'intermediate', '["Stand with your torso upright holding a kettlebell in your right hand. This will be your starting position.","Step forward with your left foot and lower your upper body down by flexing the hip and the knee, keeping the torso upright. Lower your back knee until it nearly touches the ground.","As you lunge, pass the kettlebell under your front leg to your opposite hand.","Pressing through the heel of your foot, return to the starting position.","Repeat the movement for the recommended amount of repetitions, alternating legs."]', NULL, '["Lunge_Pass_Through/0.jpg","Lunge_Pass_Through/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Lunge_Sprint', 'Lunge Sprint', 'upper legs', 'quadriceps', '["calves","glutes","hamstrings"]', 'machine', 'strength', 'intermediate', '["Adjust a bar in a Smith machine to an appropriate height. Position yourself under the bar, racking it across the back of your shoulders. Unrack the bar, and then split your feet, moving one foot forward and one foot back. This will be your starting position.","Lower your back knee nearly to the ground, flexing the knees and lowering your hips as you do so.","At the bottom of the descent, immediately reverse direction. Explosively drive through the heel of your front foot with light pressure from your back foot. Jump up and reverse the position of your legs.","Repeat for the recommended amount of repetitions."]', NULL, '["Lunge_Sprint/0.jpg","Lunge_Sprint/1.jpg"]', 9.8, 'sets', 0, 'fedb', 1),
('fe-Lying_Bent_Leg_Groin', 'Lying Bent Leg Groin', 'upper legs', 'adductors', '[]', 'other', 'stretching', 'expert', '["Lie on your back with your knees bent and the soles of the feet pressed together. Have your partner hold your knees. This will be your starting position.","Attempt to squeeze your knees together, while your partner prevents any movement from occurring.","After 10-20 seconds, relax your muscles as your partner gently pushes your knees towards the floor. Be sure to inform your helper when the stretch is adequate to prevent injury or overstretching."]', NULL, '["Lying_Bent_Leg_Groin/0.jpg","Lying_Bent_Leg_Groin/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Lying_Cable_Curl', 'Lying Cable Curl', 'upper arms', 'biceps', '[]', 'cable', 'strength', 'intermediate', '["Grab a straight bar or E-Z bar attachment that is attached to the low pulley with both hands, using an underhand (palms facing up) shoulder-width grip.","Lie flat on your back on top of an exercise mat in front of the weight stack with your feet flat against the frame of the pulley machine and your legs straight.","With your arms extended and your elbows close to your body slightly bend your arms. This will be your starting position.","While keeping your upper arms stationary and the elbows close to your body, curl the bar up slowly toward your chest as you breathe out and you squeeze the biceps.","After a second squeeze at the top of the movement, slowly return to the starting position.","Repeat for the recommended amount of repetitions."]', NULL, '["Lying_Cable_Curl/0.jpg","Lying_Cable_Curl/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Lying_Cambered_Barbell_Row', 'Lying Cambered Barbell Row', 'back', 'middle back', '["biceps","lats","traps"]', 'barbell', 'strength', 'beginner', '["Place a cambered bar underneath an exercise bench.","Lie face down on the exercise bench and grab the bar using a palms down (pronated grip) that is wider than shoulder width. This will be your starting position.","As you exhale row the bar up as you keep the elbows close to your body to either your chest, in order to target the upper mid back, or to your stomach if targeting the lats is your goal.","After a second hold at the top, lower back down to the starting position slowly as you inhale."]', NULL, '["Lying_Cambered_Barbell_Row/0.jpg","Lying_Cambered_Barbell_Row/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Lying_Close-Grip_Bar_Curl_On_High_Pulley', 'Lying Close-Grip Bar Curl On High Pulley', 'upper arms', 'biceps', '[]', 'cable', 'strength', 'beginner', '["Place a flat bench in front of a high pulley or lat pulldown machine.","Hold the straight bar attachment using an underhand grip (palms up) that is about shoulder width.","Lie on your back with your head over the end of the bench.","Now extend your arms straight above your shoulders. Your torso and your arms should make a 90-degree angle and the elbows should be in. This will be your starting position.","As you breathe out, curl the bar down in a semicircular motion until it touches your chin. Squeeze the biceps for a second at the top contracted position. Tip: As you execute this motion only the forearms should move. At no time should the upper arms be moving at all. They are to remain perpendicular throughout the movement.","Return to starting position slowly.","Repeat for the recommended amount of repetitions."]', NULL, '["Lying_Close-Grip_Bar_Curl_On_High_Pulley/0.jpg","Lying_Close-Grip_Bar_Curl_On_High_Pulley/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Lying_Close-Grip_Barbell_Triceps_Extension_Behind_The_Head', 'Lying Close-Grip Barbell Triceps Extension Behind The Head', 'upper arms', 'triceps', '[]', 'barbell', 'strength', 'intermediate', '["While holding a barbell or EZ Curl bar with a pronated grip (palms facing forward), lie on your back on a flat bench with your head close to the end of the bench. Tip: If you are holding a barbell grab it using a shoulder-width grip and if you are using an E-Z Bar grab it on the inner handles.","Extend your arms in front of you and slowly bring the bar back in a semi circular motion (while keeping the arms extended) to a position over your head. At the end of this step your arms should be overhead and parallel to the floor. This will be your starting position. Tip: Keep your elbows in at all times.","As you inhale, lower the bar by bending at the elbows and while keeping the upper arm stationary. Keep lowering the bar until your forearms are perpendicular to the floor.","As you exhale bring the bar back up to the starting position by pushing the bar up in a semi-circular motion until the lower arms are also parallel to the floor. Contract the triceps hard at the top of the movement for a second. Tip: Again, only the forearms should move. The upper arms should remain stationary at all times.","Repeat for the recommended amount of repetitions."]', NULL, '["Lying_Close-Grip_Barbell_Triceps_Extension_Behind_The_Head/0.jpg","Lying_Close-Grip_Barbell_Triceps_Extension_Behind_The_Head/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Lying_Close-Grip_Barbell_Triceps_Press_To_Chin', 'Lying Close-Grip Barbell Triceps Press To Chin', 'upper arms', 'triceps', '[]', 'e-z curl bar', 'strength', 'intermediate', '["While holding a barbell or EZ Curl bar with a pronated grip (palms facing forward), lie on your back on a flat bench with your head off the end of the bench. Tip: If you are holding a barbell grab it using a shoulder-width grip and if you are using an E-Z Bar grab it on the inner handles.","Extend your arms in front of you as you hold the barbell over your chest. The arms should be perpendicular to your torso (90-degree angle). This will be your starting position.","As you inhale, lower the bar in a semi-circular motion by bending at the elbows and while keeping the upper arm stationary and elbows in. Keep lowering the bar until it lightly touches your chin.","As you exhale bring the bar back up to the starting position by pushing the bar up in a semi-circular motion. Contract the triceps hard at the top of the movement for a second. Tip: Again, only the forearms should move. The upper arms should remain stationary at all times.","Repeat for the recommended amount of repetitions."]', NULL, '["Lying_Close-Grip_Barbell_Triceps_Press_To_Chin/0.jpg","Lying_Close-Grip_Barbell_Triceps_Press_To_Chin/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Lying_Crossover', 'Lying Crossover', 'upper legs', 'abductors', '[]', 'body only', 'stretching', 'expert', '["Lie on your back with your legs extended.","Cross one leg over your body with the knee bent, attempting to touch the knee to the ground. Your partner should kneel beside you, holding your shoulder down with one hand and controlling the crossed leg with the other. this will be your starting position.","Attempt to raise the bent knee off of the ground as your partner prevents any actual movement.","After 10-20 seconds, relax the leg as your partner gently presses the knee towards the floor. Repeat with the other side."]', NULL, '["Lying_Crossover/0.jpg","Lying_Crossover/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Lying_Face_Down_Plate_Neck_Resistance', 'Lying Face Down Plate Neck Resistance', 'neck', 'neck', '[]', 'other', 'strength', 'intermediate', '["Lie face down with your whole body straight on a flat bench while holding a weight plate behind your head. Tip: You will need to position yourself so that your shoulders are slightly above the end of a flat bench in order for the upper chest, neck and face to be off the bench. This will be your starting position.","While keeping the plate secure on the back of your head slowly lower your head (as in saying \"yes\") as you breathe in.","Raise your head back up to the starting position in a semi-circular motion as you breathe out. Hold the contraction for a second.","Repeat for the recommended amount of repetitions."]', NULL, '["Lying_Face_Down_Plate_Neck_Resistance/0.jpg","Lying_Face_Down_Plate_Neck_Resistance/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Lying_Face_Up_Plate_Neck_Resistance', 'Lying Face Up Plate Neck Resistance', 'neck', 'neck', '[]', 'other', 'strength', 'intermediate', '["Lie face up with your whole body straight on a flat bench while holding a weight plate on top of your forehead. Tip: You will need to position yourself so that your shoulders are slightly above the end of a flat bench in order for the traps, neck and head to be off the bench. This will be your starting position.","While keeping the plate secure on your forehead slowly lower your head back in a semi-circular motion as you breathe in.","Raise your head back up to the starting position in a semi-circular motion as you breathe out. Hold the contraction for a second.","Repeat for the recommended amount of repetitions."]', NULL, '["Lying_Face_Up_Plate_Neck_Resistance/0.jpg","Lying_Face_Up_Plate_Neck_Resistance/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Lying_Glute', 'Lying Glute', 'upper legs', 'glutes', '["abductors"]', 'body only', 'stretching', 'expert', '["Lie on your back with your partner kneeling beside you.","Flex the hip of one leg, raising it off of the floor. Rotate the leg so the foot is over the opposite hip, the lower leg perpendicular to your body. Your partner should hold the knee and ankle in place. This will be your starting position.","Attempt to push your leg towards your partner, who should be preventing any actual movement of the leg.","After 10-20 seconds, completely relax as your partner gently pushes the ankle and knee towards your chest. Be sure to inform your helper when the stretch is adequate to prevent injury or overstretching."]', NULL, '["Lying_Glute/0.jpg","Lying_Glute/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Lying_Hamstring', 'Lying Hamstring', 'upper legs', 'hamstrings', '["calves"]', 'other', 'stretching', 'expert', '["Lie on your back with your legs extended. Your partner should be kneeling beside you. Raise one leg up towards the ceiling and have your partner hold the ankle. Your partner can use their shoulder to brace your leg if necessary. This will be your starting position.","With your partner holding your leg in place, attempt to flex the knee, contracting the hamstrings for 10-20 seconds.","Then relax your leg, allowing your partner to gently push the leg towards your head. Be sure to inform your helper when the stretch is adequate to prevent injury or overstretching. Switch sides once complete."]', NULL, '["Lying_Hamstring/0.jpg","Lying_Hamstring/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Lying_High_Bench_Barbell_Curl', 'Lying High Bench Barbell Curl', 'upper arms', 'biceps', '[]', 'barbell', 'strength', 'intermediate', '["Lie face forward on a tall flat bench while holding a barbell with a supinated grip (palms facing up). Tip: If you are holding a barbell grab it using a shoulder-width grip and if you are using an E-Z Bar grab it on the inner handles. Your upper body should be positioned in a way that the upper chest is over the end of the bench and the barbell is hanging in front of you with the arms extended and perpendicular to the floor. This will be your starting position.","While keeping the elbows in and the upper arms stationary, curl the weight up in a semi-circular motion as you contract the biceps and exhale. Hold at the top of the movement for a second.","As you inhale, slowly go back to the starting position. Tip: Maintain full control of the weight at all times and avoid any swinging. Remember, only the forearms should move throughout the movement.","Repeat for the recommended amount of repetitions."]', NULL, '["Lying_High_Bench_Barbell_Curl/0.jpg","Lying_High_Bench_Barbell_Curl/1.jpg"]', 5, 'sets', 0, 'fedb', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('fe-Lying_Leg_Curls', 'Lying Leg Curls', 'upper legs', 'hamstrings', '[]', 'machine', 'strength', 'beginner', '["Adjust the machine lever to fit your height and lie face down on the leg curl machine with the pad of the lever on the back of your legs (just a few inches under the calves). Tip: Preferably use a leg curl machine that is angled as opposed to flat since an angled position is more favorable for hamstrings recruitment.","Keeping the torso flat on the bench, ensure your legs are fully stretched and grab the side handles of the machine. Position your toes straight (or you can also use any of the other two stances described on the foot positioning section). This will be your starting position.","As you exhale, curl your legs up as far as possible without lifting the upper legs from the pad. Once you hit the fully contracted position, hold it for a second.","As you inhale, bring the legs back to the initial position. Repeat for the recommended amount of repetitions."]', NULL, '["Lying_Leg_Curls/0.jpg","Lying_Leg_Curls/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Lying_Machine_Squat', 'Lying Machine Squat', 'upper legs', 'quadriceps', '["calves","glutes","hamstrings"]', 'machine', 'strength', 'intermediate', '["Adjust the leg machine to a height that will allow you to get inside it with your knees bent and the thighs slightly below parallel.","Once you select the weight, position yourself inside the machine face up with the knees bent and thighs slightly below parallel to the platform. Make sure that the knees do not go past the toes. The angle created between the hamstrings and the calves should be one that is slightly less than 90 degrees (since your starting position requires you to start slightly below parallel). Your back and your head should be resting on the machine while your shoulders are pressed under the shoulder pads.","Place your hands by the handles and position your feet slightly pointing out at a shoulder width position. This will be your starting position.","While pressing with the balls of the feet as you breathe out, make your whole body erect as you squeeze the quads. Hold the contracted position for a second. Tip: Since you are starting below parallel, you can opt to use your hands to help you up by pressing on your thighs only on the first repetition.","Slowly squat down as you inhale but instead of going all the way down to the starting position, just stop once your thighs are parallel to the platform. The angle between your hamstrings and calves should be a 90-degree angle.","Repeat for the recommended amount of repetitions."]', NULL, '["Lying_Machine_Squat/0.jpg","Lying_Machine_Squat/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Lying_One-Arm_Lateral_Raise', 'Lying One-Arm Lateral Raise', 'shoulders', 'shoulders', '[]', 'dumbbell', 'strength', 'intermediate', '["While holding a dumbbell in one hand, lay with your chest down on a flat bench. The other hand can be used to hold to the leg of the bench for stability.","Position the palm of the hand that is holding the dumbbell in a neutral manner (palms facing your torso) as you keep the arm extended with the elbow slightly bent. This will be your starting position.","Now raise the arm with the dumbbell to the side until your elbow is at shoulder height and your arm is roughly parallel to the floor as you exhale. Tip: Maintain your arm perpendicular to the torso while keeping your arm extended throughout the movement. Also, keep the contraction at the top for a second.","Slowly lower the dumbbell to the starting position as you inhale.","Repeat for the recommended amount of repetitions."]', NULL, '["Lying_One-Arm_Lateral_Raise/0.jpg","Lying_One-Arm_Lateral_Raise/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Lying_Prone_Quadriceps', 'Lying Prone Quadriceps', 'upper legs', 'quadriceps', '[]', 'body only', 'stretching', 'expert', '["Lay face down on the floor with your partner kneeling beside you. Flex one knee and raise that leg off the ground, attempting to touch your glutes with your foot. Your partner should hold the knee and ankle. This will be your starting position.","Attempt to extend your knee while your partner prevents any actual movement.","After 10-20 seconds, relax your muscles as your partner gently pushes the foot towards your glutes, further stretching the quadriceps and hip flexors.","After 10-20 seconds, switch sides."]', NULL, '["Lying_Prone_Quadriceps/0.jpg","Lying_Prone_Quadriceps/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Lying_Rear_Delt_Raise', 'Lying Rear Delt Raise', 'shoulders', 'shoulders', '[]', 'dumbbell', 'strength', 'intermediate', '["While holding a dumbbell in each hand, lay with your chest down on a flat bench.","Position the palms of the hands in a neutral manner (palms facing your torso) as you keep the arms extended with the elbows slightly bent. This will be your starting position.","Now raise the arms to the side until your elbows are at shoulder height and your arms are roughly parallel to the floor as you exhale. Tip: Maintain your arms perpendicular to the torso while keeping them extended throughout the movement. Also, keep the contraction at the top for a second.","Slowly lower the dumbbells to the starting position as you inhale.","Repeat for the recommended amount of repetitions and then switch to the other arm."]', NULL, '["Lying_Rear_Delt_Raise/0.jpg","Lying_Rear_Delt_Raise/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Lying_T-Bar_Row', 'Lying T-Bar Row', 'back', 'middle back', '["biceps","lats"]', 'machine', 'strength', 'intermediate', '["Load up the T-bar Row Machine with the desired weight and adjust the leg height so that your upper chest is at the top of the pad. Tip: In some machines all you can do is stand on the appropriate step that allows you to be at a height that has the upper chest at the top of the pad.","Lay face down on the pad and grab the handles. You can either use a palms down, palms up, or palms in position depending on what part of your back you want to emphasize.","Lift the bar off the rack and extend your arms in front of you. This will be your starting position.","As you exhale slowly pull the weight up and squeeze your back at the top of the movement. Tip: Keep the upper arms as close to the torso as possible throughout the movement in order to better engage the back muscles. Also, do not lift your body off of the pad at any time and refrain from using the biceps to lift the weight.","After a second contraction at the top of the movement, as you inhale, slowly go back down to the starting position.","Repeat for the recommended amount of repetitions."]', NULL, '["Lying_T-Bar_Row/0.jpg","Lying_T-Bar_Row/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Lying_Triceps_Press', 'Lying Triceps Press', 'upper arms', 'triceps', '[]', 'e-z curl bar', 'strength', 'intermediate', '["Lie on a flat bench with either an e-z bar (my preference) or a straight bar placed on the floor behind your head and your feet on the floor.","Grab the bar behind you, using a medium overhand (pronated) grip, and raise the bar in front of you at arms length. Tip: The arms should be perpendicular to the torso and the floor. The elbows should be tucked in. This is the starting position.","As you breathe in, slowly lower the weight until the bar lightly touches your forehead while keeping the upper arms and elbows stationary.","At that point, use the triceps to bring the weight back up to the starting position as you breathe out.","Repeat for the recommended amount of repetitions."]', NULL, '["Lying_Triceps_Press/0.jpg","Lying_Triceps_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Machine_Bench_Press', 'Machine Bench Press', 'chest', 'chest', '["shoulders","triceps"]', 'machine', 'strength', 'beginner', '["Sit down on the Chest Press Machine and select the weight.","Step on the lever provided by the machine since it will help you to bring the handles forward so that you can grab the handles and fully extend the arms.","Grab the handles with a palms-down grip and lift your elbows so that your upper arms are parallel to the floor to the sides of your torso. Tip: Your forearms will be pointing forward since you are grabbing the handles. Once you bring the handles forward and extend the arms you will be at the starting position.","Now bring the handles back towards you as you breathe in.","Push the handles away from you as you flex your pecs and you breathe out. Hold the contraction for a second before going back to the starting position.","Repeat for the recommended amount of reps.","When finished step on the lever again and slowly get the handles back to their original place."]', NULL, '["Machine_Bench_Press/0.jpg","Machine_Bench_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Machine_Bicep_Curl', 'Machine Bicep Curl', 'upper arms', 'biceps', '[]', 'machine', 'strength', 'beginner', '["Adjust the seat to the appropriate height and make your weight selection. Place your upper arms against the pads and grasp the handles. This will be your starting position.","Perform the movement by flexing the elbow, pulling your lower arm towards your upper arm.","Pause at the top of the movement, and then slowly return the weight to the starting position.","Avoid returning the weight all the way to the stops until the set is complete to keep tension on the muscles being worked."]', NULL, '["Machine_Bicep_Curl/0.jpg","Machine_Bicep_Curl/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Machine_Preacher_Curls', 'Machine Preacher Curls', 'upper arms', 'biceps', '[]', 'machine', 'strength', 'beginner', '["Sit down on the Preacher Curl Machine and select the weight.","Place the back of your upper arms (your triceps) on the preacher pad provided and grab the handles using an underhand grip (palms facing up). Tip: Make sure that when you place the arms on the pad you keep the elbows in. This will be your starting position.","Now lift the handles as you exhale and you contract the biceps. At the top of the position make sure that you hold the contraction for a second. Tip: Only the forearms should move. The upper arms should remain stationary and on the pad at all times.","Lower the handles slowly back to the starting position as you inhale.","Repeat for the recommended amount of repetitions."]', NULL, '["Machine_Preacher_Curls/0.jpg","Machine_Preacher_Curls/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Machine_Shoulder_Military_Press', 'Machine Shoulder (Military) Press', 'shoulders', 'shoulders', '["triceps"]', 'machine', 'strength', 'beginner', '["Sit down on the Shoulder Press Machine and select the weight.","Grab the handles to your sides as you keep the elbows bent and in line with your torso. This will be your starting position.","Now lift the handles as you exhale and you extend the arms fully. At the top of the position make sure that you hold the contraction for a second.","Lower the handles slowly back to the starting position as you inhale.","Repeat for the recommended amount of repetitions."]', NULL, '["Machine_Shoulder_Military_Press/0.jpg","Machine_Shoulder_Military_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Machine_Triceps_Extension', 'Machine Triceps Extension', 'upper arms', 'triceps', '[]', 'machine', 'strength', 'beginner', '["Adjust the seat to the appropriate height and make your weight selection. Place your upper arms against the pads and grasp the handles. This will be your starting position.","Perform the movement by extending the elbow, pulling your lower arm away from your upper arm.","Pause at the completion of the movement, and then slowly return the weight to the starting position.","Avoid returning the weight all the way to the stops until the set is complete to keep tension on the muscles being worked."]', NULL, '["Machine_Triceps_Extension/0.jpg","Machine_Triceps_Extension/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Medicine_Ball_Full_Twist', 'Medicine Ball Full Twist', 'waist', 'abdominals', '["shoulders"]', 'medicine ball', 'plyometrics', 'beginner', '["For this exercise you will need a medicine ball and a partner. Stand back to back with your partner, spaced 2-3 feet apart. This will be your starting position.","Hold the ball in front of the trunk. Open the hips and turn the shoulders at the same time as your partner.","For full rotation, you and your partner should twist in the same direction, i.e. counter-clockwise.","Pass the ball to your partner, and both of you can now twist in the opposite direction to repeat the procedure."]', NULL, '["Medicine_Ball_Full_Twist/0.jpg","Medicine_Ball_Full_Twist/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Medicine_Ball_Scoop_Throw', 'Medicine Ball Scoop Throw', 'shoulders', 'shoulders', '["abdominals","hamstrings","quadriceps"]', 'medicine ball', 'plyometrics', 'beginner', '["Assume a semisquat stance with a medicine ball in your hands. Your arms should hang so the ball is near your feet.","Begin by thrusting the hips forward as you extend through the legs, jumping up.","As you do, swing your arms up and over your head, keeping them extended, releasing the ball at the peak of your movement. The goal is to throw the ball the greatest distance behind you."]', NULL, '["Medicine_Ball_Scoop_Throw/0.jpg","Medicine_Ball_Scoop_Throw/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Middle_Back_Shrug', 'Middle Back Shrug', 'back', 'middle back', '[]', 'dumbbell', 'strength', 'intermediate', '["Lie facedown on an incline bench while holding a dumbbell in each hand. Your arms should be fully extended hanging down and pointing towards the floor. The palms of your hands should be facing each other. This will be your starting position.","As you exhale, squeeze your shoulder blades together and hold the contraction for a full second. Tip: This movement is just like the reverse action of a hug, or trying to perform rear laterals as if you had no arms.","As you inhale go back to the starting position.","Repeat for the recommended amount of repetitions."]', NULL, '["Middle_Back_Shrug/0.jpg","Middle_Back_Shrug/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Middle_Back_Stretch', 'Middle Back Stretch', 'back', 'middle back', '["abdominals","lats","lower back"]', 'body only', 'stretching', 'beginner', '["Stand so your feet are shoulder width apart and your hands are on your hips.","Twist at your waist until you feel a stretch. Hold for 10 to 15 seconds, then twist to the other side."]', NULL, '["Middle_Back_Stretch/0.jpg","Middle_Back_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Mixed_Grip_Chin', 'Mixed Grip Chin', 'back', 'middle back', '["biceps","lats"]', 'other', 'strength', 'expert', '["Using a spacing that is just about 1 inch wider than shoulder width, grab a pull-up bar with the palms of one hand facing forward and the palms of the other hand facing towards you. This will be your starting position.","Now start to pull yourself up as you exhale. Tip: With the arm that has the palms facing up concentrate on using the back muscles in order to perform the movement. The elbow of that arm should remain close to the torso. With the other arm that has the palms facing forward, the elbows will be away but in line with the torso. You will concentrate on using the lats to pull your body up.","After a second contraction at the top, start to slowly come down as you inhale.","Repeat for the recommended amount of repetitions.","On the following set, switch grips; so if you had the right hand with the palms facing you and the left one with the palms facing forward, on the next set you will have the palms facing forward for the right hand and facing you for the left."]', NULL, '["Mixed_Grip_Chin/0.jpg","Mixed_Grip_Chin/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Monster_Walk', 'Monster Walk', 'upper legs', 'abductors', '[]', 'bands', 'strength', 'beginner', '["Place a band around both ankles and another around both knees. There should be enough tension that they are tight when your feet are shoulder width apart.","To begin, take short steps forward alternating your left and right foot.","After several steps, do just the opposite and walk backward to where you started."]', NULL, '["Monster_Walk/0.jpg","Monster_Walk/1.jpg"]', 3.5, 'sets', 0, 'fedb', 1),
('fe-Mountain_Climbers', 'Mountain Climbers', 'upper legs', 'quadriceps', '["chest","hamstrings","shoulders"]', 'body only', 'plyometrics', 'beginner', '["Begin in a pushup position, with your weight supported by your hands and toes. Flexing the knee and hip, bring one leg until the knee is approximately under the hip. This will be your starting position.","Explosively reverse the positions of your legs, extending the bent leg until the leg is straight and supported by the toe, and bringing the other foot up with the hip and knee flexed. Repeat in an alternating fashion for 20-30 seconds."]', NULL, '["Mountain_Climbers/0.jpg","Mountain_Climbers/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Moving_Claw_Series', 'Moving Claw Series', 'upper legs', 'hamstrings', '["calves","quadriceps"]', 'body only', 'plyometrics', 'beginner', '["This move helps prepare your running form to help you excel at sprinting. As you run, be sure to flex the knee, aiming to kick your glutes as the hip extends.","Reload the quad as the leg moves back forward, attacking the ground on the next step.","Ensure that as you run, you block with the arms, punching through in a rapid 1-2 motion."]', NULL, '["Moving_Claw_Series/0.jpg","Moving_Claw_Series/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Muscle_Snatch', 'Muscle Snatch', 'upper legs', 'hamstrings', '["glutes","lower back","quadriceps","shoulders","triceps"]', 'barbell', 'olympic weightlifting', 'intermediate', '["Begin with a loaded barbell held at the mid thigh position with a wide grip. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar. This will be the starting position.","Begin the pull by driving through the front of the heels, raising the bar. Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body.","Continue raising the bar to the overhead position, without rebending the knees."]', NULL, '["Muscle_Snatch/0.jpg","Muscle_Snatch/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Muscle_Up', 'Muscle Up', 'back', 'lats', '["abdominals","biceps","forearms","middle back","shoulders","traps","triceps"]', 'other', 'strength', 'intermediate', '["Grip the rings using a false grip, with the base of your palms on top of the rings. Initiate a pull up by pulling the elbows down to your side, flexing the elbows.","As you reach the top position of the pull-up, pull the rings to your armpits as you roll your shoulders forward, allowing your elbows to move straight back behind you. This puts you into the proper position to continue into the dip portion of the movement.","Maintaining control and stability, extend through the elbow to complete the motion.","Use care when lowering yourself to the ground."]', NULL, '["Muscle_Up/0.jpg","Muscle_Up/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Narrow_Stance_Hack_Squats', 'Narrow Stance Hack Squats', 'upper legs', 'quadriceps', '["calves","glutes","hamstrings"]', 'machine', 'strength', 'intermediate', '["Place the back of your torso against the back pad of the machine and hook your shoulders under the shoulder pads provided.","Position your legs in the platform using a less than shoulder width narrow stance with the toes slightly pointed out. Your feet should be around 3 inches or less apart. Tip: Keep your head up at all times and also maintain the back on the pad at all times.","Place your arms on the side handles of the machine and disengage the safety bars (which on most designs is done by moving the side handles from a facing front position to a diagonal position).","Now straighten your legs without locking the knees. This will be your starting position.","Begin to slowly lower the unit by bending the knees as you maintain a straight posture with the head up (back on the pad at all times). Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement.","Begin to raise the unit as you exhale by pushing the floor with mainly with the heels of your feet as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."]', NULL, '["Narrow_Stance_Hack_Squats/0.jpg","Narrow_Stance_Hack_Squats/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Narrow_Stance_Leg_Press', 'Narrow Stance Leg Press', 'upper legs', 'quadriceps', '["calves","glutes","hamstrings"]', 'machine', 'strength', 'intermediate', '["Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a less-than-shoulder-width narrow stance with the toes slightly pointed out. Your feet should be around 3 inches or less apart. Tip: Keep your head up at all times and also maintain the back on the pad at all times.","Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you. Tip: Make sure that you do not lock your knees. Your torso and the legs should make a perfect 90-degree angle. This will be your starting position.","As you inhale, slowly lower the platform until your upper and lower legs make a 90-degree angle.","Pushing mainly with the heels of your feet and using the quadriceps go back to the starting position as you exhale.","Repeat for the recommended amount of repetitions and ensure to lock the safety pins properly once you are done. You do not want that platform falling on you fully loaded."]', NULL, '["Narrow_Stance_Leg_Press/0.jpg","Narrow_Stance_Leg_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Narrow_Stance_Squats', 'Narrow Stance Squats', 'upper legs', 'quadriceps', '["calves","glutes","hamstrings","lower back"]', 'barbell', 'strength', 'intermediate', '["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.","Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Step away from the rack and position your legs using a less-than-shoulder-width narrow stance with the toes slightly pointed out. Feet should be around 3-6 inches apart. Keep your head up at all times (looking down will get you off balance) and maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).","Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the bar as you exhale by pushing the floor with the heel of your foot mainly as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."]', NULL, '["Narrow_Stance_Squats/0.jpg","Narrow_Stance_Squats/1.jpg"]', 5, 'sets', 0, 'fedb', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('fe-Natural_Glute_Ham_Raise', 'Natural Glute Ham Raise', 'upper legs', 'hamstrings', '["calves","glutes","lower back"]', 'body only', 'strength', 'intermediate', '["Using the leg pad of a lat pulldown machine or a preacher bench, position yourself so that your ankles are under the pads, knees on the seat, and you are facing away from the machine. You should be upright and maintaining good posture.","This will be your starting position. Lower yourself under control until your knees are almost completely straight.","Remaining in control, raise yourself back up to the starting position.","If you are unable to complete a rep, use a band, a partner, or push off of a box to aid in completing a repetition."]', NULL, '["Natural_Glute_Ham_Raise/0.jpg","Natural_Glute_Ham_Raise/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Neck-SMR', 'Neck-SMR', 'neck', 'neck', '[]', 'other', 'stretching', 'intermediate', '["Using a muscle roller or a rolling pin, place the roller behind your head and against your neck. Make sure that you do not place the roller directly against the spine, but turned slightly so that the roller is pressed against the muscles to either side of the spine. This will be your starting position.","Starting at the top of your neck, slowly roll down the muscles of your neck, pausing at points of tension for 10-30 seconds."]', NULL, '["Neck-SMR/0.jpg","Neck-SMR/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Neck_Press', 'Neck Press', 'chest', 'chest', '["shoulders","triceps"]', 'barbell', 'strength', 'intermediate', '["Lie back on a flat bench. Using a medium-width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over your neck with your arms locked. This will be your starting position.","As you breathe in, come down slowly until you feel the bar on your neck.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up).","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the bar back in the rack."]', NULL, '["Neck_Press/0.jpg","Neck_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Oblique_Crunches', 'Oblique Crunches', 'waist', 'abdominals', '[]', 'body only', 'strength', 'beginner', '["Lie flat on the floor with your lower back pressed to the ground. For this exercise, you will need to put one hand beside your head and the other to the side against the floor.","Make sure your feet are elevated and resting on a flat surface.","Now lift the shoulder in which your hand is touching your head.","Simply elevate your shoulder and body upward until you touch your knee. For example, if you have your right hand besides your head, then you want to elevate your body upwards until your right elbow touches your left knee. The same variation can be applied doing the inverse and using your left elbow to touch your right knee.","After your knee touches your elbow, lower your body until you have reached the starting position.","Remember to breathe in during the eccentric (lowering) part of the exercise and to breathe out during the concentric (upward) part of the exercise.","Continue alternating in this manner until all of the recommended repetitions for each side have been completed."]', NULL, '["Oblique_Crunches/0.jpg","Oblique_Crunches/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Olympic_Squat', 'Olympic Squat', 'upper legs', 'quadriceps', '["calves","glutes","hamstrings"]', 'barbell', 'olympic weightlifting', 'intermediate', '["Begin with a barbell supported on top of the traps. The chest should be up, and the head facing forward. Adopt a hip width stance with the feet turned out as needed.","Descend by flexing the knees, refraining from moving the hips back as much as possible. This requires that the knees travel forward; ensure that they stay aligned with the feet. The goal is to keep the torso as upright as possible. Continue all the way down, keeping the weight on the front of the heel.","At the moment the upper legs contact the lower, reverse the motion, driving the weight upward."]', NULL, '["Olympic_Squat/0.jpg","Olympic_Squat/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-On-Your-Back_Quad_Stretch', 'On-Your-Back Quad Stretch', 'upper legs', 'quadriceps', '[]', 'other', 'stretching', 'beginner', '["Lie on a flat bench or step, and hang one leg and arm over the side.","Bend the knee and hold the top of the foot. As you do this, be careful not to arch your lower back.","Pull the belly button to the spine to stay in neutral. Press your foot down and into your hand. To add the hip stretch, lift the hip of the leg you''re holding up toward the ceiling.","Switch sides."]', NULL, '["On-Your-Back_Quad_Stretch/0.jpg","On-Your-Back_Quad_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-On_Your_Side_Quad_Stretch', 'On Your Side Quad Stretch', 'upper legs', 'quadriceps', '[]', 'body only', 'stretching', 'beginner', '["Start off by lying on your right side, with your right knee bent at a 90-degree angle resting on the floor in front of you (this stabilizes the torso).","Bend your left knee behind you and hold your left foot with your left hand. To stretch your hip flexor, press your left hip forward as you push your left foot back into your hand. Switch sides."]', NULL, '["On_Your_Side_Quad_Stretch/0.jpg","On_Your_Side_Quad_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-One-Arm_Dumbbell_Row', 'One-Arm Dumbbell Row', 'back', 'middle back', '["biceps","lats","shoulders"]', 'dumbbell', 'strength', 'beginner', '["Choose a flat bench and place a dumbbell on each side of it.","Place the right leg on top of the end of the bench, bend your torso forward from the waist until your upper body is parallel to the floor, and place your right hand on the other end of the bench for support.","Use the left hand to pick up the dumbbell on the floor and hold the weight while keeping your lower back straight. The palm of the hand should be facing your torso. This will be your starting position.","Pull the resistance straight up to the side of your chest, keeping your upper arm close to your side and keeping the torso stationary. Breathe out as you perform this step. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. Also, make sure that the force is performed with the back muscles and not the arms. Finally, the upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the dumbbell; therefore do not try to pull the dumbbell up using the forearms.","Lower the resistance straight down to the starting position. Breathe in as you perform this step.","Repeat the movement for the specified amount of repetitions.","Switch sides and repeat again with the other arm."]', NULL, '["One-Arm_Dumbbell_Row/0.jpg","One-Arm_Dumbbell_Row/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-One-Arm_Flat_Bench_Dumbbell_Flye', 'One-Arm Flat Bench Dumbbell Flye', 'chest', 'chest', '[]', 'dumbbell', 'strength', 'beginner', '["Lie down on a flat bench with a dumbbell in one hand resting on top of your thigh. The palm of your hand with the dumbbell in it should be at a neutral grip.","By using your thighs to help you get the dumbbell up, clean the dumbbell so that you can hold it in front of you with your lifting arm being fully extended. Remember to maintain a neutral grip with this exercise. Your non lifting hand should be to the side holding the flat bench for better support. This will be your starting position.","Your arm with the weight should have a slight bend on your elbow in order to prevent stress at the biceps tendon. Begin by lowering your arm with the weight in it out in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, your lifting arm should remain stationary; the movement should only occur at the shoulder joint.","Return your lifting arm back to the starting position as you squeeze your chest muscles and breathe out. Tip: Make sure to use the same arc of motion used to lower the weights.","Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions.","Switch arms and repeat the exercise."]', NULL, '["One-Arm_Flat_Bench_Dumbbell_Flye/0.jpg","One-Arm_Flat_Bench_Dumbbell_Flye/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-One-Arm_High-Pulley_Cable_Side_Bends', 'One-Arm High-Pulley Cable Side Bends', 'waist', 'abdominals', '[]', 'cable', 'strength', 'beginner', '["Connect a standard handle to a tower. Move cable to highest pulley position.","Stand with side to cable. With one hand, reach up and grab handle with underhand grip.","Pull down cable until elbow touches your side and the handle is by your shoulder.","Position feet hip-width apart. Place free hand on hip to help gauge pivot point.","Keep arm in static position. Contract oblique to bring the weight down in a side crunch.","Once you reach maximum contraction, slowly release the weight to the starting position. The weight stack should never be unloaded in a resting position. The aim is constant tension during the set.","Repeat to failure.","Then, reposition and repeat the same series of movements on the opposite side."]', NULL, '["One-Arm_High-Pulley_Cable_Side_Bends/0.jpg","One-Arm_High-Pulley_Cable_Side_Bends/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-One-Arm_Incline_Lateral_Raise', 'One-Arm Incline Lateral Raise', 'shoulders', 'shoulders', '[]', 'dumbbell', 'strength', 'beginner', '["Lie down sideways on an incline bench press with a dumbbell in the hand. Make sure the shoulder is pressing against the incline bench and the arm is lying across your body with the palm around your navel.","Hold a dumbbell in your uppermost arm while keeping it extended in front of you parallel to the floor. This is your starting position.","While keeping the dumbbell parallel to the floor at all times, perform a lateral raise. Your arm should travel straight up until it is pointing at the ceiling. Tip: Exhale as you perform this movement. Hold the dumbbell in the position and feel the contraction in the shoulders for a second.","While inhaling lower the weight across your body back into the starting position.","Repeat the movement for the prescribed amount of repetitions.","Switch arms and repeat the movement."]', NULL, '["One-Arm_Incline_Lateral_Raise/0.jpg","One-Arm_Incline_Lateral_Raise/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-One-Arm_Kettlebell_Clean', 'One-Arm Kettlebell Clean', 'upper legs', 'hamstrings', '["glutes","lower back","shoulders","traps"]', 'kettlebells', 'strength', 'intermediate', '["Place a kettlebell between your feet. As you bend down to grab the kettlebell, push your butt back and keep your eyes looking forward.","Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so.","Return the weight to the starting position."]', NULL, '["One-Arm_Kettlebell_Clean/0.jpg","One-Arm_Kettlebell_Clean/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-One-Arm_Kettlebell_Para_Press', 'One-Arm Kettlebell Para Press', 'shoulders', 'shoulders', '["triceps"]', 'kettlebells', 'strength', 'intermediate', '["Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position.","Hold the kettlebell with the elbow out to the side, and press it up and out until it is locked out overhead.","Lower the kettlebell back to your shoulder under control and repeat. Make sure to contract your lat, butt, and stomach forcefully for added stability and strength."]', NULL, '["One-Arm_Kettlebell_Para_Press/0.jpg","One-Arm_Kettlebell_Para_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-One-Arm_Kettlebell_Split_Jerk', 'One-Arm Kettlebell Split Jerk', 'shoulders', 'shoulders', '["glutes","hamstrings","quadriceps","triceps"]', 'kettlebells', 'strength', 'intermediate', '["Hold a kettlebell by the handle. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position.","Dip your body by bending the knees, keeping your torso upright.","Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, using your body''s momentum to move the weight.","Receive the weight overhead by returning to a squat position underneath the weight, positioning one leg in front of you and one leg behind you.","Keeping the weight overhead, return to a standing position and bring your feet together. Lower the weight to perform the next repetition."]', NULL, '["One-Arm_Kettlebell_Split_Jerk/0.jpg","One-Arm_Kettlebell_Split_Jerk/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-One-Arm_Kettlebell_Split_Snatch', 'One-Arm Kettlebell Split Snatch', 'shoulders', 'shoulders', '["hamstrings","quadriceps"]', 'kettlebells', 'strength', 'expert', '["Hold a kettlebell in one hand by the handle.","Squat towards the floor, and then reverse the motion, extending the hips, knees, and finally the ankles, to raise the kettlebell overhead.","After fully extending the body, descend into a lunge position to receive the weights overhead, one leg forward and one leg back. Ensure you drive through with your hips and lock the ketttlebells overhead in one uninterrupted motion.","Return to a standing position, holding the weight overhead, and bring the feet together. Lower the weight to return to the starting position."]', NULL, '["One-Arm_Kettlebell_Split_Snatch/0.jpg","One-Arm_Kettlebell_Split_Snatch/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-One-Arm_Kettlebell_Swings', 'One-Arm Kettlebell Swings', 'upper legs', 'hamstrings', '["calves","glutes","lower back","shoulders"]', 'kettlebells', 'strength', 'intermediate', '[]', NULL, '["One-Arm_Kettlebell_Swings/0.jpg","One-Arm_Kettlebell_Swings/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-One-Arm_Long_Bar_Row', 'One-Arm Long Bar Row', 'back', 'middle back', '["biceps","lats"]', 'barbell', 'strength', 'beginner', '["Position a bar into a landmine or in a corner to keep it from moving. Load an appropriate weight onto your end.","Stand next to the bar, and take a grip with one hand close to the collar. Using your hips and legs, rise to a standing position.","Assume a bent-knee stance with your hips back and your chest up. Your arm should be extended. This will be your starting position.","Pull the weight to your side by retracting the shoulder and flexing the elbow. Do not jerk the weight or cheat during the movement.","After a brief pause, return to the starting position."]', NULL, '["One-Arm_Long_Bar_Row/0.jpg","One-Arm_Long_Bar_Row/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-One-Arm_Open_Palm_Kettlebell_Clean', 'One-Arm Open Palm Kettlebell Clean', 'upper legs', 'hamstrings', '["forearms","glutes","lower back","quadriceps","shoulders"]', 'kettlebells', 'strength', 'intermediate', '["Place one kettlebell between your feet.","Grab the handle with one hand and raise the kettlebell rapidly, let it flip so that the ball of the kettlebell lands in the palm of your hand.","Throw the kettlebell out in front of you and catch the handle with one hand.","Take the kettlebell to the floor and repeat. Make sure to work both arms."]', NULL, '["One-Arm_Open_Palm_Kettlebell_Clean/0.jpg","One-Arm_Open_Palm_Kettlebell_Clean/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-One-Arm_Overhead_Kettlebell_Squats', 'One-Arm Overhead Kettlebell Squats', 'upper legs', 'quadriceps', '["calves","glutes","hamstrings","shoulders"]', 'kettlebells', 'strength', 'expert', '["Clean and press a kettlebell with one arm. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so. Press the weight overhead by extending through the elbow.This will be your starting position.","Looking straight ahead and keeping a kettlebell locked out above you, flex the knees and hips and lower your torso between your legs, keeping your head and chest up.","Pause at the bottom position for a second before rising back to the top, driving through the heels of your feet."]', NULL, '["One-Arm_Overhead_Kettlebell_Squats/0.jpg","One-Arm_Overhead_Kettlebell_Squats/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-One-Arm_Side_Deadlift', 'One-Arm Side Deadlift', 'upper legs', 'quadriceps', '["abdominals","calves","glutes","hamstrings","lower back","traps"]', 'barbell', 'strength', 'expert', '["Stand to the side of a barbell next to its center. Bend your knees and lower your body until you are able to reach the barbell.","Grasp the bar as if you were grabbing a briefcase (palms facing you since the bar is sideways). You may need a wrist wrap if you are using a significant amount of weight. This is your starting position.","Use your legs to help lift the barbell up while exhaling. Your arms should extend fully as bring the barbell up until you are in a standing position.","Slowly bring the barbell back down while inhaling. Tip: Make sure to bend your knees while lowering the weight to avoid any injury from occurring.","Repeat for the recommended amount of repetitions.","Switch arms and repeat the movement."]', NULL, '["One-Arm_Side_Deadlift/0.jpg","One-Arm_Side_Deadlift/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-One-Arm_Side_Laterals', 'One-Arm Side Laterals', 'shoulders', 'shoulders', '[]', 'dumbbell', 'strength', 'beginner', '["Pick a dumbbell and place it in one of your hands. Your non lifting hand should be used to grab something steady such as an incline bench press. Lean towards your lifting arm and away from the hand that is gripping the incline bench as this will allow you to keep your balance.","Stand with a straight torso and have the dumbbell by your side at arm''s length with the palm of the hand facing you. This will be your starting position.","While maintaining the torso stationary (no swinging), lift the dumbbell to your side with a slight bend on the elbow and your hand slightly tilted forward as if pouring water in a glass. Continue to go up until you arm is parallel to the floor. Exhale as you execute this movement and pause for a second at the top.","Lower the dumbbell back down slowly to the starting position as you inhale.","Repeat for the recommended amount of repetitions.","Switch arms and repeat the exercise."]', NULL, '["One-Arm_Side_Laterals/0.jpg","One-Arm_Side_Laterals/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-One-Legged_Cable_Kickback', 'One-Legged Cable Kickback', 'upper legs', 'glutes', '["hamstrings"]', 'cable', 'strength', 'intermediate', '["Hook a leather ankle cuff to a low cable pulley and then attach the cuff to your ankle.","Face the weight stack from a distance of about two feet, grasping the steel frame for support.","While keeping your knees and hips bent slightly and your abs tight, contract your glutes to slowly \"kick\" the working leg back in a semicircular arc as high as it will comfortably go as you breathe out. Tip: At full extension, squeeze your glutes for a second in order to achieve a peak contraction.","Now slowly bring your working leg forward, resisting the pull of the cable until you reach the starting position.","Repeat for the recommended amount of repetitions.","Switch legs and repeat the movement for the other side."]', NULL, '["One-Legged_Cable_Kickback/0.jpg","One-Legged_Cable_Kickback/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-One_Arm_Against_Wall', 'One Arm Against Wall', 'back', 'lats', '[]', 'body only', 'stretching', 'beginner', '["From a standing position, place a bent arm against a wall or doorway.","Slowly lean toward your arm until you feel a stretch in your lats."]', NULL, '["One_Arm_Against_Wall/0.jpg","One_Arm_Against_Wall/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-One_Arm_Chin-Up', 'One Arm Chin-Up', 'back', 'middle back', '["biceps","forearms","lats"]', 'other', 'strength', 'expert', '["For this exercise, start out by placing a towel around a chin up bar.","Grab the chin-up bar with your palm facing you. One hand will be grabbing the chin-up bar and the other will be grabbing the towel.","Bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.v","Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.","After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.","Repeat this motion for the prescribed amount of repetitions.","Switch arms and repeat the movement."]', NULL, '["One_Arm_Chin-Up/0.jpg","One_Arm_Chin-Up/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-One_Arm_Dumbbell_Bench_Press', 'One Arm Dumbbell Bench Press', 'chest', 'chest', '["shoulders","triceps"]', 'dumbbell', 'strength', 'beginner', '["Lie down on a flat bench with a dumbbell in one hand on top of your thigh.","By using your thigh to help you get the dumbbell up, clean the dumbbell up so that you can hold it in front of you at shoulder width. Use the hand you are not lifting with to help position the dumbbell over you properly.","Once at shoulder width, rotate your wrist forward so that the palm of your hand is facing away from you. This will be your starting position.","Bring down the weights slowly to your side as you breathe in. Keep full control of the dumbbell at all times. Tip: Use the hand that you are not lifting with to help keep the dumbbell balance as you may struggle a bit at first. Only use your non-lifting hand if it is needed. Otherwise, keep it resting to the side.","As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions of your training program.","Switch arms and repeat the movement."]', NULL, '["One_Arm_Dumbbell_Bench_Press/0.jpg","One_Arm_Dumbbell_Bench_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('fe-One_Arm_Dumbbell_Preacher_Curl', 'One Arm Dumbbell Preacher Curl', 'upper arms', 'biceps', '[]', 'dumbbell', 'strength', 'beginner', '["Grab a dumbbell with the right arm and place the upper arm on top of the preacher bench or the incline bench. The dumbbell should be held at shoulder length. This will be your starting position.","As you breathe in, slowly lower the dumbbell until your upper arm is extended and the biceps is fully stretched.","As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the dumbbell is at shoulder height. Again, remember that to ensure full contraction you need to bring that small finger higher than the thumb.","Squeeze the biceps hard for a second at the contracted position and repeat for the recommended amount of repetitions.","Switch arms and repeat the movement."]', NULL, '["One_Arm_Dumbbell_Preacher_Curl/0.jpg","One_Arm_Dumbbell_Preacher_Curl/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-One_Arm_Floor_Press', 'One Arm Floor Press', 'upper arms', 'triceps', '["chest","shoulders"]', 'barbell', 'strength', 'intermediate', '["Lie down on a flat surface with your back pressing against the floor or an exercise mat. Make sure your knees are bent.","Have a partner hand you the bar on one hand. When starting, your arm should be just about fully extended, similar to the starting position of a barbell bench press. However, this time your grip will be neutral (palms facing your torso).","Make sure the hand you are not using to lift the weight is placed by your side.","Begin the exercise by lowering the barbell until your elbow touches the ground. Make sure to breathe in as this is the eccentric (lowering part of the exercise).","Then start lifting the barbell back up to the original starting position. Remember to breathe out during the concentric (lifting part of the exercise).","Repeat until you have performed your recommended repetitions.","Switch arms and repeat the movement."]', NULL, '["One_Arm_Floor_Press/0.jpg","One_Arm_Floor_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-One_Arm_Lat_Pulldown', 'One Arm Lat Pulldown', 'back', 'lats', '["biceps","middle back"]', 'cable', 'strength', 'beginner', '["Select an appropriate weight and adjust the knee pad to help keep you down. Grasp the handle with a pronated grip. This will be your starting position.","Pull the handle down, squeezing your elbow to your side as you flex the elbow.","Pause at the bottom of the motion, and then slowly return the handle to the starting position.","For multiple repetitions, avoid completely returning the weight to keep tension on the muscles being worked."]', NULL, '["One_Arm_Lat_Pulldown/0.jpg","One_Arm_Lat_Pulldown/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-One_Arm_Pronated_Dumbbell_Triceps_Extension', 'One Arm Pronated Dumbbell Triceps Extension', 'upper arms', 'triceps', '[]', 'dumbbell', 'strength', 'beginner', '["Lie flat on a bench while holding a dumbbell at arms length. Your arm should be perpendicular to your body. The palm of your hand should be facing towards your feet as a pronated grip is required to perform this exercise.","Place your non lifting hand on your bicep for support.","Slowly begin to lower the dumbbell down as you breathe in.","Then, begin lifting the dumbbell upward as you contract the triceps. Remember to breathe out during the concentric (lifting part of the exercise).","Repeat until you have performed your set repetitions.","Switch arms and repeat the movement."]', NULL, '["One_Arm_Pronated_Dumbbell_Triceps_Extension/0.jpg","One_Arm_Pronated_Dumbbell_Triceps_Extension/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-One_Arm_Supinated_Dumbbell_Triceps_Extension', 'One Arm Supinated Dumbbell Triceps Extension', 'upper arms', 'triceps', '[]', 'dumbbell', 'strength', 'beginner', '["Lie flat on a bench while holding a dumbbell at arms length. Your arm should be perpendicular to your body. The palm of your hand should be facing towards your face as a supinated grip is required to perform this exercise.","Place your non lifting hand on your bicep for support.","Slowly begin to lower the dumbbell down as you breathe in.","Then, begin lifting the dumbbell upward as you contract the triceps. Remember to breathe out during the concentric (lifting part of the exercise).","Repeat until you have performed your set repetitions.","Switch arms and repeat the movement.","Switch arms again and repeat the movement."]', NULL, '["One_Arm_Supinated_Dumbbell_Triceps_Extension/0.jpg","One_Arm_Supinated_Dumbbell_Triceps_Extension/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-One_Half_Locust', 'One Half Locust', 'upper legs', 'quadriceps', '["abdominals","biceps","chest"]', 'body only', 'stretching', 'beginner', '["Lie facedown on the floor.","Put your left hand under your left hipbone to pad your hip and pubic bone.","Bend your right knee so you can hold the foot in your right hand.","Lift the foot in the air and simultaneously lift your shoulders off the floor. This also stretches the right hip flexor and the chest and shoulders. Switch sides. If it doesn''t bother your back, you can try it with both arms and legs at the same time."]', NULL, '["One_Half_Locust/0.jpg","One_Half_Locust/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-One_Handed_Hang', 'One Handed Hang', 'back', 'lats', '["biceps"]', 'other', 'stretching', 'beginner', '["Grab onto a chinup bar with one hand, using a pronated grip. Keep your feet on the floor or a step. Allow the majority of your weight to hang from that hand, while keeping your feet on the ground. Hold for 10-20 seconds and switch sides."]', NULL, '["One_Handed_Hang/0.jpg","One_Handed_Hang/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-One_Knee_To_Chest', 'One Knee To Chest', 'upper legs', 'glutes', '["hamstrings","lower back"]', 'body only', 'stretching', 'beginner', '["Start off by lying on the floor.","Extend one leg straight and pull the other knee to your chest. Hold under the knee joint to protect the kneecap.","Gently tug that knee toward your nose.","Switch sides. This stretches the buttocks and lower back of the bent leg and the hip flexor of the straight leg."]', NULL, '["One_Knee_To_Chest/0.jpg","One_Knee_To_Chest/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Open_Palm_Kettlebell_Clean', 'Open Palm Kettlebell Clean', 'upper legs', 'hamstrings', '["glutes","lower back","quadriceps","shoulders"]', 'kettlebells', 'strength', 'expert', '["Place one kettlebell between your feet. Clean the kettlebell by extending through the legs and hips as you raise the kettlebell towards your shoulders.","Release the kettlebell as it comes up, and let it flip so that the ball of the kettlebell lands in the palms of your hands.","Release the kettlebell out in front of you and catch the handle with both hands. Lower the kettlebell to the starting position and repeat."]', NULL, '["Open_Palm_Kettlebell_Clean/0.jpg","Open_Palm_Kettlebell_Clean/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Otis-Up', 'Otis-Up', 'waist', 'abdominals', '["chest","shoulders","triceps"]', 'other', 'strength', 'beginner', '["Secure your feet and lay back on the floor. Your knees should be bent. Hold a weight with both hands to your chest. This will be your starting position.","Initiate the movement by flexing the hips and spine to raise your torso up from the ground.","As you move up, press the weight up so that it is above your head at the top of the movement.","Return the weight to your chest as you reverse the sit-up motion, ensuring not to go all the way down to the floor."]', NULL, '["Otis-Up/0.jpg","Otis-Up/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Overhead_Lat', 'Overhead Lat', 'back', 'lats', '["triceps"]', 'other', 'stretching', 'expert', '["Sit upright on the floor with your partner behind you. Raise one arm straight up, and flex the elbow, attempting to touch your hand to your back. Your parner should hold your tricep and wrist. This will be your starting position.","Attempt to pull your upper arm to your side as your partner prevents you from doing actually doing so.","After 10-20 seconds, relax the arm and allow your partner to further stretch the lat by applying gentle pressure to the tricep. Hold for 10-20 seconds, and then switch sides."]', NULL, '["Overhead_Lat/0.jpg","Overhead_Lat/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Overhead_Slam', 'Overhead Slam', 'back', 'lats', '[]', 'medicine ball', 'plyometrics', 'beginner', '["Hold a medine ball with both hands and stand with your feet at shoulder width. This will be your starting position.","Initiate the countermovement by raising the ball above your head and fully extending your body.","Reverse the motion, slamming the ball into the ground directly in front of you as hard as you can.","Receive the ball with both hands on the bounce and repeat the movement."]', NULL, '["Overhead_Slam/0.jpg","Overhead_Slam/1.jpg"]', 8, 'sets', 0, 'fedb', 1),
('fe-Overhead_Squat', 'Overhead Squat', 'upper legs', 'quadriceps', '["abdominals","calves","glutes","hamstrings","lower back","shoulders","triceps"]', 'barbell', 'olympic weightlifting', 'expert', '["Start out by having a barbell in front of you on the floor. Your feet should be wider than shoulder width apart from each other.","Bend the knees and use a pronated grip (palms facing you) to grab the barbell. Your hands should be at a wider than shoulder width apart from each other before lifting. Once you are positioned, lift the barbell up until you can rest it on your chest.","Move the barbell over and slightly behind your head and make sure your arms are fully extended. Keep your head up at all times and also maintain a straight back. Retract your shoulder blades. This is your starting position.","Slowly lower the weight by bending your knees until your thighs are parallel to the ground while inhaling. Tip: Keep your back straight while performing this exercise to avoid any injuries and your arms should remain extended and over your head at all times.","Now use your feet and legs to help bring the weight back up to the starting position while exhaling.","Repeat for the recommended amount of repetitions."]', NULL, '["Overhead_Squat/0.jpg","Overhead_Squat/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Overhead_Stretch', 'Overhead Stretch', 'waist', 'abdominals', '["chest","forearms","lats","triceps"]', 'body only', 'stretching', 'beginner', '["Standing straight up, lace your fingers together and open your palms to the ceiling. Keep your shoulders down as you extend your arms up.","To create a full torso stretch, pull your tailbone down and stabilize your torso as you do this. Stretch the muscles on both the front and the back of the torso."]', NULL, '["Overhead_Stretch/0.jpg","Overhead_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Overhead_Triceps', 'Overhead Triceps', 'upper arms', 'triceps', '["lats"]', 'body only', 'stretching', 'expert', '["Sit upright on the floor with your partner behind you. Raise one arm straight up, and flex the elbow, attempting to touch your hand to your back. Your parner should hold your elbow and wrist. This will be your starting position.","Attempt to extend the arm straight into the air as your partner prevents you from doing actually doing so.","After 10-20 seconds, relax the arm and allow your partner to further stretch the tricep by applying gentle pressure to the wrist. Hold for 10-20 seconds, and then switch sides."]', NULL, '["Overhead_Triceps/0.jpg","Overhead_Triceps/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Pallof_Press', 'Pallof Press', 'waist', 'abdominals', '["chest","shoulders","triceps"]', 'cable', 'strength', 'beginner', '["Connect a standard handle to a tower, and—if possible—position the cable to shoulder height. If not, a low pulley will suffice.","With your side to the cable, grab the handle with both hands and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable.","With your feet positioned hip-width apart and knees slightly bent, hold the cable to the middle of your chest. This will be your starting position.","Press the cable away from your chest, fully extending both arms. You core should be tight and engaged.","Hold the repetition for several seconds before returning to the starting position.","At the conclusion of the set, repeat facing the other direction."]', NULL, '["Pallof_Press/0.jpg","Pallof_Press/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Pallof_Press_With_Rotation', 'Pallof Press With Rotation', 'waist', 'abdominals', '["chest","shoulders","triceps"]', 'cable', 'strength', 'beginner', '["Connect a standard handle to a tower, and position the cable to shoulder height.","With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Align outstretched arm with cable.","With your feet positioned hip-width apart, pull the cable into your chest and grab the handle with your other hand. Both hands should be on the handle at this time.","Facing forward, press the cable away from your chest. You core should be tight and engaged.","Keeping your hips straight, twist your torso away from the pulley until you get a full quarter rotation.","Maintain your rigid stance and straight arms. Return to the neutral position in a slow and controlled manner. Your arms should be extended in front of you.","With the side tension still engaging your core, bring your hands to your chest and immediately press outward to a fully extended position. This constitutes one rep.","Repeat to failure.","Then, reposition and repeat the same series of movements on the opposite side."]', NULL, '["Pallof_Press_With_Rotation/0.jpg","Pallof_Press_With_Rotation/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench', 'Palms-Down Dumbbell Wrist Curl Over A Bench', 'lower arms', 'forearms', '[]', 'dumbbell', 'strength', 'beginner', '["Start out by placing two dumbbells on one side of a flat bench.","Kneel down on both of your knees so that your body is facing the flat bench.","Use your arms to grab both of the dumbbells with a pronated grip (palms facing down) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.","Start out by curling your wrist upwards and exhaling.","Slowly lower your wrists back down to the starting position while inhaling.","Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.","Repeat for the recommended amount of repetitions."]', NULL, '["Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench/0.jpg","Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Palms-Down_Wrist_Curl_Over_A_Bench', 'Palms-Down Wrist Curl Over A Bench', 'lower arms', 'forearms', '[]', 'barbell', 'strength', 'beginner', '["Start out by placing a barbell on one side of a flat bench.","Kneel down on both of your knees so that your body is facing the flat bench.","Use your arms to grab the barbell with a pronated grip (palms down) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.","Start out by curling your wrist upwards and exhaling.","Slowly lower your wrists back down to the starting position while inhaling.","Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.","Repeat for the recommended amount of repetitions."]', NULL, '["Palms-Down_Wrist_Curl_Over_A_Bench/0.jpg","Palms-Down_Wrist_Curl_Over_A_Bench/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench', 'Palms-Up Dumbbell Wrist Curl Over A Bench', 'lower arms', 'forearms', '[]', 'dumbbell', 'strength', 'beginner', '["Start out by placing two dumbbells on one side of a flat bench.","Kneel down on both of your knees so that your body is facing the flat bench.","Use your arms to grab both of the dumbbells with a supinated grip (palms up) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge.","Start out by curling your wrist upwards and exhaling.","Slowly lower your wrists back down to the starting position while inhaling. Make sure to inhale during this part of the exercise.","Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.","Repeat for the recommended amount of repetitions."]', NULL, '["Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench/0.jpg","Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Parallel_Bar_Dip', 'Parallel Bar Dip', 'upper arms', 'triceps', '["chest","shoulders"]', 'other', 'strength', 'beginner', '["Stand between a set of parallel bars. Place a hand on each bar, and then take a small jump to help you get into the starting position with your arms locked out.","Begin by flexing the elbow, lowering your body until your arms break 90 degrees. Avoid swinging, and maintain good posture throughout the descent.","Reverse the motion by extending the elbow, pushing yourself back up into the starting position.","Repeat for the desired number of repetitions."]', NULL, '["Parallel_Bar_Dip/0.jpg","Parallel_Bar_Dip/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Pelvic_Tilt_Into_Bridge', 'Pelvic Tilt Into Bridge', 'back', 'lower back', '[]', 'body only', 'stretching', 'intermediate', '["Lie down with your feet on the floor, heels directly under your knees.","Lift only your tailbone to the ceiling to stretch your lower back. (Don''t lift the entire spine yet.) Pull in your stomach.","To go into a bridge, lift the entire spine except the neck."]', NULL, '["Pelvic_Tilt_Into_Bridge/0.jpg","Pelvic_Tilt_Into_Bridge/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Peroneals-SMR', 'Peroneals-SMR', 'lower legs', 'calves', '[]', 'foam roll', 'stretching', 'intermediate', '["Lay on your side, supporting your weight on your forearm and on a foam roller placed on the outside of your lower leg. Your upper leg can either be on top of your lower leg, or you can cross it in front of you. This will be your starting position.","Raise your hips off of the ground and begin to roll from below the knee to above the ankle on the side of your leg, pausing at points of tension for 10-30 seconds. Repeat on the other leg."]', NULL, '["Peroneals-SMR/0.jpg","Peroneals-SMR/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Peroneals_Stretch', 'Peroneals Stretch', 'lower legs', 'calves', '[]', 'other', 'stretching', 'intermediate', '["In a seated position, loop a belt, rope, or band around one foot. This will be your starting position.","With the leg extended and the heel off of the ground, pull on the belt so that the foot is inverted, with the inside of the foot being pulled towards you. Hold for 10-20 seconds, and then switch sides."]', NULL, '["Peroneals_Stretch/0.jpg","Peroneals_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Physioball_Hip_Bridge', 'Physioball Hip Bridge', 'upper legs', 'glutes', '["hamstrings"]', 'exercise ball', 'strength', 'beginner', '["Lay on a ball so that your upper back is on the ball with your hips unsupported. Both feet should be flat on the floor, hip width apart or wider. This will be your starting position.","Begin by extending the hips using your glutes and hamstrings, raising your hips upward as you bridge.","Pause at the top of the motion and return to the starting position."]', NULL, '["Physioball_Hip_Bridge/0.jpg","Physioball_Hip_Bridge/1.jpg"]', 5, 'sets', 0, 'fedb', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('fe-Pin_Presses', 'Pin Presses', 'upper arms', 'triceps', '["chest","forearms","lats","middle back","shoulders"]', 'barbell', 'powerlifting', 'intermediate', '["Pin presses remove the eccentric phase of the bench press, developing starting strength. They also allow you to train a desired range of motion.","The bench should be set up in a power rack. Set the pins to the desired point in your range of motion, whether it just be lockout or an inch off of your chest. The bar should be moved to the pins and prepared for lifting.","Begin by lying on the bench, with the bar directly above the contact point during your regular bench. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement.","You can take a standard bench grip, or shoulder width to focus on the triceps. The bar, wrist, and elbow should stay in line at all times. Focus on squeezing the bar and trying to pull it apart.","Drive the bar up with as much force as possible. The elbows should be tucked in until lockout.","Return the bar to the pins, pausing before beginning the next repetition."]', NULL, '["Pin_Presses/0.jpg","Pin_Presses/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Piriformis-SMR', 'Piriformis-SMR', 'upper legs', 'glutes', '[]', 'foam roll', 'stretching', 'intermediate', '["Sit with your buttocks on top of a foam roll. Bend your knees, and then cross one leg so that the ankle is over the knee. This will be your starting position.","Shift your weight to the side of the crossed leg, rolling over the buttocks until you feel tension in your upper glute. You may assist the stretch by using one hand to pull the bent knee towards your chest. Hold this position for 10-30 seconds, and then switch sides."]', NULL, '["Piriformis-SMR/0.jpg","Piriformis-SMR/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Plank', 'Plank', 'waist', 'abdominals', '[]', 'body only', 'strength', 'beginner', '["Get into a prone position on the floor, supporting your weight on your toes and your forearms. Your arms are bent and directly below the shoulder.","Keep your body straight at all times, and hold this position as long as possible. To increase difficulty, an arm or leg can be raised."]', NULL, '["Plank/0.jpg","Plank/1.jpg"]', 5, 'sets', 1, 'fedb', 1),
('fe-Plate_Pinch', 'Plate Pinch', 'lower arms', 'forearms', '[]', 'other', 'strength', 'intermediate', '["Grab two wide-rimmed plates and put them together with the smooth sides facing outward","Use your fingers to grip the outside part of the plate and your thumb for the other side thus holding both plates together. This is the starting position.","Squeeze the plate with your fingers and thumb. Hold this position for as long as you can.","Repeat for the recommended amount of sets prescribed in your program.","Switch arms and repeat the movements."]', NULL, '["Plate_Pinch/0.jpg","Plate_Pinch/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Plate_Twist', 'Plate Twist', 'waist', 'abdominals', '[]', 'other', 'strength', 'intermediate', '["Lie down on the floor or an exercise mat with your legs fully extended and your upper body upright. Grab the plate by its sides with both hands out in front of your abdominals with your arms slightly bent.","Slowly cross your legs near your ankles and lift them up off the ground. Your knees should also be bent slightly. Note: Move your upper body back slightly to help keep you balanced turning this exercise. This is the starting position.","Move the plate to the left side and touch the floor with it. Breathe out as you perform that movement.","Come back to the starting position as you breathe in and then repeat the movement but this time to the right side of the body. Tip: Use a slow controlled movement at all times. Jerking motions can injure the back.","Repeat for the recommended amount of repetitions."]', NULL, '["Plate_Twist/0.jpg","Plate_Twist/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Platform_Hamstring_Slides', 'Platform Hamstring Slides', 'upper legs', 'hamstrings', '["glutes"]', 'other', 'strength', 'beginner', '["For this movement a wooden floor or similar is needed. Lay on your back with your legs extended. Place a gym towel or a light weight underneath your heel. This will be your starting position.","Begin the movement by flexing the knee, keeping your other leg straight.","Continue bringing the heel closer to you, sliding it on the floor.","At full knee flexion, reverse the movement to return to the starting position."]', NULL, '["Platform_Hamstring_Slides/0.jpg","Platform_Hamstring_Slides/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Plie_Dumbbell_Squat', 'Plie Dumbbell Squat', 'upper legs', 'quadriceps', '["abdominals","calves","glutes","hamstrings"]', 'dumbbell', 'strength', 'beginner', '["Hold a dumbbell at the base with both hands and stand straight up. Move your legs so that they are wider than shoulder width apart from each other with your knees slightly bent.","Your toes should be facing out. Note: Your arms should be stationary while performing the exercise. This is the starting position.","Slowly bend the knees and lower your legs until your thighs are parallel to the floor. Make sure to inhale as this is the eccentric part of the exercise.","Press mainly with the heel of the foot to bring the body back to the starting position while exhaling.","Repeat for the recommended amount of repetitions."]', NULL, '["Plie_Dumbbell_Squat/0.jpg","Plie_Dumbbell_Squat/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Plyo_Kettlebell_Pushups', 'Plyo Kettlebell Pushups', 'chest', 'chest', '["shoulders","triceps"]', 'kettlebells', 'strength', 'expert', '["Place a kettlebell on the floor. Place yourself in a pushup position, on your toes with one hand on the ground and one hand holding the kettlebell, with your elbows extended. This will be your starting position.","Begin by lowering yourself as low as you can, keeping your back straight.","Quickly and forcefully reverse direction, pushing yourself up to the other side of the kettlebell, switching hands as you do so. Continue the movement by descending and repeating the movement back and forth."]', NULL, '["Plyo_Kettlebell_Pushups/0.jpg","Plyo_Kettlebell_Pushups/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Posterior_Tibialis_Stretch', 'Posterior Tibialis Stretch', 'lower legs', 'calves', '[]', 'other', 'stretching', 'intermediate', '["In a seated position, loop a belt, rope, or band around one foot. This will be your starting position.","With the leg extended and the heel off of the ground, pull on the belt so that the foot is everted, with the outside of the foot being pulled towards you. Hold for 10-20 seconds, and then switch sides."]', NULL, '["Posterior_Tibialis_Stretch/0.jpg","Posterior_Tibialis_Stretch/1.jpg"]', 2.3, 'time', 0, 'fedb', 1),
('fe-Power_Clean_from_Blocks', 'Power Clean from Blocks', 'upper legs', 'hamstrings', '["quadriceps"]', 'barbell', 'olympic weightlifting', 'intermediate', '["With a barbell on boxes of the desired height, take a grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.","Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. As the bar approaches the mid-thigh position, begin extending through the hips.","In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight. At the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.","As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, pull yourself under the bar far enough that it can be racked onto the shoulders, rotating your elbows under the bar as you do so. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed.","Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position, and complete the repetition by returning the weight to the boxes."]', NULL, '["Power_Clean_from_Blocks/0.jpg","Power_Clean_from_Blocks/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Power_Jerk', 'Power Jerk', 'upper legs', 'quadriceps', '["abdominals","calves","glutes","hamstrings","shoulders","triceps"]', 'barbell', 'olympic weightlifting', 'expert', '["Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible.","Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders.","At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as possible. In the brief moment the feet are not actively driving against the platform, the athletes effort to push the bar up will drive them down. The feet should be moved to a slightly wider stance, with the knees partially bent.","Receive the bar with the arms locked out overhead.","Return to a standing position."]', NULL, '["Power_Jerk/0.jpg","Power_Jerk/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Power_Partials', 'Power Partials', 'shoulders', 'shoulders', '[]', 'dumbbell', 'strength', 'beginner', '["Stand up with your torso upright and a dumbbell on each hand being held at arms length. The elbows should be close to the torso.","The palms of the hands should be facing your torso. Your feet should be about shoulder width apart. This will be your starting position.","Keeping your arms straight and the torso stationary, lift the weights out to your sides until they are about shoulder level height while exhaling.","Feel the contraction for a second and begin to lower the weights back down to the starting position while inhaling. Tip: Keep the palms facing down with the little finger slightly higher while lifting and lowering the weights as it will concentrate the stress on your shoulders mainly.","Repeat for the recommended amount of repetitions."]', NULL, '["Power_Partials/0.jpg","Power_Partials/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Power_Snatch', 'Power Snatch', 'upper legs', 'hamstrings', '["calves","glutes","lower back","quadriceps","shoulders","traps","triceps"]', 'barbell', 'olympic weightlifting', 'expert', '["Begin with a loaded barbell on the floor. The bar should be close to or touching the shins, and a wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar. This will be the starting position.","Begin the first pull by driving through the front of the heels, raising the bar from the ground. The back angle should stay the same until the bar passes the knees.","Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the shoulders and allow the elbows to flex to the side.","As you move your feet into the receiving position, a slightly wider position, pull yourself below the bar as you elevate the bar overhead. The bar should be received in a partial squat. Continue raising the bar to the overhead position, receiving the bar locked out overhead.","Return to a standing position with the weight over head."]', NULL, '["Power_Snatch/0.jpg","Power_Snatch/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Power_Snatch_from_Blocks', 'Power Snatch from Blocks', 'upper legs', 'quadriceps', '["calves","forearms","glutes","hamstrings","lower back","shoulders","traps","triceps"]', 'barbell', 'olympic weightlifting', 'intermediate', '["Begin with a loaded barbell on boxes or stands of the desired height. A wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar, with the elbows pointed out. This will be the starting position.","Begin the first pull by driving through the front of the heels, raising the bar from the boxes.","Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the shoulders and allow the elbows to flex to the side.","As you move your feet into the receiving position, forcefully pull yourself below the bar as you elevate the bar overhead. The feet should move to just outside the hips, turned out as necessary. Receive the bar above a full squat and with the arms fully extended overhead.","Keeping the bar aligned over the front of the heels, your head and chest up, drive through heels of the feet to move to a standing position. Carefully return the weight to the boxes."]', NULL, '["Power_Snatch_from_Blocks/0.jpg","Power_Snatch_from_Blocks/1.jpg"]', 6, 'sets', 0, 'fedb', 1),
('fe-Power_Stairs', 'Power Stairs', 'upper legs', 'hamstrings', '["adductors","calves","glutes","lower back","quadriceps","shoulders","traps"]', 'other', 'strongman', 'intermediate', '["In the power stairs, implements are moved up a staircase. For training purposes, these can be performed with a tire or box.","Begin by taking the implement with both hands. Set your feet wide, with your head and chest up. Drive through the ground with your heels, extending your knees and hips to raise the weight from the ground.","As you lean back, attempt to swing the weight onto the stairs, which are usually around 16-18\" high. You can use your legs to help push the weight onto the stair.","Repeat for 3-5 repetitions, and continue with a heavier weight, moving as fast as possible."]', NULL, '["Power_Stairs/0.jpg","Power_Stairs/1.jpg"]', 9, 'sets', 0, 'fedb', 1),
('fe-Preacher_Curl', 'Preacher Curl', 'upper arms', 'biceps', '[]', 'barbell', 'strength', 'beginner', '["To perform this movement you will need a preacher bench and an E-Z bar. Grab the E-Z curl bar at the close inner handle (either have someone hand you the bar which is preferable or grab the bar from the front bar rest provided by most preacher benches). The palm of your hands should be facing forward and they should be slightly tilted inwards due to the shape of the bar.","With the upper arms positioned against the preacher bench pad and the chest against it, hold the E-Z Curl Bar at shoulder length. This will be your starting position.","As you breathe in, slowly lower the bar until your upper arm is extended and the biceps is fully stretched.","As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the bar is at shoulder height. Squeeze the biceps hard and hold this position for a second.","Repeat for the recommended amount of repetitions."]', NULL, '["Preacher_Curl/0.jpg","Preacher_Curl/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Press_Sit-Up', 'Press Sit-Up', 'waist', 'abdominals', '["chest","shoulders","triceps"]', 'barbell', 'strength', 'expert', '["To begin, lie down on a bench with a barbell resting on your chest. Position your legs so they are secure on the extension of the abdominal bench. This is the starting position.","While inhaling, tighten your abdominals and glutes. Simultaneously curl your torso as you do when performing a sit-up and press the barbell to an overhead position while exhaling. Tip: Use your arms to push the barbell out as you perform this exercise while still focusing on the abdominal muscles.","Lower your upper body back down to the starting position while bringing the barbell back down to your torso. Remember to breathe in while lowering the body.","Repeat for the recommended amount of repetitions."]', NULL, '["Press_Sit-Up/0.jpg","Press_Sit-Up/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Prone_Manual_Hamstring', 'Prone Manual Hamstring', 'upper legs', 'hamstrings', '[]', 'body only', 'strength', 'beginner', '["You will need a partner for this exercise. Lay face down with your legs straight. Your assistant will place their hand on your heel.","To begin, flex the knee to curl your leg up. Your partner should provide resistance, starting light and increasing the pressure as the movement is completed. Communicate with your partner to monitor appropriate resistance levels.","Pause at the top, returning the leg to the starting position as your partner provides resistance going the other direction."]', NULL, '["Prone_Manual_Hamstring/0.jpg","Prone_Manual_Hamstring/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Prowler_Sprint', 'Prowler Sprint', 'cardio', 'hamstrings', '["calves","chest","glutes","quadriceps","shoulders"]', 'other', 'cardio', 'beginner', '["Place your sled on an appropriate surface, loaded to a suitable weight. The sled should provide enough resistance to require effort, but not so heavy that you are significantly slowed down.","You may use the upright or the low handles for this exercise. Place your hands on the handles with your arms extended, leaning into the implement.","With good posture, drive through the ground with alternating, short steps. Move as fast as you can for a short distance."]', NULL, '["Prowler_Sprint/0.jpg","Prowler_Sprint/1.jpg"]', 9.8, 'time', 0, 'fedb', 1),
('fe-Pull_Through', 'Pull Through', 'upper legs', 'glutes', '["hamstrings","lower back"]', 'cable', 'strength', 'beginner', '["Begin standing a few feet in front of a low pulley with a rope or handle attached. Face away from the machine, straddling the cable, with your feet set wide apart.","Begin the movement by reaching through your legs as far as possible, bending at the hips. Keep your knees slightly bent. Keeping your arms straight, extend through the hip to stand straight up. Avoid pulling upward through the shoulders; all of the motion should originate through the hips."]', NULL, '["Pull_Through/0.jpg","Pull_Through/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Pullups', 'Pullups', 'back', 'lats', '["biceps","middle back"]', 'body only', 'strength', 'beginner', '["Grab the pull-up bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.","As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.","Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.","After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.","Repeat this motion for the prescribed amount of repetitions."]', NULL, '["Pullups/0.jpg","Pullups/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Push-Up_Wide', 'Push-Up Wide', 'chest', 'chest', '["abdominals","shoulders","triceps"]', 'body only', 'strength', 'beginner', '["With your hands wide apart, support your body on your toes and hands in a plank position. Your elbows should be extended and your body straight. Do not allow your hips to sag. This will be your starting position.","To begin, allow the elbows to flex, lowering your chest to the floor as you inhale.","Using your pectoral muscles, press your upper body back up to the starting position by extending the elbows. Exhale as you perform this step.","After pausing at the contracted position, repeat the movement for the prescribed amount of repetitions."]', NULL, '["Push-Up_Wide/0.jpg","Push-Up_Wide/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Push-Ups_-_Close_Triceps_Position', 'Push-Ups - Close Triceps Position', 'upper arms', 'triceps', '["chest","shoulders"]', 'body only', 'strength', 'intermediate', '["Lie on the floor face down and place your hands closer than shoulder width for a close hand position. Make sure that you are holding your torso up at arms'' length.","Lower yourself until your chest almost touches the floor as you inhale.","Using your triceps and some of your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step.","After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions."]', NULL, '["Push-Ups_-_Close_Triceps_Position/0.jpg","Push-Ups_-_Close_Triceps_Position/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Push-Ups_With_Feet_Elevated', 'Push-Ups With Feet Elevated', 'chest', 'chest', '["shoulders","triceps"]', 'body only', 'strength', 'beginner', '["Lie on the floor face down and place your hands about 36 inches apart from each other holding your torso up at arms length.","Place your toes on top of a flat bench. This will allow your body to be elevated. Note: The higher the elevation of the flat bench, the higher the resistance of the exercise is.","Lower yourself until your chest almost touches the floor as you inhale.","Using your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step.","After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions."]', NULL, '["Push-Ups_With_Feet_Elevated/0.jpg","Push-Ups_With_Feet_Elevated/1.jpg"]', 5, 'sets', 0, 'fedb', 1),
('fe-Push-Ups_With_Feet_On_An_Exercise_Ball', 'Push-Ups With Feet On An Exercise Ball', 'chest', 'chest', '["shoulders","triceps"]', 'exercise ball', 'strength', 'intermediate', '["Lie on the floor face down and place your hands about 36 inches apart from each other holding your torso up at arms length.","Place your toes on top of an exercise ball. This will allow your body to be elevated.","Lower yourself until your chest almost touches the floor as you inhale.","Using your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step.","After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions."]', NULL, '["Push-Ups_With_Feet_On_An_Exercise_Ball/0.jpg","Push-Ups_With_Feet_On_An_Exercise_Ball/1.jpg"]', 5, 'sets', 0, 'fedb', 1)
